: "{{\\n  config(\\n    materialized = 'incremental',\\n    unique_key='uuid',\\n    on_schema_change='append_new_columns',\\n    post_hook='delete from {{this}} where _deleted=true',\\n    indexes=[\\n      {'columns': ['uuid'], 'type': 'hash'},\\n      {'columns': ['saved_timestamp']},\\n      {'columns': ['doc_type']},\\n      {'columns': ['_deleted']},\\n    ]\\n  )\\n}}\\n\\nSELECT\\n  _id as uuid,\\n  _deleted,\\n  saved_timestamp,\\n  doc->>'type' as doc_type\\nfrom {{ source('couchdb', env_var('POSTGRES_TABLE')) }} source_table\\n{% if is_incremental() %}\\nWHERE source_table.saved_timestamp >= {{ max_existing_timestamp('saved_timestamp') }}\\n{% endif %}", "unique_id": "model.cht_pipeline_base.document_metadata", "build_path": null, "created_at": 1758839282.8238616, "depends_on": {"nodes": ["source.cht_pipeline_base.couchdb.medic"], "macros": ["macro.dbt.is_incremental"]}, "doc_blocks": [], "patch_path": "cht_pipeline_base://models/root/root.yml", "time_spine": null, "constraints": [], "description": "", "primary_key": [], "package_name": "cht_pipeline_base", "compiled_path": null, "relation_name": "\\"data\\".\\"v1\\".\\"document_metadata\\"", "resource_type": "model", "latest_version": null, "deprecation_date": null, "unrendered_config": {"indexes": [{"type": "hash", "columns": ["uuid"]}, {"columns": ["saved_timestamp"]}, {"columns": ["doc_type"]}, {"columns": ["_deleted"]}], "contract": {"enforced": true}, "post-hook": "delete from {{this}} where _deleted=true", "unique_key": "uuid", "materialized": "incremental", "on_schema_change": "append_new_columns"}, "original_file_path": "models/root/document_metadata.sql"}, "model.cht_pipeline_base.monitoring_messages": {"fqn": ["cht_pipeline_base", "forms", "monitoring_messages"], "docs": {"show": true, "node_color": null}, "meta": {}, "name": "monitoring_messages", "path": "forms/monitoring_messages.sql", "refs": [{"name": "document_metadata", "package": null, "version": null}], "tags": ["monitoring"], "alias": "monitoring_messages", "group": null, "access": "protected", "config": {"docs": {"show": true, "node_color": null}, "meta": {}, "tags": ["monitoring"], "alias": null, "begin": null, "group": null, "access": "protected", "grants": {}, "schema": null, "enabled": true, "indexes": [{"type": "hash", "columns": ["uuid"]}, {"columns": ["from_phone"]}, {"columns": ["message_timestamp"]}, {"columns": ["message_health"]}], "quoting": {}, "contract": {"enforced": true, "alias_types": true}, "database": null, "lookback": 1, "packages": [], "pre-hook": [], "freshness": null, "post-hook": [{"sql": "\\n      DO $$\\n      DECLARE\\n        record_count INTEGER;\\n        phone_numbers TEXT;\\n      BEGIN\\n        SELECT COUNT(*) INTO record_count FROM {{ this }};\\n        SELECT STRING_AGG(DISTINCT from_phone, ', ') INTO phone_numbers \\n        FROM {{ this }};\\n        \\n        RAISE NOTICE '=== MONITORING MESSAGES PROCESSING COMPLETE ===';\\n        RAISE NOTICE 'Total records processed: %', record_count;\\n        RAISE NOTICE 'Phone numbers found: %', COALESCE(phone_numbers, 'NONE');\\n        RAISE NOTICE '==============================================';\\n      END $$;\\n    ", "index": null, "transaction": true}], "batch_size": null, "event_time": null, "unique_key": "uuid", "column_types": {}, "full_refresh": null, "materialized": "incremental", "persist_docs": {}, "on_schema_change": "append_new_columns", "concurrent_batches": null, "incremental_strategy": null, "on_configuration_change": "apply"}, "schema": "v1", "columns": {"uuid": {"meta": {}, "name": "uuid", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "string", "doc_blocks": [], "constraints": [{"to": null, "name": null, "type": "foreign_key", "expression": "v1.document_metadata (uuid) ON DELETE CASCADE", "to_columns": [], "warn_unenforced": true, "warn_unsupported": true}, {"to": null, "name": null, "type": "unique", "expression": null, "to_columns": [], "warn_unenforced": true,