e", "path": "macros/_utils/modules_datetime.sql", "arguments": [], "macro_sql": "{% macro datetime(year, month, day, hour=0, minute=0, second=0, microsecond=0, tz=None) %}\\n    {% set tz = tz if tz else var(\\"dbt_date:time_zone\\") %}\\n    {{ return(\\n        modules.datetime.datetime(\\n            year=year, month=month, day=day, hour=hour,\\n            minute=minute, second=second, microsecond=microsecond,\\n            tzinfo=modules.pytz.timezone(tz)\\n        )\\n    ) }}\\n{% endmacro %}", "unique_id": "macro.dbt_date.datetime", "created_at": 1758839281.1312702, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/_utils/modules_datetime.sql", "supported_languages": null}, "macro.dbt_date.day_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "day_name", "path": "macros/calendar_date/day_name.sql", "arguments": [], "macro_sql": "{%- macro day_name(date, short=True) -%}\\n    {{ adapter.dispatch('day_name', 'dbt_date') (date, short) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.day_name", "created_at": 1758839281.1461918, "depends_on": {"macros": ["macro.dbt_date.postgres__day_name"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_name.sql", "supported_languages": null}, "macro.dbt_date.tomorrow": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "tomorrow", "path": "macros/calendar_date/tomorrow.sql", "arguments": [], "macro_sql": "{%- macro tomorrow(date=None, tz=None) -%}\\n{{ dbt_date.n_days_away(1, date, tz) }}\\n{%- endmacro -%}", "unique_id": "macro.dbt_date.tomorrow", "created_at": 1758839281.1610713, "depends_on": {"macros": ["macro.dbt_date.n_days_away"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/tomorrow.sql", "supported_languages": null}, "macro.dbt_date.week_end": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "week_end", "path": "macros/calendar_date/week_end.sql", "arguments": [], "macro_sql": "{%- macro week_end(date=None, tz=None) -%}\\n{%-set dt = date if date else dbt_date.today(tz) -%}\\n{{ adapter.dispatch('week_end', 'dbt_date') (dt) }}\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_date.week_end", "created_at": 1758839281.1438968, "depends_on": {"macros": ["macro.dbt_date.today", "macro.dbt_date.postgres__week_end"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_end.sql", "supported_languages": null}, "macro.dbt_utils.slugify": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "slugify", "path": "macros/jinja_helpers/slugify.sql", "arguments": [], "macro_sql": "{% macro slugify(string) %}\\n\\n{#- Lower case the string -#}\\n{% set string = string | lower %}\\n{#- Replace spaces and dashes with underscores -#}\\n{% set string = modules.re.sub('[ -]+', '_', string) %}\\n{#- Only take letters, numbers, and underscores -#}\\n{% set string = modules.re.sub('[^a-z0-9_]+', '', string) %}\\n{#- Prepends \\"_\\" if string begins with a number -#}\\n{% set string = modules.re.sub('^[0-9]', '_' + string[0], string) %}\\n\\n{{ return(string) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.slugify", "created_at": 1758839281.3093622, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/jinja_helpers/slugify.sql", "supported_languages": null}, "macro.dbt_utils.unpivot": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "unpivot", "path": "macros/sql/unpivot.sql", "arguments": [], "macro_sql": "{% macro unpivot(relation=none, cast_to='varchar', exclude=none, remove=none, field_name='field_name', value_name='value') -%}\\n    {{ return(adapter.dispatch('unpivot', 'dbt_utils')(relation, cast_to, exclude, remove, field_name, value_name)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.unpivot", "created_at": 1758839281.2314563, "depends_on": {"macros": ["macro.dbt_utils.default__unpivot"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/unpivot.sql", "supported_languages": null}, "macro.dbt.create_columns": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "create_columns", "path": "macros/materializations/snapshots/helpers.sql", "arguments": [], "macro_sql": "{% macro create_columns(relation, columns) %}\\n  {{ adapter.dispatch('create_columns', 'dbt')(relation, columns) }}\\n{% endmacro %}", "unique_id": "macro.dbt.create_columns", "created_at": 1758839280.8406684, "depends_on": {"macros": ["macro.dbt.default__create_columns"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/helpers.sql", "supported_languages": null}, "macro.dbt.create_indexes": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "create_indexes", "path": "macros/adapters/indexes.sql", "arguments": [], "macro_sql": "{% macro create_indexes(relation) -%}\\n  {{ adapter.dispatch('create_indexes', 'dbt')(relation) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.create_indexes", "created_at": 1758839280.9980357, "depends_on": {"macros": ["macro.dbt.default__create_indexes"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/indexes.sql", "supported_languages": null}, "macro.dbt.create_view_as": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "create_view_as", "path": "macros/relations/view/create.sql", "arguments": [], "macro_sql": "{% macro create_view_as(relation, sql) -%}\\n  {{ adapter.dispatch('create_view_as', 'dbt')(relati