chema_changes_dict['new_target_types'] -%}\\n\\n     {% if add_to_target_arr | length > 0 or remove_from_target_arr | length > 0 %}\\n       {%- do alter_relation_add_remove_columns(target_relation, add_to_target_arr, remove_from_target_arr) -%}\\n     {% endif %}\\n\\n     {% if new_target_types != [] %}\\n       {% for ntt in new_target_types %}\\n         {% set column_name = ntt['column_name'] %}\\n         {% set new_type = ntt['new_type'] %}\\n         {% do alter_column_type(target_relation, column_name, new_type) %}\\n       {% endfor %}\\n     {% endif %}\\n\\n  {% endif %}\\n\\n  {% set schema_change_message %}\\n    In {{ target_relation }}:\\n        Schema change approach: {{ on_schema_change }}\\n        Columns added: {{ add_to_target_arr }}\\n        Columns removed: {{ remove_from_target_arr }}\\n        Data types changed: {{ new_target_types }}\\n  {% endset %}\\n\\n  {% do log(schema_change_message) %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.sync_column_schemas", "created_at": 1758839280.920916, "depends_on": {"macros": ["macro.dbt.alter_relation_add_remove_columns", "macro.dbt.alter_column_type"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/on_schema_change.sql", "supported_languages": null}, "macro.dbt_date.get_base_dates": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_base_dates", "path": "macros/get_base_dates.sql", "arguments": [], "macro_sql": "{% macro get_base_dates(start_date=None, end_date=None, n_dateparts=None, datepart=\\"day\\") %}\\n    {{ adapter.dispatch('get_base_dates', 'dbt_date') (start_date, end_date, n_dateparts, datepart) }}\\n{% endmacro %}", "unique_id": "macro.dbt_date.get_base_dates", "created_at": 1758839281.1113505, "depends_on": {"macros": ["macro.dbt_date.default__get_base_dates"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/get_base_dates.sql", "supported_languages": null}, "macro.dbt_date.iso_week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "iso_week_start", "path": "macros/calendar_date/iso_week_start.sql", "arguments": [], "macro_sql": "{%- macro iso_week_start(date=None, tz=None) -%}\\n{%-set dt = date if date else dbt_date.today(tz) -%}\\n{{ adapter.dispatch('iso_week_start', 'dbt_date') (dt) }}\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_date.iso_week_start", "created_at": 1758839281.1505625, "depends_on": {"macros": ["macro.dbt_date.today", "macro.dbt_date.postgres__iso_week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_start.sql", "supported_languages": null}, "macro.dbt_utils._is_ephemeral": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "_is_ephemeral", "path": "macros/jinja_helpers/_is_ephemeral.sql", "arguments": [], "macro_sql": "{% macro _is_ephemeral(obj, macro) %}\\n    {%- if obj.is_cte -%}\\n        {% set ephemeral_prefix = api.Relation.add_ephemeral_prefix('') %}\\n        {% if obj.name.startswith(ephemeral_prefix) %}\\n            {% set model_name = obj.name[(ephemeral_prefix|length):] %}\\n        {% else %}\\n            {% set model_name = obj.name %}\\n        {%- endif -%}\\n        {% set error_message %}\\nThe `{{ macro }}` macro cannot be used with ephemeral models, as it relies on the information schema.\\n\\n`{{ model_name }}` is an ephemeral model. Consider making it a view or table instead.\\n        {% endset %}\\n        {%- do exceptions.raise_compiler_error(error_message) -%}\\n    {%- endif -%}\\n{% endmacro %}", "unique_id": "macro.dbt_utils._is_ephemeral", "created_at": 1758839281.3047607, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/jinja_helpers/_