k, 1, current_date)\\"\\n) #}\\n\\n\\nwith rawdata as (\\n\\n    {{\\n        dbt_date.generate_series(\\n            dbt_date.get_intervals_between(start_date, end_date, datepart)\\n        )\\n    }}\\n\\n),\\n\\nall_periods as (\\n\\n    select (\\n        {{\\n            dbt.dateadd(\\n                datepart,\\n                \\"(row_number() over (order by 1) - 1)\\",\\n                start_date\\n            )\\n        }}\\n    ) as date_{{datepart}}\\n    from rawdata\\n\\n),\\n\\nfiltered as (\\n\\n    select *\\n    from all_periods\\n    where date_{{datepart}} <= {{ end_date }}\\n\\n)\\n\\nselect * from filtered\\n\\n{% endmacro %}", "unique_id": "macro.dbt_date.default__date_spine", "created_at": 1758839281.1295996, "depends_on": {"macros": ["macro.dbt_date.generate_series", "macro.dbt_date.get_intervals_between", "macro.dbt.dateadd"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/_utils/date_spine.sql", "supported_languages": null}, "macro.dbt_date.default__month_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__month_name", "path": "macros/calendar_date/month_name.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__month_name(date, short) -%}\\n{%- set f = 'MON' if short else 'MONTH' -%}\\n    to_char({{ date }}, '{{ f }}')\\n{%- endmacro %}", "unique_id": "macro.dbt_date.default__month_name", "created_at": 1758839281.162379, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/month_name.sql", "supported_languages": null}, "macro.dbt_date.default__week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__week_start", "path": "macros/calendar_date/week_start.sql", "arguments": [], "macro_sql": "{%- macro default__week_start(date) -%}\\ncast({{ dbt.date_trunc('week', date) }} as date)\\n{