ported_languages": null}, "macro.dbt_date.duckdb__week_of_year": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "duckdb__week_of_year", "path": "macros/calendar_date/week_of_year.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro duckdb__week_of_year(date) -%}\\ncast(ceil(dayofyear({{ date }}) / 7) as int)\\n{%- endmacro %}", "unique_id": "macro.dbt_date.duckdb__week_of_year", "created_at": 1758839281.1598008, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_of_year.sql", "supported_languages": null}, "macro.dbt_date.postgres__month_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__month_name", "path": "macros/calendar_date/month_name.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro postgres__month_name(date, short) -%}\\n{# FM = Fill mode, which suppresses padding blanks #}\\n{%- set f = 'FMMon' if short else 'FMMonth' -%}\\n    to_char({{ date }}, '{{ f }}')\\n{%- endmacro %}", "unique_id": "macro.dbt_date.postgres__month_name", "created_at": 1758839281.1635888, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/month_name.sql", "supported_languages": null}, "macro.dbt_date.postgres__week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__week_start", "path": "macros/calendar_date/week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro postgres__week_start(date) -%}\\n-- Sunday as week start date\\ncast({{ dbt.dateadd('day', -1, dbt.date_trunc('week', dbt.dateadd('day', 1, date))) }} as date)\\n{%- endmacro %}", "unique_id": "macro.dbt_date.postgres__week_start", "created_at": 1758839281.175838, "depends_on": {"macros": ["macro.dbt.dateadd", "macro.dbt.date_trunc"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_start.sql", "supported_languages": null}, "macro.dbt_utils.default__date_spine": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__date_spine", "path": "macros/sql/date_spine.sql", "arguments": [], "macro_sql": "{% macro default__date_spine(datepart, start_date, end_date) %}\\n\\n\\n{# call as follows:\\n\\ndate_spine(\\n    \\"day\\",\\n    \\"to_date('01/01/2016', 'mm/dd/yyyy')\\",\\n    \\"dbt.dateadd(week, 1, current_date)\\"\\n) #}\\n\\n\\nwith rawdata as (\\n\\n    {{dbt_utils.generate_series(\\n        dbt_utils.get_intervals_between(start_date, end_date, datepart)\\n    )}}\\n\\n),\\n\\nall_periods as (\\n\\n    select (\\n        {{\\n            dbt.dateadd(\\n                datepart,\\n                \\"row_number() over (order by 1) - 1\\",\\n                start_date\\n            )\\n        }}\\n    ) as date_{{datepart}}\\n    from rawdata\\n\\n),\\n\\nfiltered as (\\n\\n    select *\\n    from all_periods\\n    where date_{{datepart}} <= {{ end_date }}\\n\\n)\\n\\nselect * from filtered\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__date_spine", "created_at": 1758839281.1945596, "depends_on": {"macros": ["macro.dbt_utils.generate_series", "macro.dbt_utils.get_intervals_between", "macro.dbt.dateadd"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/date_spine.sql", "supported_languages": null}, "macro.dbt_utils.get_table_types_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_table_types_sql", "path": "macros/sql/get_table_types_sql.sql", "arguments": [], "macro_sql": "{%- macro get_table_types_sql() -%}\\n  {{ return(adapter.dispatch('get_table_types_sql', 'dbt_utils')()) }}\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_utils.get_table_types_sql", "created_at": 1758839281.2358925, "depends_on": {"macros": ["macro.dbt_utils.postgres__get_table_types_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_table_types_sql.sql", "supported_languages": null}, "macro.dbt_utils.test_accepted_range": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_accepted_range", "path": "macros/generic_tests/accepted_range.sql", "arguments": [], "macro_sql": "{% test accepted_range(model, column_name, min_value=none, max_value=none, inclusive=true) %}\\n  {{ return(adapter.dispatch('test_accepted_range', 'dbt_utils')(model, column_name, min_value, max_value, inclusive)) }}\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_accepted_range", "created_at": 1758839281.2814415, "depends_on": {"macros": ["macro.dbt_utils.default__test_accepted_range"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/accepted_range.sql", "supported_languages": null}, "macro.dbt_utils.test_equal_rowcount": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_equal_rowcount", "path": "macros/generic_tests/equal_rowcount.sql", "arguments": [], "macro_sql": "{% test equal_rowcount(model, compare_model, group_by_columns = []) %}\\n  {{ return(adapter.dispatch('test_equal_rowcount', 'dbt_utils')(model, compare_model, group_by_columns)) }}\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_equal_rowcount", "created_at": 1758839281.297647, "depends_on": {"macros": ["macro.dbt_utils.default__test_equal_rowcount"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/equal_rowcount.sql", "supported_languages": null}, "macro.cht_pipeline_base.max_existing": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "max_existing", "path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro max_existing(max_field, target_ref=this) -%}\\n{#\\n  Attribution: https://gist.github.com/davehowell/1d6564875f35e58d8da14c9adbcb92da\\n#}\\n{#\\n    Gets the max existing value for some field in the target, or some other ref or source.\\n    Use in incremental models, inside `if is_incremental()` or `if execute` blocks,\\n    otherwise the dbt model will not compile.\\n    Useful where you have a primary key or other watermark field and want to construct SQL with\\n    that value determined at compile time.\\n    Why?\\n        When using the max value multiple times in a query it will be better than inlining multiple\\n        subqueries to fetch the same value, and in many cases, hardcoding a value in a where clause\\n        generates a significantly better execution plan.\\n\\n    Params: max_field - string, the name of the field\\n            target_ref - string, pass in a call to ref or source to ensure dag dependency\\n                                defaults to this (current context model)\\n    Return: A literal string of the max value - will not have any quoting\\n    Usage:  To return dates use `max_existing_date`\\n            To return timestamps use `max_existing_timestamp`\\n\\n            For integers:\\n\\n            SELECT pk_column [,col2 ...]\\n            FROM source_table_ref\\n            WHERE True\\n            {%- if is_incremental() %}\\n                AND some_int_column > {{ max_existing('some_int_column') }}\\n            {%- endif  %}\\n\\n            For strings - n.b. probably not useful to use strings as watermarks\\n\\n            SELECT pk_column [,col2 ...]\\n            FROM source_table_ref\\n            WHERE True\\n            {%- if is_incremental() %}\\n                AND some_string_column > '{{ max_existing(\\"some_string_column\\") }}'\\n            {%- endif  %}\\n#}\\n    {% call statement('get_max_existing', fetch_result=True)-%}\\n\\n        SELECT max({{ max_field }}) as max_existing\\n        FROM {{ '\\"' ~ this.schema ~ '\\"' ~ '.' ~ '\\"' ~ this.name~ '\\"' if target_ref in [this] else target_ref }}\\n\\n    {%- endcall %}\\n    {% set max_existing_field = load_result('get_max_existing').table.columns['max_existing'].values()[0] %}\\n    {% if max_existing_field == none %}\\n      {{ return('1990-01-01 23:00.000') }}\\n    {% else %}\\n      {{ return(max_existing_field) }}\\n    {% endif %}\\n{%- endmacro %}", "unique_id": "macro.cht_pipeline_base.max_existing", "created_at": 1758839281.3206837, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supported_languages": null}, "macro.cht_pipeline_base.select_table": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "select_table", "path": "macros/select_table.sql", "arguments": [], "macro_sql": "{% macro select_table(source_table, test_table) %}\\n\\n  {% if target.name == 'test' %}\\n\\n    {{ return(test_table) }}\\n\\n  {% else %}\\n\\n    {{ return(source_table) }}\\n\\n  {% endif %}\\n\\n{% endmacro %}", "unique_id": "macro.cht_pipeline_base.select_table", "created_at": 1758839281.3178847, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/select_table.sql", "supported_languages": null}, "macro.dbt.default__alter_column_type": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__alter_column_type", "path": "macros/adapters/columns.sql", "arguments": [], "macro_sql": "{% macro default__alter_column_type(relation, column_name, new_column_type) -%}\\n  {#\\n    1. Create a new column (w/ temp name and correct type)\\n    2. Copy data over to it\\n    3. Drop the existing column (cascade!)\\n    4. Rename the new column to existing column\\n  #}\\n  {%- set tmp_column = column_name + \\"__dbt_alter\\" -%}\\n\\n  {% call statement('alter_column_type') %}\\n    alter table {{ relation.render() }} add column {{ adapter.quote(tmp_column) }} {{ new_column_type }};\\n    update {{ relation.render() }} set {{ adapter.quote(tmp_column) }} = {{ adapter.quote(column_name) }};\\n    alter table {{ relation.render() }} drop column {{ adapter.quote(column_name) }} cascade;\\n    alter table {{ relation.render() }} rename column {{ adapter.quote(tmp_column) }} to {{ adapter.quote(column_name) }}\\n  {% endcall %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__alter_column_type", "created_at": 1758839281.0447986, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/columns.sql", "supported_languages": null}, "macro.dbt.default__cast_bool_to_text": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__cast_bool_to_text", "path": "macros/utils/cast_bool_to_text.sql", "arguments": [], "macro_sql": "{% macro default__cast_bool_to_text(field) %}\\n    cast({{ field }} as {{ api.Column.translate_type('string') }})\\n{% endmacro %}", "unique_id": "macro.dbt.default__cast_bool_to_text", "created_at": 1758839281.0611343, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/cast_bool_to_text.sql", "supported_languages": null}, "macro.dbt.default__collect_freshness": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__collect_freshness", "path": "macros/adapters/freshness.sql", "arguments": [], "macro_sql": "{% macro default__collect_freshness(source, loaded_at_field, filter) %}\\n  {% call statement('collect_freshness', fetch_result=True, auto_begin=False) -%}\\n    select\\n      max({{ loaded_at_field }}) as max_loaded_at,\\n      {{ current_timestamp() }} as snapshotted_at\\n    from {{ source }}\\n    {% if filter %}\\n    where {{ filter }}\\n    {% endif %}\\n  {% endcall %}\\n  {{ return(load_result('collect_freshness')) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__collect_freshness", "created_at": 1758839281.0125184, "depends_on": {"macros": ["macro.dbt.statement", "macro.dbt.current_timestamp"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/freshness.sql", "supported_languages": null}, "macro.dbt.default__current_timestamp": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__current_timestamp", "path": "macros/adapters/timestamps.sql", "arguments": [], "macro_sql": "{% macro default__current_timestamp() -%}\\n  {{ exceptions.raise_not_implemented(\\n    'current_timestamp macro not implemented for adapter ' + adapter.type()) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.default__current_timestamp", "created_at": 1758839281.0480099, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/timestamps.sql", "supported_languages": null}, "macro.dbt.default__drop_schema_named": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__drop_schema_named", "path": "macros/relations/schema.sql", "arguments": [], "macro_sql": "{% macro default__drop_schema_named(schema_name) %}\\n  {% set schema_relation = api.Relation.create(schema=schema_name) %}\\n  {{ adapter.drop_schema(schema_relation) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__drop_schema_named", "created_at": 1758839280.7766247, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/schema.sql", "supported_languages": null}, "macro.dbt.default__get_powers_of_two": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_powers_of_two", "path": "macros/utils/generate_series.sql", "arguments": [], "macro_sql": "{% macro default__get_powers_of_two(upper_bound) %}\\n\\n    {% if upper_bound <= 0 %}\\n    {{ exceptions.raise_compiler_error(\\"upper bound must be positive\\") }}\\n    {% endif %}\\n\\n    {% for _ in range(1, 100) %}\\n       {% if upper_bound <= 2 ** loop.index %}{{ return(loop.index) }}{% endif %}\\n    {% endfor %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_powers_of_two", "created_at": 1758839281.0572186, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/generate_series.sql", "supported_languages": null}, "macro.dbt.default__get_unit_test_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_unit_test_sql", "path": "macros/materializations/tests/helpers.sql", "arguments": [], "macro_sql": "{% macro default__get_unit_test_sql(main_sql, expected_fixture_sql, expected_column_names) -%}\\n-- Build actual result given inputs\\nwith dbt_internal_unit_test_actual as (\\n  select\\n    {% for expected_column_name in expected_column_names %}{{expected_column_name}}{% if not loop.last -%},{% endif %}{%- endfor -%}, {{ dbt.string_literal(\\"actual\\") }} as {{ adapter.quote(\\"actual_or_expected\\") }}\\n  from (\\n    {{ main_sql }}\\n  ) _dbt_internal_unit_test_actual\\n),\\n-- Build expected result\\ndbt_internal_unit_test_expected as (\\n  select\\n    {% for expected_column_name in expected_column_names %}{{expected_column_name}}{% if not loop.last -%}, {% endif %}{%- endfor -%}, {{ dbt.string_literal(\\"expected\\") }} as {{ adapter.quote(\\"actual_or_expected\\") }}\\n  from (\\n    {{ expected_fixture_sql }}\\n  ) _dbt_internal_unit_test_expected\\n)\\n-- Union actual and expected results\\nselect * from dbt_internal_unit_test_actual\\nunion all\\nselect * from dbt_internal_unit_test_expected\\n{%- endmacro %}", "unique_id": "macro.dbt.default__get_unit_test_sql", "created_at": 1758839280.9478574, "depends_on": {"macros": ["macro.dbt.string_literal"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/tests/helpers.sql", "supported_languages": null}, "macro.dbt.default__snapshot_get_time": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__snapshot_get_time", "path": "macros/adapters/timestamps.sql", "arguments": [], "macro_sql": "{% macro default__snapshot_get_time() %}\\n    {{ current_timestamp() }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__snapshot_get_time", "created_at": 1758839281.0485098, "depends_on": {"macros": ["macro.dbt.current_timestamp"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/timestamps.sql", "supported_languages": null}, "macro.dbt.default__truncate_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__truncate_relation", "path": "macros/adapters/relation.sql", "arguments": [], "macro_sql": "{% macro default__truncate_relation(relation) -%}\\n  {% call statement('truncate_relation') -%}\\n    truncate table {{ relation.render() }}\\n  {%- endcall %}\\n{% endmacro %}", "unique_id": "macro.dbt.default__truncate_relation", "created_at": 1758839281.0205052, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/relation.sql", "supported_languages": null}, "macro.dbt.get_incremental_append_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_incremental_append_sql", "path": "macros/materializations/models/incremental/strategies.sql", "arguments": [], "macro_sql": "{% macro get_incremental_append_sql(arg_dict) %}\\n\\n  {{ return(adapter.dispatch('get_incremental_append_sql', 'dbt')(arg_dict)) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.get_incremental_append_sql", "created_at": 1758839280.9236805, "depends_on": {"macros": ["macro.dbt.default__get_incremental_append_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/strategies.sql", "supported_languages": null}, "macro.dbt.get_relation_last_modified": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_relation_last_modified", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro get_relation_last_modified(information_schema, relations) %}\\n  {{ return(adapter.dispatch('get_relation_last_modified', 'dbt')(information_schema, relations)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.get_relation_last_modified", "created_at": 1758839281.0093098, "depends_on": {"macros": ["macro.dbt.default__get_relation_last_modified"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt.get_seed_column_quoted_csv": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_seed_column_quoted_csv", "path": "macros/materializations/seeds/helpers.sql", "arguments": [], "macro_sql": "{% macro get_seed_column_quoted_csv(model, column_names) %}\\n  {%- set quote_seed_column = model['config'].get('quote_columns', None) -%}\\n    {% set quoted = [] %}\\n    {% for col in column_names -%}\\n        {%- do quoted.append(adapter.quote_seed_column(col, quote_seed_column)) -%}\\n    {%- endfor %}\\n\\n    {%- set dest_cols_csv = quoted | join(', ') -%}\\n    {{ return(dest_cols_csv) }}\\n{% endmacro %}", "unique_id": "macro.dbt.get_seed_column_quoted_csv", "created_at": 1758839280.967868, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/seeds/helpers.sql", "supported_languages": null}, "macro.dbt.make_intermediate_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "make_intermediate_relation", "path": "macros/adapters/relation.sql", "arguments": [], "macro_sql": "{% macro make_intermediate_relation(base_relation, suffix='__dbt_tmp') %}\\n  {{ return(adapter.dispatch('make_intermediate_relation', 'dbt')(base_relation, suffix)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.make_intermediate_relation", "created_at": 1758839281.0164316, "depends_on": {"macros": ["macro.dbt_postgres.postgres__make_intermediate_relation"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/relation.sql", "supported_languages": null}, "macro.dbt.materialized_view_teardown": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialized_view_teardown", "path": "macros/materializations/models/materialized_view.sql", "arguments": [], "macro_sql": "{% macro materialized_view_teardown(backup_relation, intermediate_relation, post_hooks) %}\\n\\n    -- drop the temp relations if they exist to leave the database clean for the next run\\n    {{ drop_relation_if_exists(backup_relation) }}\\n    {{ drop_relation_if_exists(intermediate_relation) }}\\n\\n    {{ run_hooks(post_hooks, inside_transaction=False) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.materialized_view_teardown", "created_at": 1758839280.894199, "depends_on": {"macros": ["macro.dbt.drop_relation_if_exists", "macro.dbt.run_hooks"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/materialized_view.sql", "supported_languages": null}, "macro.dbt_date.bigquery__day_of_week": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "bigquery__day_of_week", "path": "macros/calendar_date/day_of_week.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro bigquery__day_of_week(date, isoweek) -%}\\n\\n    {%- set dow = dbt_date.date_part('dayofweek', date) -%}\\n\\n    {%- if isoweek -%}\\n    case\\n        -- Shift start of week from Sunday (1) to Monday (2)\\n        when {{ dow }} = 1 then 7\\n        else {{ dow }} - 1\\n    end\\n    {%- else -%}\\n    {{ dow }}\\n    {%- endif -%}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_date.bigquery__day_of_week", "created_at": 1758839281.1885865, "depends_on": {"macros": ["macro.dbt_date.date_part"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_of_week.sql", "supported_languages": null}, "macro.dbt_date.default__iso_week_end": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__iso_week_end", "path": "macros/calendar_date/iso_week_end.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__iso_week_end(date) -%}\\n{{ dbt_date._iso_week_end(date, 'isoweek') }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.default__iso_week_end", "created_at": 1758839281.1725273, "depends_on": {"macros": ["macro.dbt_date._iso_week_end"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_end.sql", "supported_languages": null}, "macro.dbt_date.default__week_of_year": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__week_of_year", "path": "macros/calendar_date/week_of_year.sql", "arguments": [], "macro_sql": "{%- macro default__week_of_year(date) -%}\\ncast({{ dbt_date.date_part('week', date) }} as {{ dbt.type_int() }})\\n{%- endmacro %}", "unique_id": "macro.dbt_date.default__week_of_year", "created_at": 1758839281.1592934, "depends_on": {"macros": ["macro.dbt_date.date_part", "macro.dbt.type_int"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_of_year.sql", "supported_languages": null}, "macro.dbt_date.get_fiscal_year_dates": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_fiscal_year_dates", "path": "macros/fiscal_date/get_fiscal_year_dates.sql", "arguments": [], "macro_sql": "{% macro get_fiscal_year_dates(dates, year_end_month=12, week_start_day=1, shift_year=1) %}\\n{{ adapter.dispatch('get_fiscal_year_dates', 'dbt_date') (dates, year_end_month, week_start_day, shift_year) }}\\n{% endmacro %}", "unique_id": "macro.dbt_date.get_fiscal_year_dates", "created_at": 1758839281.136639, "depends_on": {"macros": ["macro.dbt_date.default__get_fiscal_year_dates"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/fiscal_date/get_fiscal_year_dates.sql", "supported_languages": null}, "macro.dbt_date.get_intervals_between": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_intervals_between", "path": "macros/_utils/date_spine.sql", "arguments": [], "macro_sql": "{% macro get_intervals_between(start_date, end_date, datepart) -%}\\n    {{ return(adapter.dispatch('get_intervals_between', 'dbt_date')(start_date, end_date, datepart)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.get_intervals_between", "created_at": 1758839281.1272547, "depends_on": {"macros": ["macro.dbt_date.default__get_intervals_between"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/_utils/date_spine.sql", "supported_languages": null}, "macro.dbt_date.postgres__day_of_week": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__day_of_week", "path": "macros/calendar_date/day_of_week.sql", "arguments": [], "macro_sql": "\\n\\n\\n{%- macro postgres__day_of_week(date, isoweek) -%}\\n\\n    {%- if isoweek -%}\\n        {%- set dow_part = 'isodow' -%}\\n        -- Monday(1) to Sunday (7)\\n        cast({{ dbt_date.date_part(dow_part, date) }} as {{ dbt.type_int() }})\\n    {%- else -%}\\n        {%- set dow_part = 'dow' -%}\\n        -- Sunday(1) to Saturday (7)\\n        cast({{ dbt_date.date_part(dow_part, date) }} + 1 as {{ dbt.type_int() }})\\n    {%- endif -%}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_date.postgres__day_of_week", "created_at": 1758839281.1894026, "depends_on": {"macros": ["macro.dbt_date.date_part", "macro.dbt.type_int"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_of_week.sql", "supported_languages": null}, "macro.dbt_date.postgres__day_of_year": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__day_of_year", "path": "macros/calendar_date/day_of_year.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro postgres__day_of_year(date) -%}\\n    {{ dbt_date.date_part('doy', date) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.postgres__day_of_year", "created_at": 1758839281.1807284, "depends_on": {"macros": ["macro.dbt_date.date_part"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_of_year.sql", "supported_languages": null}, "macro.dbt_date.redshift__day_of_week": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "redshift__day_of_week", "path": "macros/calendar_date/day_of_week.sql", "arguments": [], "macro_sql": "\\n\\n\\n{%- macro redshift__day_of_week(date, isoweek) -%}\\n\\n    {%- set dow = dbt_date.date_part('dayofweek', date) -%}\\n\\n    {%- if isoweek -%}\\n    case\\n        -- Shift start of week from Sunday (0) to Monday (1)\\n        when {{ dow }} = 0 then 7\\n        else cast({{ dow }} as {{ dbt.type_bigint() }})\\n    end\\n    {%- else -%}\\n    cast({{ dow }} + 1 as {{ dbt.type_bigint() }})\\n    {%- endif -%}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_date.redshift__day_of_week", "created_at": 1758839281.1901238, "depends_on": {"macros": ["macro.dbt_date.date_part", "macro.dbt.type_bigint"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_of_week.sql", "supported_languages": null}, "macro.dbt_date.redshift__day_of_year": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "redshift__day_of_year", "path": "macros/calendar_date/day_of_year.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro redshift__day_of_year(date) -%}\\n    cast({{ dbt_date.date_part('dayofyear', date) }} as {{ dbt.type_bigint() }})\\n{%- endmacro %}", "unique_id": "macro.dbt_date.redshift__day_of_year", "created_at": 1758839281.181091, "depends_on": {"macros": ["macro.dbt_date.date_part", "macro.dbt.type_bigint"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_of_year.sql", "supported_languages": null}, "macro.dbt_date.snowflake__month_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snowflake__month_name", "path": "macros/calendar_date/month_name.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro snowflake__month_name(date, short) -%}\\n{%- set f = 'MON' if short else 'MMMM' -%}\\n    to_char({{ date }}, '{{ f }}')\\n{%- endmacro %}", "unique_id": "macro.dbt_date.snowflake__month_name", "created_at": 1758839281.163179, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/month_name.sql", "supported_languages": null}, "macro.dbt_date.snowflake__week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snowflake__week_start", "path": "macros/calendar_date/week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro snowflake__week_start(date) -%}\\n    {#\\n        Get the day of week offset: e.g. if the date is a Sunday,\\n        dbt_date.day_of_week returns 1, so we subtract 1 to get a 0 offset\\n    #}\\n    {% set off_set = dbt_date.day_of_week(date, isoweek=False) ~ \\" - 1\\" %}\\n    cast({{ dbt.dateadd(\\"day\\", \\"-1 * (\\" ~ off_set ~ \\")\\", date) }} as date)\\n{%- endmacro %}", "unique_id": "macro.dbt_date.snowflake__week_start", "created_at": 1758839281.1753433, "depends_on": {"macros": ["macro.dbt_date.day_of_week", "macro.dbt.dateadd"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_start.sql", "supported_languages": null}, "macro.dbt_date.spark__iso_week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "spark__iso_week_start", "path": "macros/calendar_date/iso_week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro spark__iso_week_start(date) -%}\\n{{ dbt_date._iso_week_start(date, 'week') }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.spark__iso_week_start", "created_at": 1758839281.1522677, "depends_on": {"macros": ["macro.dbt_date._iso_week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_start.sql", "supported_languages": null}, "macro.dbt_date.trino__get_base_dates": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "trino__get_base_dates", "path": "macros/get_base_dates.sql", "arguments": [], "macro_sql": "{% macro trino__get_base_dates(start_date, end_date, n_dateparts, datepart) %}\\n\\n{%- if start_date and end_date -%}\\n{%- set start_date=\\"cast('\\" ~ start_date ~ \\"' as \\" ~ dbt.type_timestamp() ~ \\")\\" -%}\\n{%- set end_date=\\"cast('\\" ~ end_date ~ \\"' as \\" ~ dbt.type_timestamp() ~ \\")\\"  -%}\\n\\n{%- elif n_dateparts and datepart -%}\\n\\n{%- set start_date = dbt.dateadd(datepart, -1 * n_dateparts, dbt_date.now()) -%}\\n{%- set end_date = dbt_date.tomorrow() -%}\\n{%- endif -%}\\n\\nwith date_spine as\\n(\\n\\n    {{ dbt_date.date_spine(\\n        datepart=datepart,\\n        start_date=start_date,\\n        end_date=end_date,\\n       )\\n    }}\\n\\n)\\nselect\\n    cast(d.date_{{ datepart }} as {{ dbt.type_timestamp() }}) as date_{{ datepart }}\\nfrom\\n    date_spine d\\n{% endmacro %}", "unique_id": "macro.dbt_date.trino__get_base_dates", "created_at": 1758839281.115719, "depends_on": {"macros": ["macro.dbt.type_timestamp", "macro.dbt.dateadd", "macro.dbt_date.now", "macro.dbt_date.tomorrow", "macro.dbt_date.date_spine"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/get_base_dates.sql", "supported_languages": null}, "macro.dbt_date.trino__iso_week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "trino__iso_week_start", "path": "macros/calendar_date/iso_week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro trino__iso_week_start(date) -%}\\n{{ dbt_date._iso_week_start(date, 'week') }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.trino__iso_week_start", "created_at": 1758839281.152537, "depends_on": {"macros": ["macro.dbt_date._iso_week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_start.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__dateadd": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__dateadd", "path": "macros/utils/dateadd.sql", "arguments": [], "macro_sql": "{% macro postgres__dateadd(datepart, interval, from_date_or_timestamp) %}\\n\\n    {{ from_date_or_timestamp }} + ((interval '1 {{ datepart }}') * ({{ interval }}))\\n\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__dateadd", "created_at": 1758839280.7701683, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/utils/dateadd.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__listagg": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__listagg", "path": "macros/utils/listagg.sql", "arguments": [], "macro_sql": "{% macro postgres__listagg(measure, delimiter_text, order_by_clause, limit_num) -%}\\n\\n    {% if limit_num -%}\\n    array_to_string(\\n        (array_agg(\\n            {{ measure }}\\n            {% if order_by_clause -%}\\n            {{ order_by_clause }}\\n            {%- endif %}\\n        ))[1:{{ limit_num }}],\\n        {{ delimiter_text }}\\n        )\\n    {%- else %}\\n    string_agg(\\n        {{ measure }},\\n        {{ delimiter_text }}\\n        {% if order_by_clause -%}\\n        {{ order_by_clause }}\\n        {%- endif %}\\n        )\\n    {%- endif %}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__listagg", "created_at": 1758839280.7642136, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/utils/listagg.sql", "supported_languages": null}, "macro.dbt_utils.default__deduplicate": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__deduplicate", "path": "macros/sql/deduplicate.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__deduplicate(relation, partition_by, order_by) -%}\\n\\n    with row_numbered as (\\n        select\\n            _inner.*,\\n            row_number() over (\\n                partition by {{ partition_by }}\\n                order by {{ order_by }}\\n            ) as rn\\n        from {{ relation }} as _inner\\n    )\\n\\n    select\\n        distinct data.*\\n    from {{ relation }} as data\\n    {#\\n    -- Not all DBs will support natural joins but the ones that do include:\\n    -- Oracle, MySQL, SQLite, Redshift, Teradata, Materialize, Databricks\\n    -- Apache Spark, SingleStore, Vertica\\n    -- Those that do not appear to support natural joins include:\\n    -- SQLServer, Trino, Presto, Rockset, Athena\\n    #}\\n    natural join row_numbered\\n    where row_numbered.rn = 1\\n\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_utils.default__deduplicate", "created_at": 1758839281.2086904, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/deduplicate.sql", "supported_languages": null}, "macro.dbt_utils.default__pretty_time": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__pretty_time", "path": "macros/jinja_helpers/pretty_time.sql", "arguments": [], "macro_sql": "{% macro default__pretty_time(format='%H:%M:%S') %}\\n    {{ return(modules.datetime.datetime.now().strftime(format)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__pretty_time", "created_at": 1758839281.3081665, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/jinja_helpers/pretty_time.sql", "supported_languages": null}, "macro.dbt_utils.default__safe_divide": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__safe_divide", "path": "macros/sql/safe_divide.sql", "arguments": [], "macro_sql": "{% macro default__safe_divide(numerator, denominator) %}\\n    ( {{ numerator }} ) / nullif( ( {{ denominator }} ), 0)\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__safe_divide", "created_at": 1758839281.2352977, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/safe_divide.sql", "supported_languages": null}, "macro.dbt_utils.test_fewer_rows_than": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_fewer_rows_than", "path": "macros/generic_tests/fewer_rows_than.sql", "arguments": [], "macro_sql": "{% test fewer_rows_than(model, compare_model, group_by_columns = []) %}\\n  {{ return(adapter.dispatch('test_fewer_rows_than', 'dbt_utils')(model, compare_model, group_by_columns)) }}\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_fewer_rows_than", "created_at": 1758839281.289265, "depends_on": {"macros": ["macro.dbt_utils.default__test_fewer_rows_than"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/fewer_rows_than.sql", "supported_languages": null}, "macro.cht_pipeline_base._cast_as_type": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "_cast_as_type", "path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro _cast_as_type(stringvalue, as_type) %}\\n    {{ return(\\"CAST('\\" ~ stringvalue ~ \\"' AS \\" ~ as_type ~ \\")\\") }}\\n{% endmacro %}", "unique_id": "macro.cht_pipeline_base._cast_as_type", "created_at": 1758839281.3240488, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supported_languages": null}, "macro.cht_pipeline_base.get_hmis_data": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_hmis_data", "path": "macros/get_hmis_data.sql", "arguments": [], "macro_sql": "{% macro get_hmis_data(startDate, endDate) %}\\nSELECT\\n\\tperiod_chp.uuid AS chp_uuid,\\n\\tperiod_chp.name,\\n\\tperiod_chp.date,\\n\\tperiod_chp.branch_uuid,\\n\\tperiod_chp.supervisor_uuid,\\n\\tperiod_chp.branch_name,\\n\\tperiod_chp.region,\\n\\tCASE WHEN COALESCE(num_of_hh_visited.count, 0) > 0 THEN 'Yes' ELSE 'No' END AS chp_active,\\n\\tCOALESCE(cumulative_demography.total_households, 0) AS total_households,\\n\\tCOALESCE(num_of_hh_covered.count, 0) AS households_registered,\\n\\tCOALESCE(num_of_hh_visited.count, 0) AS num_of_hh_visited,\\n\\tCOALESCE(family_survey.num_of_hh_bed_nets, 0) AS num_of_hh_bed_nets, \\n\\tCOALESCE(family_survey.num_of_hh_latrines, 0) AS num_of_hh_latrines, \\n\\tCOALESCE(family_survey.num_of_hh_safe_water, 0) AS num_of_hh_safe_water,\\t\\n\\tCOALESCE(health_forum.num_of_comm_members, 0) AS num_of_comm_members, \\n\\tCOALESCE(health_forum.num_of_health_forum, 0) AS num_of_health_forum,\\t\\n\\tCOALESCE(num_pregnant.care, 0) AS num_pregnant_care,\\t\\n\\tCOALESCE(num_pregnant.identified, 0) AS num_pregnant_identified,\\t\\n\\tCOALESCE(deliveries.num_facility_deliveries, 0) AS num_facility_deliveries,\\t\\n\\tCOALESCE(deliveries.num_home_deliveries, 0) AS num_home_deliveries,\\n\\tCOALESCE(pregnancy.num_active_pregnant, 0) AS num_active_pregnant,\\n\\tCOALESCE(pregnancy.num_anc_1, 0) AS num_anc_1,\\n\\tCOALESCE(pregnancy.num_anc_2, 0) AS num_anc_2,\\n\\tCOALESCE(pregnancy.num_anc_3, 0) AS num_anc_3,\\n\\tCOALESCE(pregnancy.num_anc_4, 0) AS num_anc_4,\\t\\n\\tCOALESCE(assess.tot_malaria_confirmed, 0) AS tot_malaria_confirmed,\\n\\tCOALESCE(assess.num_malaria_u1_male, 0) AS num_malaria_u1_male,\\n\\tCOALESCE(assess.num_malaria_u1_female, 0) AS num_malaria_u1_female,\\n\\tCOALESCE(assess.num_malaria_u5_male, 0) AS num_malaria_u5_male,\\n\\tCOALESCE(assess.num_malaria_u5_female, 0) AS num_malaria_u5_female,\\n\\tCOALESCE(assess.num_diarrhea_u1_male, 0) AS num_diarrhea_u1_male,\\n\\tCOALESCE(assess.num_diarrhea_u1_female, 0) AS num_diarrhea_u1_female,\\n\\tCOALESCE(assess.num_diarrhea_u5_male, 0) AS num_diarrhea_u5_male,\\n\\tCOALESCE(assess.num_diarrhea_u5_female, 0) AS num_diarrhea_u5_female,\\n\\tCOALESCE(assess.num_ari_u1_male, 0) AS num_ari_u1_male,\\n\\tCOALESCE(assess.num_ari_u1_female, 0) AS num_ari_u1_female,\\n\\tCOALESCE(assess.num_ari_u5_male, 0) AS num_ari_u5_male,\\n\\tCOALESCE(assess.num_ari_u5_female, 0) AS num_ari_u5_female,\\n\\tCOALESCE(assess.tot_u5_assessed, 0) AS tot_u5_assessed,\\n\\tCOALESCE(assess.tot_u1_assessed, 0) AS tot_u1_assessed,\\n\\tCOALESCE(assess.malaria_treatment_u1_male, 0) AS malaria_treatment_u1_male,\\n\\tCOALESCE(assess.malaria_treatment_u1_female, 0) AS malaria_treatment_u1_female,\\n\\tCOALESCE(assess.u1_malaria_treatment, 0) AS u1_malaria_treatment,\\n\\tCOALESCE(assess.malaria_treatment_u5_male, 0) AS malaria_treatment_u5_male,\\n\\tCOALESCE(assess.malaria_treatment_u5_female, 0) AS malaria_treatment_u5_female,\\n\\tCOALESCE(assess.u5_malaria_treatment, 0) AS u5_malaria_treatment,\\n\\tCOALESCE(assess.malaria_treatment_over5_male, 0) AS malaria_treatment_over5_male,\\n\\tCOALESCE(assess.malaria_treatment_over5_female, 0) AS malaria_treatment_over5_female,\\n\\tCOALESCE(assess.over5_malaria_treatment, 0) AS over5_malaria_treatment,\\n\\tCOALESCE(assess.diarrhea_treatment_u1_male, 0) AS diarrhea_treatment_u1_male,\\n\\tCOALESCE(assess.diarrhea_treatment_u1_female, 0) AS diarrhea_treatment_u1_female,\\n\\tCOALESCE(assess.u1_diarrhea_treatment, 0) AS u1_diarrhea_treatment,\\n\\tCOALESCE(assess.diarrhea_treatment_u5_male, 0) AS diarrhea_treatment_u5_male,\\n\\tCOALESCE(assess.diarrhea_treatment_u5_female, 0) AS diarrhea_treatment_u5_female,\\n\\tCOALESCE(assess.u5_diarrhea_treatment, 0) AS u5_diarrhea_treatment,\\n\\tCOALESCE(assess.ari_treatment_u1_male, 0) AS ari_treatment_u1_male,\\n\\tCOALESCE(assess.ari_treatment_u1_female, 0) AS ari_treatment_u1_female,\\n\\tCOALESCE(assess.u1_ari_treatment, 0) AS u1_ari_treatment,\\n\\tCOALESCE(assess.ari_treatment_u5_male, 0) AS ari_treatment_u5_male,\\n\\tCOALESCE(assess.ari_treatment_u5_female, 0) AS ari_treatment_u5_female,\\n\\tCOALESCE(assess.u5_ari_treatment, 0) AS u5_ari_treatment,\\n\\tCOALESCE(assess.num_treatments, 0) AS num_treatments,\\n\\t(\\n\\t\\tCOALESCE(assess.u1_malaria_treatment, 0) + \\n\\t\\tCOALESCE(assess.u1_diarrhea_treatment, 0) + \\n\\t\\tCOALESCE(assess.u1_ari_treatment, 0)\\n\\t) AS u1_num_treatments,\\n\\t(\\n\\t\\tCOALESCE(assess.u5_malaria_treatment, 0) + \\n\\t\\tCOALESCE(assess.u5_diarrhea_treatment, 0) + \\n\\t\\tCOALESCE(assess.u5_ari_treatment, 0)\\n\\t) AS u5_num_treatments,\\n\\tCOALESCE(assess.tot_malaria_positive_u5, 0) AS tot_malaria_positive_u5,\\n\\tCOALESCE(assess.tot_malaria_positive_over5, 0) AS tot_malaria_positive_over5,\\n\\tCOALESCE(assess.tot_malaria_suspect_u5, 0) AS tot_malaria_suspect_u5,\\n\\tCOALESCE(assess.tot_malaria_suspect_over5, 0) AS tot_malaria_suspect_over5,\\n\\tCOALESCE(assess.num_reffered_malaria_u5_male, 0) AS num_reffered_malaria_u5_male,\\n\\tCOALESCE(assess.num_reffered_malaria_u5_female, 0) AS num_reffered_malaria_u5_female,\\n\\tCOALESCE(assess.num_reffered_malaria_over5_male, 0) AS num_reffered_malaria_over5_male,\\n\\tCOALESCE(assess.num_reffered_malaria_over5_female, 0) AS num_reffered_malaria_over5_female,\\n\\tCOALESCE(assess.num_reffered_diarrhea_u5_male, 0) AS num_reffered_diarrhea_u5_male,\\n\\tCOALESCE(assess.num_reffered_diarrhea_u5_female, 0) AS num_reffered_diarrhea_u5_female,\\n\\tCOALESCE(assess.num_reffered_ari_u5_male, 0) AS num_reffered_ari_u5_male,\\n\\tCOALESCE(assess.num_reffered_ari_u5_female, 0) AS num_reffered_ari_u5_female,\\t\\n\\tCOALESCE(follow_Up.num_accute_u5_malaria, 0) AS num_accute_u5_malaria,\\t\\n\\tCOALESCE(follow_Up.num_accute_u5_diarrhea, 0) AS num_accute_u5_diarrhea,\\t\\n\\tCOALESCE(follow_Up.num_accute_u5_ari, 0) AS num_accute_u5_ari,\\t\\n\\tCOALESCE(follow_Up.num_u5_reffered_followed, 0) AS num_u5_reffered_followed,\\t\\n\\tCOALESCE(follow_Up.num_u5_followed_malaria, 0) AS num_u5_followed_malaria,\\t\\n\\tCOALESCE(follow_Up.num_u5_followed_diarrhea, 0) AS num_u5_followed_diarrhea,\\t\\n\\tCOALESCE(follow_Up.num_u5_followed_ari, 0) AS num_u5_followed_ari,\\t\\n\\tCOALESCE(follow_Up.num_u5_treated, 0) AS num_u5_treated,\\t\\n\\tCOALESCE(demography.num_eligible_women, 0) AS num_eligible_women,\\n\\tCOALESCE(cumulative_demography.tot_eligible_women, 0) AS tot_eligible_women,\\n\\tCOALESCE(cumulative_demography.tot_eligible_women_old, 0) AS tot_eligible_women_old,\\n\\tCOALESCE(demography.num_u5_children, 0) AS num_u5_children,\\n\\tCOALESCE(immunization.num_u5_imm, 0) AS num_u5_imm,\\n\\tCOALESCE(FPREFERRALS.long_term_fp_referrals, 0) AS long_term_fp_referrals,\\n\\tCOALESCE(deaths.u5_count, 0) AS num_u5_deaths,\\n\\tCOALESCE(demography.num_hh_with_u5, 0) AS num_hh_with_u5,\\t\\n\\tCOALESCE(pnc.pnc_visit_48_hrs, 0) AS pnc_visit_48_hrs,\\t\\t\\n\\tCOALESCE(visit.num_pregnant_immunized, 0) AS num_pregnant_immunized,\\t\\n\\tCOALESCE(visit.num_anc_at_facility, 0) AS num_anc_at_facility\\n\\t\\n\\t\\nFROM\\n\\t(\\n\\t\\tSELECT\\n\\t\\t\\tchp.area_uuid,\\n\\t\\t\\tchp.uuid,\\n\\t\\t\\tchp.name,\\n\\t\\t\\tchp.branch_name,\\n\\t\\t\\tchp.branch_uuid,\\n\\t\\t\\tchp.supervisor_uuid,\\n\\t\\t\\tchp.region,\\t\\n\\t\\t\\tgenerate_series(date_trunc('month',({{startDate}})::date), \\n\\t\\t\\t\\t\\t\\t\\tdate_trunc('month',({{endDate}})::date), \\n\\t\\t\\t\\t\\t\\t\\t'1 month'::interval\\n\\t\\t\\t\\t\\t\\t\\t)::DATE AS date\\n\\t\\tFROM\\n\\t\\t\\t{{ ref(\\"contactview_chp\\") }} AS chp\\n\\t) AS period_chp\\n\\nLEFT JOIN\\n(\\n\\tSELECT\\n\\t\\tmeta.parent_uuid as area_uuid,\\n\\t\\tCOUNT(person.uuid) FILTER(\\n\\t\\t\\tWHERE extract (YEAR from age(now()::date, to_date(person.date_of_birth,'YYYY-MM-DD')))::int BETWEEN 12 AND 52  \\n\\t\\t\\tAND person.sex ='female' AND (date_trunc('hour',(person.reported)::timestamp))::date <= date_trunc('hour',({{endDate}})::date)::date\\n\\t\\t) AS tot_eligible_women,\\n\\t\\tCOUNT(person.uuid) FILTER(\\n\\t\\t\\tWHERE extract (YEAR from age(now()::date, to_date(person.date_of_birth,'YYYY-MM-DD')))::int BETWEEN 12 AND 52  \\n\\t\\t\\tAND person.sex ='female' AND (date_trunc('hour',(person.reported)::timestamp))::date <= (date_trunc('hour',({{endDate}})::date)::date - INTERVAL '1 months')\\n\\t\\t) AS tot_eligible_women_old,\\n\\t\\tCOUNT(DISTINCT person.parent_uuid) AS total_households\\n\\tFROM \\n\\t\\t{{ ref(\\"contactview_person\\") }} person\\n\\tLEFT JOIN {{ ref(\\"contactview_metadata\\") }} AS meta ON person.parent_uuid = meta.uuid\\n\\tWHERE\\n\\t\\tmeta.type = 'clinic'\\n\\tGROUP BY \\n\\t\\tmeta.parent_uuid\\n) cumulative_demography ON (period_chp.area_uuid = cumulative_demography.area_uuid)\\n\\t\\nLEFT JOIN\\n\\t(\\n\\t\\tSELECT\\n\\t\\t\\tparent_uuid AS area_uuid,\\n\\t\\t\\tdate_trunc('month',reported::timestamp)::date AS reported_month,\\n\\t\\t\\tsum(1) AS count\\n\\t\\t\\t\\n\\t\\t\\t\\n\\t\\tFROM\\n\\t\\t\\t{{ ref(\\"contactview_metadata\\") }}\\n\\t\\t\\t\\n\\t\\tWHERE\\n\\t\\t\\ttype = 'clinic'\\n\\t\\t\\t\\n\\t\\tGROUP BY\\n\\t\\t\\tarea_uuid,\\n\\t\\t\\treported_month\\n\\t\\t\\t\\t\\n\\t) AS num_of_hh_covered ON (period_chp.date = num_of_hh_covered.reported_month AND period_chp.area_uuid = num_of_hh_covered.area_uuid)\\n\\t\\nLEFT JOIN\\n\\t(\\n\\t\\tSELECT\\n\\t\\t\\tfmeta.reported_by_parent AS area_uuid,\\n\\t\\t\\tdate_trunc('month',fmeta.reported::timestamp)::date AS reported_month,\\n\\t\\t\\tCOUNT(DISTINCT(cperson.parent_uuid)) AS count\\n\\t\\t\\t\\n\\t\\tFROM\\n\\t\\t\\t{{ ref(\\"form_metadata\\") }} AS fmeta\\n\\t\\tINNER JOIN {{ ref(\\"contactview_person\\") }} AS cperson ON (fmeta.patient_id = cperson.patient_id)\\n\\t\\tWHERE\\n\\t\\t\\tfmeta.reported BETWEEN {{startDate}} AND {{endDate}} /* only pick whats necessary */\\n\\t\\t\\t\\n\\t\\tGROUP BY\\n\\t\\t\\tarea_uuid,\\n\\t\\t\\treported_month\\n\\t\\n\\t) AS num_of_hh_visited ON (period_chp.date = num_of_hh_visited.reported_month AND period_chp.area_uuid = num_of_hh_visited.area_uuid)\\nLEFT JOIN \\n(\\n\\n\\tSELECT  \\n\\t\\tchw, \\n\\t\\tarea_uuid, \\t\\n\\t\\tdate_trunc('month',reported::timestamp)::date  AS reported_month, \\n\\t\\tSUM((mosquito_nets ='true')::int) AS num_of_hh_bed_nets, \\n    \\tSUM((hygeinic_toilet ='true')::int) AS num_of_hh_latrines, \\n\\t\\tSUM((COALESCE(source_of_drinking_water,'') != 'spring')::int) AS num_of_hh_safe_water\\n\\tFROM {{ ref(\\"useview_household_survey\\") }}\\n\\n\\tGROUP BY \\n\\t\\tchw, \\n\\t\\tarea_uuid, \\n\\t\\treported_month \\n\\n\\n) AS family_survey ON(period_chp.date = family_survey.reported_month  AND  period_chp.area_uuid =family_survey.area_uuid)\\nLEFT JOIN\\n(\\n\\n\\tSELECT \\n\\t\\tchw, \\n\\t\\tarea_uuid,  \\n\\t\\tSUM( \\n\\t\\tCASE \\n\\t\\tWHEN CHARACTER_LENGTH(no_of_participants) > 4 THEN 0  /* guard against invalid entry from users*/\\n\\t\\tELSE  no_of_participants ::int\\n\\t\\tEND ) AS num_of_comm_members, \\n\\t\\tCOUNT(xmlforms_uuid) AS num_of_health_forum,\\n\\t\\tdate_trunc('month',reported_day::date)::date AS reported_month\\n\\tFROM {{ ref(\\"useview_health_forum\\") }}\\n\\tGROUP BY \\n \\t\\tchw, \\n \\t\\tarea_uuid,\\n \\t\\treported_month\\n\\n) AS health_forum ON (period_chp.date = health_forum. reported_month AND period_chp.area_uuid = health_forum.area_uuid )\\nLEFT JOIN \\n(\\n\\tWITH preg_record AS (\\n\\t\\tSELECT \\n\\t\\t\\tchp.area_uuid,\\n\\t\\t\\tdate_trunc('MONTH', reported::timestamp) AS reported_month,\\n\\t\\t\\tCOUNT(DISTINCT patient_id) FILTER(WHERE preg_test != 'neg') AS count\\n\\t\\tFROM {{ ref(\\"useview_pregnancy\\") }} preg\\n\\t\\tLEFT JOIN {{ ref(\\"contactview_chp\\") }} chp ON chp.uuid =  preg.chw \\n\\t\\tWHERE date_trunc('month',reported::timestamp)::date <= date_trunc('MONTH',({{endDate}})::timestamp)::date\\n\\t\\tGROUP BY \\n\\t\\t\\tarea_uuid, \\n\\t\\t\\treported_month\\n\\t)\\n\\tSELECT\\n\\t\\tarea_uuid,\\n\\t\\treported_month,\\n\\t\\tcount as identified, /* Count those registered this month*/\\n\\t\\tSUM(count) OVER (PARTITION BY area_uuid ORDER BY reported_month) AS care /* Count all those registered in the past*/\\n\\tFROM {{ ref(\\"preg_record\\") }}\\n\\t\\t\\t\\n\\t)\\tAS num_pregnant ON (num_pregnant.reported_month = period_chp.date  AND period_chp.area_uuid = num_pregnant.area_uuid)\\n\\tLEFT JOIN \\n\\t(\\n\\tSELECT  DISTINCT\\n\\t\\tfpostnatal.reported_by_parent AS area_uuid,\\n\\t\\tSUM ((fpostnatal.health_facility_delivery ='yes' )::int  ) AS num_facility_deliveries,\\n\\t\\tSUM ((fpostnatal.health_facility_delivery ='no')::int ) AS num_home_deliveries,  /* Assumption is that home deliveries have answer no  */\\n\\t\\tdate_trunc('month',(fpostnatal.reported::timestamp)::date)  AS reported_month\\n\\tFROM \\n\\t\\t{{ ref(\\"useview_postnatal_care\\") }} AS fpostnatal\\n\\tWHERE \\n\\t\\t(date_trunc('month',fpostnatal.reported::timestamp)::DATE) >= (date_trunc('MONTH',({{startDate}})::date)::timestamp) AND (date_trunc('month',fpostnatal.reported::timestamp)::date) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\tGROUP BY\\n\\t\\tarea_uuid,\\n\\t\\treported_month\\n\\t\\n\\t\\n\\t) AS deliveries ON (deliveries.area_uuid = period_chp.area_uuid  AND deliveries.reported_month = period_chp.date ) \\n  LEFT JOIN\\n  (\\n  \\tSELECT  \\n\\t\\tchw, \\n\\t\\tdate_trunc('month', reported::timestamp)::date  AS reported_month, \\n\\t\\tSUM((edd::date > date_trunc('month', reported::timestamp)::date)::int) AS num_active_pregnant,\\n\\t\\tSUM((anc_visit >= 1)::int) AS num_anc_1,\\n\\t\\tSUM((anc_visit >= 2)::int) AS num_anc_2,\\n\\t\\tSUM((anc_visit >= 3)::int) AS num_anc_3,\\n\\t\\tSUM((anc_visit >= 4)::int) AS num_anc_4\\n\\tFROM \\n\\t\\t{{ ref(\\"useview_pregnancy\\") }}\\n\\t\\t\\n\\tWHERE \\n\\t\\t(date_trunc('month',useview_pregnancy.reported::timestamp)::DATE) >= (date_trunc('MONTH',({{startDate}})::DATE)::date) AND (date_trunc('month',useview_pregnancy.reported::timestamp)::DATE) <= (date_trunc('MONTH',({{endDate}})::DATE))\\n\\t\\n\\n\\tGROUP BY \\n\\t\\tchw,\\n\\t\\treported_month\\n\\t\\t\\n  ) AS pregnancy ON (pregnancy.chw = period_chp.uuid AND pregnancy.reported_month = period_chp.date)\\n  LEFT JOIN \\n  (\\n  SELECT \\n\\t\\n\\treported_by_parent  AS  area_uuid, \\n\\tdate_trunc ('MONTH',reported::timestamp)::date AS reported_month, \\n\\tSUM ((COALESCE(mrdt_result,'')= 'positive')::int) AS tot_malaria_confirmed,\\t\\n\\tSUM ((COALESCE(mrdt_result,'')= 'positive'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <12  AND COALESCE(sex,'') ='male')::int) AS num_malaria_u1_male,\\n\\tSUM ((COALESCE(mrdt_result,'')= 'positive'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <12  AND COALESCE(sex,'') ='female')::int) AS num_malaria_u1_female,\\n\\tSUM ((COALESCE(mrdt_result,'')= 'positive'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <60 AND COALESCE(sex,'') ='male')::int) AS num_malaria_u5_male,\\n\\tSUM ((COALESCE(mrdt_result,'')= 'positive'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <60  AND COALESCE(sex,'') ='female')::int) AS num_malaria_u5_female,\\n\\tSUM ((COALESCE(diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <12  AND COALESCE(sex,'') ='male')::int) AS num_ari_u1_male,\\n\\tSUM ((COALESCE(diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <12  AND COALESCE(sex,'') ='female')::int) AS num_ari_u1_female,\\n\\tSUM ((COALESCE(diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <60  AND COALESCE(sex,'') ='male')::int) AS num_ari_u5_male,\\n\\tSUM ((COALESCE(diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <60  AND COALESCE(sex,'') ='female')::int) AS num_ari_u5_female,\\n\\tSUM ((COALESCE(diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <12  AND COALESCE(sex,'') ='male')::int) AS num_diarrhea_u1_male,\\n\\tSUM ((COALESCE(diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <12  AND COALESCE(sex,'') ='female')::int) AS num_diarrhea_u1_female,\\n\\tSUM ((COALESCE(diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <60  AND COALESCE(sex,'') ='male')::int) AS num_diarrhea_u5_male,\\n\\tSUM ((COALESCE(diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (patient_age_in_months,0) >2 AND COALESCE (patient_age_in_months,0) <60  AND COALESCE(sex,'') ='female')::int) AS num_diarrhea_u5_female,\\n\\tCOUNT(uuid) FILTER(WHERE patient_age_in_months < 60) AS tot_u5_assessed,\\n\\tCOUNT(uuid) FILTER(WHERE patient_age_in_months < 12) AS tot_u1_assessed,\\n\\tSUM ((malaria_treatment IS NOT NULL)::int + (diarrhea_treatment IS NOT NULL)::int + (pneumonia_treatment IS NOT NULL)::int) AS num_treatments,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND malaria_treatment IS NOT NULL AND COALESCE(sex,'') ='male') AS malaria_treatment_u1_male,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND malaria_treatment IS NOT NULL AND COALESCE(sex,'') ='female') AS malaria_treatment_u1_female,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND malaria_treatment IS NOT NULL) AS u1_malaria_treatment,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND malaria_treatment IS NOT NULL AND COALESCE(sex,'') ='male') AS malaria_treatment_u5_male,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND malaria_treatment IS NOT NULL AND COALESCE(sex,'') ='female') AS malaria_treatment_u5_female,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND malaria_treatment IS NOT NULL) AS u5_malaria_treatment,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int >= 5 AND malaria_treatment IS NOT NULL AND COALESCE(sex,'') ='male') AS malaria_treatment_over5_male,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int >= 5 AND malaria_treatment IS NOT NULL AND COALESCE(sex,'') ='female') AS malaria_treatment_over5_female,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int >= 5 AND malaria_treatment IS NOT NULL) AS over5_malaria_treatment,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND diarrhea_treatment IS NOT NULL AND COALESCE(sex,'') ='male') AS diarrhea_treatment_u1_male,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND diarrhea_treatment IS NOT NULL AND COALESCE(sex,'') ='female') AS diarrhea_treatment_u1_female,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND diarrhea_treatment IS NOT NULL) AS u1_diarrhea_treatment,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND diarrhea_treatment IS NOT NULL AND COALESCE(sex,'') ='male') AS diarrhea_treatment_u5_male,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND diarrhea_treatment IS NOT NULL AND COALESCE(sex,'') ='female') AS diarrhea_treatment_u5_female,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND diarrhea_treatment IS NOT NULL) AS u5_diarrhea_treatment,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND pneumonia_treatment IS NOT NULL AND COALESCE(sex,'') ='male') AS ari_treatment_u1_male,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND pneumonia_treatment IS NOT NULL AND COALESCE(sex,'') ='female') AS ari_treatment_u1_female,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 1 AND pneumonia_treatment IS NOT NULL) AS u1_ari_treatment,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND pneumonia_treatment IS NOT NULL AND COALESCE(sex,'') ='male') AS ari_treatment_u5_male,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND pneumonia_treatment IS NOT NULL AND COALESCE(sex,'') ='female') AS ari_treatment_u5_female,\\n\\tCOUNT(uuid) FILTER (WHERE patient_age_in_years::int < 5 AND pneumonia_treatment IS NOT NULL) AS u5_ari_treatment,\\n\\tSUM ((COALESCE(mrdt_result,'')= 'positive'  AND COALESCE (patient_age_in_months,0) < 60)::int) AS tot_malaria_positive_u5,\\n\\tSUM ((COALESCE(mrdt_result,'')= 'positive'  AND COALESCE (patient_age_in_months,0) >= 60)::int) AS tot_malaria_positive_over5,\\t\\n\\tSUM ((COALESCE(mrdt_result,'')   ~* 'positive|negative'  AND COALESCE (patient_age_in_months,0) < 60)::int) AS tot_malaria_suspect_u5,\\n\\tSUM ((COALESCE(mrdt_result,'')   ~* 'positive|negative'  AND COALESCE (patient_age_in_months,0) >= 60)::int) AS tot_malaria_suspect_over5,\\n\\tSUM ((COALESCE(diagnosis_fever,'')   ~*  'malaria2|malaria1'  AND COALESCE (patient_age_in_months,0) <4  AND COALESCE(sex,'') ='male')::int) AS num_reffered_malaria_u5_male,/*All patients under 4 months are refferred*/\\n\\tSUM ((COALESCE(diagnosis_fever,'')   ~*  'malaria2|malaria1'  AND COALESCE (patient_age_in_months,0) <4 AND COALESCE(sex,'') ='female')::int) AS num_reffered_malaria_u5_female,\\n\\tSUM ((COALESCE(diagnosis_fever,'')   ~*  'malaria2|malaria1'  AND COALESCE (patient_age_in_months,0) >= 60  AND COALESCE(sex,'') ='male')::int) AS num_reffered_malaria_over5_male,\\n\\tSUM ((COALESCE(diagnosis_fever,'')   ~*  'malaria2|malaria1'  AND COALESCE (patient_age_in_months,0) >= 60 AND COALESCE(sex,'') ='female')::int) AS num_reffered_malaria_over5_female,\\n\\tSUM ((COALESCE(diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (patient_age_in_months,0) < 60 AND COALESCE(referral_follow_up,'')='true' AND COALESCE(sex,'') ='male')::int) AS num_reffered_diarrhea_u5_male,\\n\\tSUM ((COALESCE(diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (patient_age_in_months,0) < 60 AND COALESCE(referral_follow_up,'')='true' AND COALESCE(sex,'') ='female')::int) AS num_reffered_diarrhea_u5_female,\\n\\tSUM ((COALESCE(diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (patient_age_in_months,0) <60 AND COALESCE(referral_follow_up,'')='true'  AND COALESCE(sex,'') ='male')::int) AS num_reffered_ari_u5_male,\\n\\tSUM ((COALESCE(diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (patient_age_in_months,0) <60 AND COALESCE(referral_follow_up,'')='true' AND COALESCE(sex,'') ='female')::int) AS num_reffered_ari_u5_female\\n\\t\\nFROM {{ ref(\\"useview_assessment\\") }}\\n\\nWHERE \\n\\t\\t(date_trunc('month',useview_assessment.reported::timestamp)::date) >= (date_trunc('MONTH',({{startDate}})::DATE)::date) AND (date_trunc('month',useview_assessment.reported::timestamp)::DATE) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\t\\nGROUP BY \\narea_uuid,\\nreported_month\\n  \\n  ) AS assess ON ( assess. area_uuid = period_chp.area_uuid AND assess.reported_month = period_chp.date )\\n\\n LEFT JOIN\\n (\\n SELECT \\n\\tdate_trunc('MONTH',assess.reported::timestamp) reported_month, \\n\\tassess.reported_by_parent AS  area_uuid,\\n\\tSUM ((COALESCE(assess.diagnosis_fever,'')   ~*  'malaria2|malaria1'  AND COALESCE (assess.patient_age_in_months,0) <60 AND COALESCE(assess.referral_follow_up,'') ~* 'true')::int) AS num_accute_u5_malaria,\\n\\tSUM ((COALESCE(assess.diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (assess.patient_age_in_months,0) <60 AND COALESCE(assess.referral_follow_up,'') ~* 'true')::int) AS num_accute_u5_diarrhea,\\n\\tSUM ((COALESCE(assess.diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (assess.patient_age_in_months,0) <60 AND COALESCE(assess.referral_follow_up,'') ~* 'true')::int) AS num_accute_u5_ari,\\n\\tSUM ((COALESCE(assess.patient_age_in_months,0) < 60 AND COALESCE(assess.referral_follow_up,'') ~* 'true' )::int) AS num_u5_reffered_followed,\\n\\tSUM ((COALESCE(assess.diagnosis_fever,'')  ~* 'malaria2|malaria1'  AND COALESCE (assess.patient_age_in_months,0) <60  AND COALESCE(assess.treatment_follow_up,'')  ~* 'true' AND assess.reported >= follow_up.reported - interval '48 hours')::int) AS num_u5_followed_malaria,\\n\\tSUM ((COALESCE(assess.diagnosis_diarrhea,'')   ~* 'diarrhea2|diarrhea1'  AND COALESCE (assess.patient_age_in_months,0) <60 AND COALESCE(assess.treatment_follow_up,'')  ~* 'true'  AND assess.reported >= follow_up.reported - interval '48 hours')::int) AS num_u5_followed_diarrhea,\\n\\tSUM ((COALESCE(assess.diagnosis_cough,'')   ~* 'pneumonia1|pneumonia2b|pneumonia2c'  AND COALESCE (assess.patient_age_in_months,0) <60 AND COALESCE(assess.treatment_follow_up,'')  ~* 'true'  AND assess.reported >= follow_up.reported - interval '48 hours')::int) AS num_u5_followed_ari,\\n\\tSUM ((COALESCE(assess.patient_age_in_months,0) < 60 AND COALESCE(assess.treatment_follow_up,'')  ~* 'true'   AND assess.reported >= follow_up.reported - interval '48 hours')::int) AS num_u5_treated\\n\\nFROM {{ ref(\\"useview_assessment\\") }} AS assess\\n\\nINNER JOIN {{ ref(\\"useview_assessment_follow_up\\") }}  AS follow_up \\nON  assess.uuid = follow_up.form_source_id\\n\\nWHERE \\n\\t\\t(date_trunc('month',assess.reported::timestamp)::DATE) >= (date_trunc('MONTH',({{startDate}})::DATE)::timestamp) AND (date_trunc('month',assess.reported::timestamp)::date) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\n\\t\\nGROUP BY \\n\\treported_month, \\n\\tarea_uuid\\n \\n \\n ) AS follow_Up ON ( follow_Up. area_uuid = period_chp.area_uuid AND follow_Up.reported_month = period_chp.date )\\n\\n LEFT JOIN (\\n\\tWITH immunization_followup \\n\\tAS\\t(\\n\\t\\t\\tSELECT DISTINCT ON (patient_id)\\n\\t\\t\\t\\t\\"inputs/source_id\\",\\n\\t\\t\\t\\tvaccines_administered \\n\\t\\t\\tFROM {{ ref(\\"formview_immunization_follow_up\\") }}\\n\\t\\t\\tWHERE \\n\\t\\t\\t(date_trunc('month', reported::timestamp)::DATE) <= (date_trunc('MONTH',({{endDate}})::date)::date) \\n\\t\\t\\tORDER BY patient_id, reported DESC\\n\\t\\t)\\n\\tSELECT\\n\\t\\tdate_trunc('month', imm.reported::timestamp) reported_month,\\n\\t\\timm.reported_by_parent AS  area_uuid,\\n\\t\\tCOUNT(\\n\\t\\t\\tNULLIF(COALESCE(imm_given_2mo, imm_given_9mo, imm_given_18mo, fu.vaccines_administered), '')\\n\\t\\t) as num_u5_imm\\n\\tFROM {{ ref(\\"useview_assessment\\") }} imm\\n\\tLEFT JOIN {{ ref(\\"immunization_followup\\") }} fu ON \\"inputs/source_id\\" = imm.uuid\\n\\tWHERE \\n\\t\\tpatient_age_in_months < 60\\n\\t\\tAND (date_trunc('month', imm.reported::timestamp)::date) >= (date_trunc('month',({{startDate}})::date)::date) \\n\\t\\tAND (date_trunc('month', imm.reported)::date) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\tGROUP BY \\n\\t\\tarea_uuid, \\n\\t\\treported_month\\n ) immunization ON ( immunization.area_uuid = period_chp.area_uuid AND immunization.reported_month = period_chp.date )\\n\\n LEFT JOIN\\n (\\n\\tSELECT\\n\\t \\tdate_trunc('month', reported::timestamp)::date reported_month,\\n\\t\\treported_by_parent AS  area_uuid,\\n\\t \\tCOUNT(uuid) FILTER(WHERE referred_for_fp_method IS TRUE) AS long_term_fp_referrals\\n\\tFROM {{ ref(\\"fp_referral_cases\\") }}\\n\\tWHERE\\n\\t\\t(date_trunc('month', reported::timestamp)::date) >= (date_trunc('month',({{startDate}})::date)::date) \\n\\t\\tAND (date_trunc('month', reported::timestamp)::date) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\tGROUP BY \\n\\t\\tarea_uuid, \\n\\t\\treported_month\\n ) FPREFERRALS ON ( FPREFERRALS.area_uuid = period_chp.area_uuid AND FPREFERRALS.reported_month = period_chp.date )\\n\\n LEFT JOIN\\n (\\n\\t SELECT\\n\\t \\tdate_trunc('month', reported::timestamp) reported_month,\\n\\t\\treported_by_parent AS  area_uuid,\\n\\t\\tCOUNT(uuid) as COUNT,\\n\\t\\tCOUNT(uuid) FILTER(WHERE patient_age_in_years < 5) AS u5_count\\n\\tFROM {{ ref(\\"formview_death_confirmation\\") }}\\n\\tWHERE\\n\\t\\t(date_trunc('month', reported::timestamp)::DATE) >= (date_trunc('month',({{startDate}})::date)::date) \\n\\t\\tAND (date_trunc('month', reported::timestamp)::DATE) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\tGROUP BY \\n\\t\\tarea_uuid, \\n\\t\\treported_month\\n ) deaths ON (deaths.area_uuid = period_chp.area_uuid AND deaths.reported_month = period_chp.date)\\n \\n LEFT JOIN (\\n \\n \\tSELECT \\n\\t\\tSUM ((extract (YEAR from age(now()::date, to_date(person.date_of_birth,'YYYY-MM-DD')))::int >=12 AND extract (YEAR from age(now()::date, to_date(person.date_of_birth,'YYYY-MM-DD')))::int <=52  AND COALESCE(person.sex,'') ='female')::int) AS num_eligible_women,\\n\\t\\tSUM ((extract (YEAR from age(now()::date, to_date(person.date_of_birth,'YYYY-MM-DD')))::int < 5 )::int) AS num_u5_children,\\n\\t\\tCOUNT( DISTINCT(person.parent_uuid)) FILTER (WHERE extract (YEAR from age(now()::date, to_date(person.date_of_birth,'YYYY-MM-DD')))::int < 5) as num_hh_with_u5,\\n\\t\\tdate_trunc('month',person.reported::timestamp) AS reported_month,\\n\\t\\tmeta.PARENT_UUID AS area_uuid\\n\\tFROM {{ ref(\\"contactview_person\\") }} person\\n\\tLEFT JOIN {{ ref(\\"contactview_metadata\\") }} AS meta \\n\\tON person.parent_uuid = meta.UUID\\n\\t\\n\\tWHERE \\n\\t\\t(date_trunc('month',person.reported::timestamp)::DATE) >= (date_trunc('MONTH',({{startDate}})::date)::date) AND (date_trunc('month',person.reported::timestamp)::DATE) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\n\\n\\tGROUP BY \\n\\t\\tarea_uuid, \\n\\t\\treported_month \\n ) AS  demography ON  ( demography. area_uuid = period_chp.area_uuid AND demography.reported_month = period_chp.date )\\nLEFT JOIN\\n(\\n\\nSELECT \\n\\treported_by_parent AS area_uuid,\\n\\tdate_trunc('month',delivery_date::timestamp)::date AS reported_month,\\n\\tSUM((first_visit_on_time)::int) AS pnc_visit_48_hrs\\nFROM {{ ref(\\"pncview_actual_enrollments\\") }}\\nWHERE \\n\\t\\t(date_trunc('month',delivery_date::date)::date) >= (date_trunc('MONTH',({{startDate}})::date)::date) AND (date_trunc('month',delivery_date::date)::DATE) <= (date_trunc('MONTH',({{endDate}})::DATE)::date)\\n\\n\\nGROUP BY \\narea_uuid,\\nreported_month\\n\\n)AS  pnc ON  ( pnc. area_uuid = period_chp.area_uuid AND pnc.reported_month = period_chp.date )\\nLEFT JOIN \\n(\\n\\tSELECT \\n\\t\\treported_month, \\n\\t\\tarea_uuid, \\n\\t\\tSUM (((CASE \\n    \\t\\t\\tWHEN tt ='' THEN 0\\n    \\t\\t\\tELSE RIGHT(tt,1)::int END\\n    \\t\\t\\t)>0)::int) AS num_pregnant_immunized , \\n\\t\\tSUM (((CASE \\n    \\t\\t\\tWHEN anc_visit ='' THEN 0\\n    \\t\\t\\tELSE RIGHT(anc_visit,1)::int END\\n    \\t\\t\\t) > 0)::int ) AS num_anc_at_facility\\n\\tFROM {{ ref(\\"useview_pregnancy_visit\\") }}\\n    WHERE \\n\\treported_month::date >= (date_trunc('MONTH',({{startDate}})::date)::date) AND (reported_month::date) <= (date_trunc('MONTH',({{endDate}})::date)::date)\\n\\n\\tGROUP BY \\n \\t\\treported_month, \\n \\t\\tarea_uuid\\n) AS visit ON ( visit. area_uuid = period_chp.area_uuid AND visit.reported_month = period_chp.date )\\n{% endmacro %}", "unique_id": "macro.cht_pipeline_base.get_hmis_data", "created_at": 1758839281.3350322, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/get_hmis_data.sql", "supported_languages": null}, "macro.dbt.default__get_drop_index_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_drop_index_sql", "path": "macros/adapters/indexes.sql", "arguments": [], "macro_sql": "{% macro default__get_drop_index_sql(relation, index_name) -%}\\n    {{ exceptions.raise_compiler_error(\\"`get_drop_index_sql has not been implemented for this adapter.\\") }}\\n{%- endmacro %}", "unique_id": "macro.dbt.default__get_drop_index_sql", "created_at": 1758839280.9994314, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/indexes.sql", "supported_languages": null}, "macro.dbt.default__get_show_grant_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_show_grant_sql", "path": "macros/adapters/apply_grants.sql", "arguments": [], "macro_sql": "{% macro default__get_show_grant_sql(relation) %}\\n    show grants on {{ relation.render() }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_show_grant_sql", "created_at": 1758839281.027395, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/apply_grants.sql", "supported_languages": null}, "macro.dbt.default__get_where_subquery": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_where_subquery", "path": "macros/materializations/tests/where_subquery.sql", "arguments": [], "macro_sql": "{% macro default__get_where_subquery(relation) -%}\\n    {% set where = config.get('where', '') %}\\n    {% if where %}\\n        {%- set filtered -%}\\n            (select * from {{ relation }} where {{ where }}) dbt_subquery\\n        {%- endset -%}\\n        {% do return(filtered) %}\\n    {%- else -%}\\n        {% do return(relation) %}\\n    {%- endif -%}\\n{%- endmacro %}", "unique_id": "macro.dbt.default__get_where_subquery", "created_at": 1758839280.9446366, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/tests/where_subquery.sql", "supported_languages": null}, "macro.dbt.default__make_temp_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__make_temp_relation", "path": "macros/adapters/relation.sql", "arguments": [], "macro_sql": "{% macro default__make_temp_relation(base_relation, suffix) %}\\n    {%- set temp_identifier = base_relation.identifier ~ suffix -%}\\n    {%- set temp_relation = base_relation.incorporate(\\n                                path={\\"identifier\\": temp_identifier}) -%}\\n\\n    {{ return(temp_relation) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__make_temp_relation", "created_at": 1758839281.018574, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/relation.sql", "supported_languages": null}, "macro.dbt.default__resolve_model_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__resolve_model_name", "path": "macros/python_model/python.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__resolve_model_name(input_model_name) -%}\\n    {{  input_model_name | string | replace('\\"', '\\\\\\"') }}\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt.default__resolve_model_name", "created_at": 1758839280.976453, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/python_model/python.sql", "supported_languages": null}, "macro.dbt.default__snapshot_merge_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__snapshot_merge_sql", "path": "macros/materializations/snapshots/snapshot_merge.sql", "arguments": [], "macro_sql": "{% macro default__snapshot_merge_sql(target, source, insert_cols) -%}\\n    {%- set insert_cols_csv = insert_cols | join(', ') -%}\\n\\n    {%- set columns = config.get(\\"snapshot_table_column_names\\") or get_snapshot_table_column_names() -%}\\n\\n    merge into {{ target.render() }} as DBT_INTERNAL_DEST\\n    using {{ source }} as DBT_INTERNAL_SOURCE\\n    on DBT_INTERNAL_SOURCE.{{ columns.dbt_scd_id }} = DBT_INTERNAL_DEST.{{ columns.dbt_scd_id }}\\n\\n    when matched\\n     {% if config.get(\\"dbt_valid_to_current\\") %}\\n\\t{% set source_unique_key = (\\"DBT_INTERNAL_DEST.\\" ~ columns.dbt_valid_to) | trim %}\\n\\t{% set target_unique_key = config.get('dbt_valid_to_current') | trim %}\\n\\tand ({{ equals(source_unique_key, target_unique_key) }} or {{ source_unique_key }} is null)\\n\\n     {% else %}\\n       and DBT_INTERNAL_DEST.{{ columns.dbt_valid_to }} is null\\n     {% endif %}\\n     and DBT_INTERNAL_SOURCE.dbt_change_type in ('update', 'delete')\\n        then update\\n        set {{ columns.dbt_valid_to }} = DBT_INTERNAL_SOURCE.{{ columns.dbt_valid_to }}\\n\\n    when not matched\\n     and DBT_INTERNAL_SOURCE.dbt_change_type = 'insert'\\n        then insert ({{ insert_cols_csv }})\\n        values ({{ insert_cols_csv }})\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__snapshot_merge_sql", "created_at": 1758839280.8820417, "depends_on": {"macros": ["macro.dbt.get_snapshot_table_column_names", "macro.dbt.equals"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/snapshot_merge.sql", "supported_languages": null}, "macro.dbt.default__test_relationships": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_relationships", "path": "macros/generic_test_sql/relationships.sql", "arguments": [], "macro_sql": "{% macro default__test_relationships(model, column_name, to, field) %}\\n\\nwith child as (\\n    select {{ column_name }} as from_field\\n    from {{ model }}\\n    where {{ column_name }} is not null\\n),\\n\\nparent as (\\n    select {{ field }} as to_field\\n    from {{ to }}\\n)\\n\\nselect\\n    from_field\\n\\nfrom child\\nleft join parent\\n    on child.from_field = parent.to_field\\n\\nwhere parent.to_field is null\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__test_relationships", "created_at": 1758839280.8326988, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/generic_test_sql/relationships.sql", "supported_languages": null}, "macro.dbt.get_create_intermediate_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_create_intermediate_sql", "path": "macros/relations/create_intermediate.sql", "arguments": [], "macro_sql": "{%- macro get_create_intermediate_sql(relation, sql) -%}\\n    {{- log('Applying CREATE INTERMEDIATE to: ' ~ relation) -}}\\n    {{- adapter.dispatch('get_create_intermediate_sql', 'dbt')(relation, sql) -}}\\n{%- endmacro -%}\\n\\n\\n", "unique_id": "macro.dbt.get_create_intermediate_sql", "created_at": 1758839280.7772613, "depends_on": {"macros": ["macro.dbt.default__get_create_intermediate_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/create_intermediate.sql", "supported_languages": null}, "macro.dbt.get_delete_insert_merge_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_delete_insert_merge_sql", "path": "macros/materializations/models/incremental/merge.sql", "arguments": [], "macro_sql": "{% macro get_delete_insert_merge_sql(target, source, unique_key, dest_columns, incremental_predicates) -%}\\n  {{ adapter.dispatch('get_delete_insert_merge_sql', 'dbt')(target, source, unique_key, dest_columns, incremental_predicates) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.get_delete_insert_merge_sql", "created_at": 1758839280.90437, "depends_on": {"macros": ["macro.dbt.default__get_delete_insert_merge_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/merge.sql", "supported_languages": null}, "macro.dbt.get_incremental_default_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_incremental_default_sql", "path": "macros/materializations/models/incremental/strategies.sql", "arguments": [], "macro_sql": "{% macro get_incremental_default_sql(arg_dict) %}\\n\\n  {{ return(adapter.dispatch('get_incremental_default_sql', 'dbt')(arg_dict)) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.get_incremental_default_sql", "created_at": 1758839280.927213, "depends_on": {"macros": ["macro.dbt_postgres.postgres__get_incremental_default_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/strategies.sql", "supported_languages": null}, "macro.dbt.get_rename_intermediate_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_rename_intermediate_sql", "path": "macros/relations/rename_intermediate.sql", "arguments": [], "macro_sql": "{%- macro get_rename_intermediate_sql(relation) -%}\\n    {{- log('Applying RENAME INTERMEDIATE to: ' ~ relation) -}}\\n    {{- adapter.dispatch('get_rename_intermediate_sql', 'dbt')(relation) -}}\\n{%- endmacro -%}\\n\\n\\n", "unique_id": "macro.dbt.get_rename_intermediate_sql", "created_at": 1758839280.7854505, "depends_on": {"macros": ["macro.dbt.default__get_rename_intermediate_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/rename_intermediate.sql", "supported_languages": null}, "macro.dbt.snapshot_timestamp_strategy": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snapshot_timestamp_strategy", "path": "macros/materializations/snapshots/strategies.sql", "arguments": [], "macro_sql": "{% macro snapshot_timestamp_strategy(node, snapshotted_rel, current_rel, model_config, target_exists) %}\\n    {# The model_config parameter is no longer used, but is passed in anyway for compatibility. #}\\n    {% set primary_key = config.get('unique_key') %}\\n    {% set updated_at = config.get('updated_at') %}\\n    {% set hard_deletes = adapter.get_hard_deletes_behavior(config) %}\\n    {% set invalidate_hard_deletes = hard_deletes == 'invalidate' %}\\n    {% set columns = config.get(\\"snapshot_table_column_names\\") or get_snapshot_table_column_names() %}\\n\\n    {#/*\\n        The snapshot relation might not have an {{ updated_at }} value if the\\n        snapshot strategy is changed from `check` to `timestamp`. We\\n        should use a dbt-created column for the comparison in the snapshot\\n        table instead of assuming that the user-supplied {{ updated_at }}\\n        will be present in the historical data.\\n\\n        See https://github.com/dbt-labs/dbt-core/issues/2350\\n    */ #}\\n    {% set row_changed_expr -%}\\n        ({{ snapshotted_rel }}.{{ columns.dbt_valid_from }} < {{ current_rel }}.{{ updated_at }})\\n    {%- endset %}\\n\\n    {% set scd_args = api.Relation.scd_args(primary_key, updated_at) %}\\n    {% set scd_id_expr = snapshot_hash_arguments(scd_args) %}\\n\\n    {% do return({\\n        \\"unique_key\\": primary_key,\\n        \\"updated_at\\": updated_at,\\n        \\"row_changed\\": row_changed_expr,\\n        \\"scd_id\\": scd_id_expr,\\n        \\"invalidate_hard_deletes\\": invalidate_hard_deletes,\\n        \\"hard_deletes\\": hard_deletes\\n    }) %}\\n{% endmacro %}", "unique_id": "macro.dbt.snapshot_timestamp_strategy", "created_at": 1758839280.8726282, "depends_on": {"macros": ["macro.dbt.get_snapshot_table_column_names", "macro.dbt.snapshot_hash_arguments"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/strategies.sql", "supported_languages": null}, "macro.dbt_date.duckdb__iso_week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "duckdb__iso_week_start", "path": "macros/calendar_date/iso_week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro duckdb__iso_week_start(date) -%}\\n{{ return(dbt_date.postgres__iso_week_start(date)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.duckdb__iso_week_start", "created_at": 1758839281.1519945, "depends_on": {"macros": ["macro.dbt_date.postgres__iso_week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_start.sql", "supported_languages": null}, "macro.dbt_date.postgres__week_of_year": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__week_of_year", "path": "macros/calendar_date/week_of_year.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro postgres__week_of_year(date) -%}\\n{# postgresql 'week' returns isoweek. Use to_char instead.\\n   WW = the first week starts on the first day of the year #}\\ncast(to_char({{ date }}, 'WW') as {{ dbt.type_int() }})\\n{%- endmacro %}", "unique_id": "macro.dbt_date.postgres__week_of_year", "created_at": 1758839281.1595902, "depends_on": {"macros": ["macro.dbt.type_int"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_of_year.sql", "supported_languages": null}, "macro.dbt_date.redshift__day_of_month": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "redshift__day_of_month", "path": "macros/calendar_date/day_of_month.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro redshift__day_of_month(date) -%}\\ncast({{ dbt_date.date_part('day', date) }} as {{ dbt.type_bigint() }})\\n{%- endmacro %}", "unique_id": "macro.dbt_date.redshift__day_of_month", "created_at": 1758839281.1854205, "depends_on": {"macros": ["macro.dbt_date.date_part", "macro.dbt.type_bigint"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_of_month.sql", "supported_languages": null}, "macro.dbt_date.snowflake__day_of_week": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snowflake__day_of_week", "path": "macros/calendar_date/day_of_week.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro snowflake__day_of_week(date, isoweek) -%}\\n\\n    {%- if isoweek -%}\\n        {%- set dow_part = 'dayofweekiso' -%}\\n        {{ dbt_date.date_part(dow_part, date) }}\\n    {%- else -%}\\n        {%- set dow_part = 'dayofweek' -%}\\n        case\\n            when {{ dbt_date.date_part(dow_part, date) }} = 7 then 1\\n            else {{ dbt_date.date_part(dow_part, date) }} + 1\\n        end\\n    {%- endif -%}\\n\\n\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_date.snowflake__day_of_week", "created_at": 1758839281.1880248, "depends_on": {"macros": ["macro.dbt_date.date_part"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_of_week.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__datediff": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__datediff", "path": "macros/utils/datediff.sql", "arguments": [], "macro_sql": "{% macro postgres__datediff(first_date, second_date, datepart) -%}\\n\\n    {% if datepart == 'year' %}\\n        (date_part('year', ({{second_date}})::date) - date_part('year', ({{first_date}})::date))\\n    {% elif datepart == 'quarter' %}\\n        ({{ datediff(first_date, second_date, 'year') }} * 4 + date_part('quarter', ({{second_date}})::date) - date_part('quarter', ({{first_date}})::date))\\n    {% elif datepart == 'month' %}\\n        ({{ datediff(first_date, second_date, 'year') }} * 12 + date_part('month', ({{second_date}})::date) - date_part('month', ({{first_date}})::date))\\n    {% elif datepart == 'day' %}\\n        (({{second_date}})::date - ({{first_date}})::date)\\n    {% elif datepart == 'week' %}\\n        ({{ datediff(first_date, second_date, 'day') }} / 7 + case\\n            when date_part('dow', ({{first_date}})::timestamp) <= date_part('dow', ({{second_date}})::timestamp) then\\n                case when {{first_date}} <= {{second_date}} then 0 else -1 end\\n            else\\n                case when {{first_date}} <= {{second_date}} then 1 else 0 end\\n        end)\\n    {% elif datepart == 'hour' %}\\n        ({{ datediff(first_date, second_date, 'day') }} * 24 + date_part('hour', ({{second_date}})::timestamp) - date_part('hour', ({{first_date}})::timestamp))\\n    {% elif datepart == 'minute' %}\\n        ({{ datediff(first_date, second_date, 'hour') }} * 60 + date_part('minute', ({{second_date}})::timestamp) - date_part('minute', ({{first_date}})::timestamp))\\n    {% elif datepart == 'second' %}\\n        ({{ datediff(first_date, second_date, 'minute') }} * 60 + floor(date_part('second', ({{second_date}})::timestamp)) - floor(date_part('second', ({{first_date}})::timestamp)))\\n    {% elif datepart == 'millisecond' %}\\n        ({{ datediff(first_date, second_date, 'minute') }} * 60000 + floor(date_part('millisecond', ({{second_date}})::timestamp)) - floor(date_part('millisecond', ({{first_date}})::timestamp)))\\n    {% elif datepart == 'microsecond' %}\\n        ({{ datediff(first_date, second_date, 'minute') }} * 60000000 + floor(date_part('microsecond', ({{second_date}})::timestamp)) - floor(date_part('microsecond', ({{first_date}})::timestamp)))\\n    {% else %}\\n        {{ exceptions.raise_compiler_error(\\"Unsupported datepart for macro datediff in postgres: {!r}\\".format(datepart)) }}\\n    {% endif %}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__datediff", "created_at": 1758839280.7689037, "depends_on": {"macros": ["macro.dbt.datediff"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/utils/datediff.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__last_day": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__last_day", "path": "macros/utils/last_day.sql", "arguments": [], "macro_sql": "{% macro postgres__last_day(date, datepart) -%}\\n\\n    {%- if datepart == 'quarter' -%}\\n    -- postgres dateadd does not support quarter interval.\\n    cast(\\n        {{dbt.dateadd('day', '-1',\\n        dbt.dateadd('month', '3', dbt.date_trunc(datepart, date))\\n        )}}\\n        as date)\\n    {%- else -%}\\n    {{dbt.default_last_day(date, datepart)}}\\n    {%- endif -%}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__last_day", "created_at": 1758839280.765138, "depends_on": {"macros": ["macro.dbt.dateadd", "macro.dbt.date_trunc", "macro.dbt.default_last_day"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/utils/last_day.sql", "supported_languages": null}, "macro.dbt_utils.bigquery__deduplicate": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "bigquery__deduplicate", "path": "macros/sql/deduplicate.sql", "arguments": [], "macro_sql": "\\n{%- macro bigquery__deduplicate(relation, partition_by, order_by) -%}\\n\\n    select unique.*\\n    from (\\n        select\\n            array_agg (\\n                original\\n                order by {{ order_by }}\\n                limit 1\\n            )[offset(0)] unique\\n        from {{ relation }} original\\n        group by {{ partition_by }}\\n    )\\n\\n{%- endmacro -%}", "unique_id": "macro.dbt_utils.bigquery__deduplicate", "created_at": 1758839281.2102368, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/deduplicate.sql", "supported_languages": null}, "macro.dbt_utils.default__get_url_host": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_url_host", "path": "macros/web/get_url_host.sql", "arguments": [], "macro_sql": "{% macro default__get_url_host(field) -%}\\n\\n{%- set parsed =\\n    dbt.split_part(\\n        dbt.split_part(\\n            dbt.replace(\\n                dbt.replace(\\n                    dbt.replace(field, \\"'android-app://'\\", \\"''\\"\\n                    ), \\"'http://'\\", \\"''\\"\\n                ), \\"'https://'\\", \\"''\\"\\n            ), \\"'/'\\", 1\\n        ), \\"'?'\\", 1\\n    )\\n\\n-%}\\n\\n\\n    {{ dbt.safe_cast(\\n        parsed,\\n        dbt.type_string()\\n        )}}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_utils.default__get_url_host", "created_at": 1758839281.2659109, "depends_on": {"macros": ["macro.dbt.split_part", "macro.dbt.replace", "macro.dbt.safe_cast", "macro.dbt.type_string"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/web/get_url_host.sql", "supported_languages": null}, "macro.dbt_utils.default__get_url_path": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_url_path", "path": "macros/web/get_url_path.sql", "arguments": [], "macro_sql": "{% macro default__get_url_path(field) -%}\\n\\n    {%- set stripped_url =\\n        dbt.replace(\\n            dbt.replace(field, \\"'http://'\\", \\"''\\"), \\"'https://'\\", \\"''\\")\\n    -%}\\n\\n    {%- set first_slash_pos -%}\\n        coalesce(\\n            nullif({{ dbt.position(\\"'/'\\", stripped_url) }}, 0),\\n            {{ dbt.position(\\"'?'\\", stripped_url) }} - 1\\n            )\\n    {%- endset -%}\\n\\n    {%- set parsed_path =\\n        dbt.split_part(\\n            dbt.right(\\n                stripped_url,\\n                dbt.length(stripped_url) ~ \\"-\\" ~ first_slash_pos\\n                ),\\n            \\"'?'\\", 1\\n            )\\n    -%}\\n\\n    {{ dbt.safe_cast(\\n        parsed_path,\\n        dbt.type_string()\\n    )}}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_utils.default__get_url_path", "created_at": 1758839281.2631996, "depends_on": {"macros": ["macro.dbt.replace", "macro.dbt.position", "macro.dbt.split_part", "macro.dbt.right", "macro.dbt.length", "macro.dbt.safe_cast", "macro.dbt.type_string"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/web/get_url_path.sql", "supported_languages": null}, "macro.dbt_utils.default__test_recency": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_recency", "path": "macros/generic_tests/recency.sql", "arguments": [], "macro_sql": "{% macro default__test_recency(model, field, datepart, interval, ignore_time_component, group_by_columns) %}\\n\\n{% set threshold = 'cast(' ~ dbt.dateadd(datepart, interval * -1, dbt.current_timestamp()) ~ ' as ' ~ ('date' if ignore_time_component else dbt.type_timestamp()) ~ ')'  %}\\n\\n{% if group_by_columns|length() > 0 %}\\n  {% set select_gb_cols = group_by_columns|join(' ,') + ', ' %}\\n  {% set groupby_gb_cols = 'group by ' + group_by_columns|join(',') %}\\n{% endif %}\\n\\n\\nwith recency as (\\n\\n    select \\n\\n      {{ select_gb_cols }}\\n      {% if ignore_time_component %}\\n        cast(max({{ field }}) as date) as most_recent\\n      {%- else %}\\n        max({{ field }}) as most_recent\\n      {%- endif %}\\n\\n    from {{ model }}\\n\\n    {{ groupby_gb_cols }}\\n\\n)\\n\\nselect\\n\\n    {{ select_gb_cols }}\\n    most_recent,\\n    {{ threshold }} as threshold\\n\\nfrom recency\\nwhere most_recent < {{ threshold }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_recency", "created_at": 1758839281.2882192, "depends_on": {"macros": ["macro.dbt.dateadd", "macro.dbt.current_timestamp", "macro.dbt.type_timestamp"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/recency.sql", "supported_languages": null}, "macro.dbt_utils.default__width_bucket": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__width_bucket", "path": "macros/sql/width_bucket.sql", "arguments": [], "macro_sql": "{% macro default__width_bucket(expr, min_value, max_value, num_buckets) -%}\\n\\n    {% set bin_size -%}\\n    (( {{ max_value }} - {{ min_value }} ) / {{ num_buckets }} )\\n    {%- endset %}\\n    (\\n        -- to break ties when the amount is eaxtly at the bucket egde\\n        case\\n            when\\n                mod(\\n                    {{ dbt.safe_cast(expr, dbt.type_numeric() ) }},\\n                    {{ dbt.safe_cast(bin_size, dbt.type_numeric() ) }}\\n                ) = 0\\n            then 1\\n            else 0\\n        end\\n    ) +\\n      -- Anything over max_value goes the N+1 bucket\\n    least(\\n        ceil(\\n            ({{ expr }} - {{ min_value }})/{{ bin_size }}\\n        ),\\n        {{ num_buckets }} + 1\\n    )\\n{%- endmacro %}", "unique_id": "macro.dbt_utils.default__width_bucket", "created_at": 1758839281.2417088, "depends_on": {"macros": ["macro.dbt.safe_cast", "macro.dbt.type_numeric"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/width_bucket.sql", "supported_languages": null}, "macro.dbt_utils.get_intervals_between": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_intervals_between", "path": "macros/sql/date_spine.sql", "arguments": [], "macro_sql": "{% macro get_intervals_between(start_date, end_date, datepart) -%}\\n    {{ return(adapter.dispatch('get_intervals_between', 'dbt_utils')(start_date, end_date, datepart)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_utils.get_intervals_between", "created_at": 1758839281.1923015, "depends_on": {"macros": ["macro.dbt_utils.default__get_intervals_between"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/date_spine.sql", "supported_languages": null}, "macro.dbt_utils.postgres__deduplicate": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__deduplicate", "path": "macros/sql/deduplicate.sql", "arguments": [], "macro_sql": "\\n{%- macro postgres__deduplicate(relation, partition_by, order_by) -%}\\n\\n    select\\n        distinct on ({{ partition_by }}) *\\n    from {{ relation }}\\n    order by {{ partition_by }}{{ ',' ~ order_by }}\\n\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_utils.postgres__deduplicate", "created_at": 1758839281.209474, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/deduplicate.sql", "supported_languages": null}, "macro.dbt_utils.redshift__deduplicate": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "redshift__deduplicate", "path": "macros/sql/deduplicate.sql", "arguments": [], "macro_sql": "{% macro redshift__deduplicate(relation, partition_by, order_by) -%}\\n\\n    {{ return(dbt_utils.default__deduplicate(relation, partition_by, order_by=order_by)) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.redshift__deduplicate", "created_at": 1758839281.2090912, "depends_on": {"macros": ["macro.dbt_utils.default__deduplicate"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/deduplicate.sql", "supported_languages": null}, "macro.dbt_utils.test_not_empty_string": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_not_empty_string", "path": "macros/generic_tests/not_empty_string.sql", "arguments": [], "macro_sql": "{% test not_empty_string(model, column_name, trim_whitespace=true) %}\\n\\n  {{ return(adapter.dispatch('test_not_empty_string', 'dbt_utils')(model, column_name, trim_whitespace)) }}\\n\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_not_empty_string", "created_at": 1758839281.2754898, "depends_on": {"macros": ["macro.dbt_utils.default__test_not_empty_string"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/not_empty_string.sql", "supported_languages": null}, "macro.dbt.build_snapshot_staging_table": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "build_snapshot_staging_table", "path": "macros/materializations/snapshots/helpers.sql", "arguments": [], "macro_sql": "{% macro build_snapshot_staging_table(strategy, sql, target_relation) %}\\n    {% set temp_relation = make_temp_relation(target_relation) %}\\n\\n    {% set select = snapshot_staging_table(strategy, sql, target_relation) %}\\n\\n    {% call statement('build_snapshot_staging_relation') %}\\n        {{ create_table_as(True, temp_relation, select) }}\\n    {% endcall %}\\n\\n    {% do return(temp_relation) %}\\n{% endmacro %}", "unique_id": "macro.dbt.build_snapshot_staging_table", "created_at": 1758839280.853514, "depends_on": {"macros": ["macro.dbt.make_temp_relation", "macro.dbt.snapshot_staging_table", "macro.dbt.statement", "macro.dbt.create_table_as"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/helpers.sql", "supported_languages": null}, "macro.dbt.collect_freshness_custom_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "collect_freshness_custom_sql", "path": "macros/adapters/freshness.sql", "arguments": [], "macro_sql": "{% macro collect_freshness_custom_sql(source, loaded_at_query) %}\\n  {{ return(adapter.dispatch('collect_freshness_custom_sql', 'dbt')(source, loaded_at_query))}}\\n{% endmacro %}", "unique_id": "macro.dbt.collect_freshness_custom_sql", "created_at": 1758839281.0132613, "depends_on": {"macros": ["macro.dbt.default__collect_freshness_custom_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/freshness.sql", "supported_languages": null}, "macro.dbt.current_timestamp_backcompat": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "current_timestamp_backcompat", "path": "macros/adapters/timestamps.sql", "arguments": [], "macro_sql": "{% macro current_timestamp_backcompat() %}\\n    {{ return(adapter.dispatch('current_timestamp_backcompat', 'dbt')()) }}\\n{% endmacro %}", "unique_id": "macro.dbt.current_timestamp_backcompat", "created_at": 1758839281.0496495, "depends_on": {"macros": ["macro.dbt_postgres.postgres__current_timestamp_backcompat"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/timestamps.sql", "supported_languages": null}, "macro.dbt.default__call_dcl_statements": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__call_dcl_statements", "path": "macros/adapters/apply_grants.sql", "arguments": [], "macro_sql": "{% macro default__call_dcl_statements(dcl_statement_list) %}\\n    {#\\n      -- By default, supply all grant + revoke statements in a single semicolon-separated block,\\n      -- so that they're all processed together.\\n\\n      -- Some databases do not support this. Those adapters will need to override this macro\\n      -- to run each statement individually.\\n    #}\\n    {% call statement('grants') %}\\n        {% for dcl_statement in dcl_statement_list %}\\n            {{ dcl_statement }};\\n        {% endfor %}\\n    {% endcall %}\\n{% endmacro %}", "unique_id": "macro.dbt.default__call_dcl_statements", "created_at": 1758839281.031658, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/apply_grants.sql", "supported_languages": null}, "macro.dbt.default__check_schema_exists": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__check_schema_exists", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro default__check_schema_exists(information_schema, schema) -%}\\n  {% set sql -%}\\n        select count(*)\\n        from {{ information_schema.replace(information_schema_view='SCHEMATA') }}\\n        where catalog_name='{{ information_schema.database }}'\\n          and schema_name='{{ schema }}'\\n  {%- endset %}\\n  {{ return(run_query(sql)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__check_schema_exists", "created_at": 1758839281.006844, "depends_on": {"macros": ["macro.dbt.replace", "macro.dbt.run_query"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt.default__generate_alias_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__generate_alias_name", "path": "macros/get_custom_name/get_custom_alias.sql", "arguments": [], "macro_sql": "{% macro default__generate_alias_name(custom_alias_name=none, node=none) -%}\\n\\n    {%- if custom_alias_name -%}\\n\\n        {{ custom_alias_name | trim }}\\n\\n    {%- elif node.version -%}\\n\\n        {{ return(node.name ~ \\"_v\\" ~ (node.version | replace(\\".\\", \\"_\\"))) }}\\n\\n    {%- else -%}\\n\\n        {{ node.name }}\\n\\n    {%- endif -%}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt.default__generate_alias_name", "created_at": 1758839280.7735257, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/get_custom_name/get_custom_alias.sql", "supported_languages": null}, "macro.dbt.default__get_drop_backup_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_drop_backup_sql", "path": "macros/relations/drop_backup.sql", "arguments": [], "macro_sql": "{%- macro default__get_drop_backup_sql(relation) -%}\\n\\n    -- get the standard backup name\\n    {% set backup_relation = make_backup_relation(relation, relation.type) %}\\n\\n    {{ get_drop_sql(backup_relation) }}\\n\\n{%- endmacro -%}", "unique_id": "macro.dbt.default__get_drop_backup_sql", "created_at": 1758839280.7756934, "depends_on": {"macros": ["macro.dbt.make_backup_relation", "macro.dbt.get_drop_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/drop_backup.sql", "supported_languages": null}, "macro.dbt.default__get_rename_view_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_rename_view_sql", "path": "macros/relations/view/rename.sql", "arguments": [], "macro_sql": "{% macro default__get_rename_view_sql(relation, new_name) %}\\n    {{ exceptions.raise_compiler_error(\\n        \\"`get_rename_view_sql` has not been implemented for this adapter.\\"\\n    ) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_rename_view_sql", "created_at": 1758839280.7954257, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/view/rename.sql", "supported_languages": null}, "macro.dbt.default__get_select_subquery": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_select_subquery", "path": "macros/relations/table/create.sql", "arguments": [], "macro_sql": "{% macro default__get_select_subquery(sql) %}\\n    select {{ adapter.dispatch('get_column_names', 'dbt')() }}\\n    from (\\n        {{ sql }}\\n    ) as model_subq\\n{%- endmacro %}", "unique_id": "macro.dbt.default__get_select_subquery", "created_at": 1758839280.805174, "depends_on": {"macros": ["macro.dbt.default__get_column_names"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/table/create.sql", "supported_languages": null}, "macro.dbt.generate_schema_name_for_env": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "generate_schema_name_for_env", "path": "macros/get_custom_name/get_custom_schema.sql", "arguments": [], "macro_sql": "{% macro generate_schema_name_for_env(custom_schema_name, node) -%}\\n\\n    {%- set default_schema = target.schema -%}\\n    {%- if target.name == 'prod' and custom_schema_name is not none -%}\\n\\n        {{ custom_schema_name | trim }}\\n\\n    {%- else -%}\\n\\n        {{ default_schema }}\\n\\n    {%- endif -%}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt.generate_schema_name_for_env", "created_at": 1758839280.772098, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/get_custom_name/get_custom_schema.sql", "supported_languages": null}, "macro.dbt.get_column_schema_from_query": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_column_schema_from_query", "path": "macros/adapters/columns.sql", "arguments": [], "macro_sql": "{% macro get_column_schema_from_query(select_sql, select_sql_header=none) -%}\\n    {% set columns = [] %}\\n    {# -- Using an 'empty subquery' here to get the same schema as the given select_sql statement, without necessitating a data scan.#}\\n    {% set sql = get_empty_subquery_sql(select_sql, select_sql_header) %}\\n    {% set column_schema = adapter.get_column_schema_from_query(sql) %}\\n    {{ return(column_schema) }}\\n{% endmacro %}", "unique_id": "macro.dbt.get_column_schema_from_query", "created_at": 1758839281.0420756, "depends_on": {"macros": ["macro.dbt.get_empty_subquery_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/columns.sql", "supported_languages": null}, "macro.dbt.materialization_seed_default": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialization_seed_default", "path": "macros/materializations/seeds/seed.sql", "arguments": [], "macro_sql": "{% materialization seed, default %}\\n\\n  {%- set identifier = model['alias'] -%}\\n  {%- set full_refresh_mode = (should_full_refresh()) -%}\\n\\n  {%- set old_relation = adapter.get_relation(database=database, schema=schema, identifier=identifier) -%}\\n\\n  {%- set exists_as_table = (old_relation is not none and old_relation.is_table) -%}\\n  {%- set exists_as_view = (old_relation is not none and old_relation.is_view) -%}\\n\\n  {%- set grant_config = config.get('grants') -%}\\n  {%- set agate_table = load_agate_table() -%}\\n  -- grab current tables grants config for comparison later on\\n\\n  {%- do store_result('agate_table', response='OK', agate_table=agate_table) -%}\\n\\n  {{ run_hooks(pre_hooks, inside_transaction=False) }}\\n\\n  -- `BEGIN` happens here:\\n  {{ run_hooks(pre_hooks, inside_transaction=True) }}\\n\\n  -- build model\\n  {% set create_table_sql = \\"\\" %}\\n  {% if exists_as_view %}\\n    {{ exceptions.raise_compiler_error(\\"Cannot seed to '{}', it is a view\\".format(old_relation.render())) }}\\n  {% elif exists_as_table %}\\n    {% set create_table_sql = reset_csv_table(model, full_refresh_mode, old_relation, agate_table) %}\\n  {% else %}\\n    {% set create_table_sql = create_csv_table(model, agate_table) %}\\n  {% endif %}\\n\\n  {% set code = 'CREATE' if full_refresh_mode else 'INSERT' %}\\n  {% set rows_affected = (agate_table.rows | length) %}\\n  {% set sql = load_csv_rows(model, agate_table) %}\\n\\n  {% call noop_statement('main', code ~ ' ' ~ rows_affected, code, rows_affected) %}\\n    {{ get_csv_sql(create_table_sql, sql) }};\\n  {% endcall %}\\n\\n  {% set target_relation = this.incorporate(type='table') %}\\n\\n  {% set should_revoke = should_revoke(old_relation, full_refresh_mode) %}\\n  {% do apply_grants(target_relation, grant_config, should_revoke=should_revoke) %}\\n\\n  {% do persist_docs(target_relation, model) %}\\n\\n  {% if full_refresh_mode or not exists_as_table %}\\n    {% do create_indexes(target_relation) %}\\n  {% endif %}\\n\\n  {{ run_hooks(post_hooks, inside_transaction=True) }}\\n\\n  -- `COMMIT` happens here\\n  {{ adapter.commit() }}\\n\\n  {{ run_hooks(post_hooks, inside_transaction=False) }}\\n\\n  {{ return({'relations': [target_relation]}) }}\\n\\n{% endmaterialization %}", "unique_id": "macro.dbt.materialization_seed_default", "created_at": 1758839280.9605331, "depends_on": {"macros": ["macro.dbt.should_full_refresh", "macro.dbt.run_hooks", "macro.dbt.reset_csv_table", "macro.dbt.create_csv_table", "macro.dbt.load_csv_rows", "macro.dbt.noop_statement", "macro.dbt.get_csv_sql", "macro.dbt.should_revoke", "macro.dbt.apply_grants", "macro.dbt.persist_docs", "macro.dbt.create_indexes"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/seeds/seed.sql", "supported_languages": ["sql"]}, "macro.dbt.materialization_test_default": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialization_test_default", "path": "macros/materializations/tests/test.sql", "arguments": [], "macro_sql": "{%- materialization test, default -%}\\n\\n  {% set relations = [] %}\\n  {% set limit = config.get('limit') %}\\n\\n  {% set sql_with_limit %}\\n    {{ get_limit_subquery_sql(sql, limit) }}\\n  {% endset %}\\n\\n  {% if should_store_failures() %}\\n\\n    {% set identifier = model['alias'] %}\\n    {% set old_relation = adapter.get_relation(database=database, schema=schema, identifier=identifier) %}\\n\\n    {% set store_failures_as = config.get('store_failures_as') %}\\n    -- if `--store-failures` is invoked via command line and `store_failures_as` is not set,\\n    -- config.get('store_failures_as', 'table') returns None, not 'table'\\n    {% if store_failures_as == none %}{% set store_failures_as = 'table' %}{% endif %}\\n    {% if store_failures_as not in ['table', 'view'] %}\\n        {{ exceptions.raise_compiler_error(\\n            \\"'\\" ~ store_failures_as ~ \\"' is not a valid value for `store_failures_as`. \\"\\n            \\"Accepted values are: ['ephemeral', 'table', 'view']\\"\\n        ) }}\\n    {% endif %}\\n\\n    {% set target_relation = api.Relation.create(\\n        identifier=identifier, schema=schema, database=database, type=store_failures_as) -%} %}\\n\\n    {% if old_relation %}\\n        {% do adapter.drop_relation(old_relation) %}\\n    {% endif %}\\n\\n    {% call statement(auto_begin=True) %}\\n        {{ get_create_sql(target_relation, sql_with_limit) }}\\n    {% endcall %}\\n\\n    {% do relations.append(target_relation) %}\\n\\n    {# Since the test failures have already been saved to the database, reuse that result rather than querying again #}\\n    {% set main_sql %}\\n        select *\\n        from {{ target_relation }}\\n    {% endset %}\\n\\n    {{ adapter.commit() }}\\n\\n  {% else %}\\n\\n      {% set main_sql = sql_with_limit %}\\n\\n  {% endif %}\\n\\n  {% set fail_calc = config.get('fail_calc') %}\\n  {% set warn_if = config.get('warn_if') %}\\n  {% set error_if = config.get('error_if') %}\\n\\n  {% call statement('main', fetch_result=True) -%}\\n\\n    {# The limit has already been included above, and we do not want to duplicate it again. We also want to be safe for macro overrides treating `limit` as a required parameter. #}\\n    {{ get_test_sql(main_sql, fail_calc, warn_if, error_if, limit=none)}}\\n\\n  {%- endcall %}\\n\\n  {{ return({'relations': relations}) }}\\n\\n{%- endmaterialization -%}", "unique_id": "macro.dbt.materialization_test_default", "created_at": 1758839280.9523542, "depends_on": {"macros": ["macro.dbt.get_limit_subquery_sql", "macro.dbt.should_store_failures", "macro.dbt.statement", "macro.dbt.get_create_sql", "macro.dbt.get_test_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/tests/test.sql", "supported_languages": ["sql"]}, "macro.dbt.materialization_unit_default": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialization_unit_default", "path": "macros/materializations/tests/unit.sql", "arguments": [], "macro_sql": "{%- materialization unit, default -%}\\n\\n  {% set relations = [] %}\\n\\n  {% set expected_rows = config.get('expected_rows') %}\\n  {% set expected_sql = config.get('expected_sql') %}\\n  {% set tested_expected_column_names = expected_rows[0].keys() if (expected_rows | length ) > 0 else get_columns_in_query(sql) %}\\n\\n  {%- set target_relation = this.incorporate(type='table') -%}\\n  {%- set temp_relation = make_temp_relation(target_relation)-%}\\n  {% do run_query(get_create_table_as_sql(True, temp_relation, get_empty_subquery_sql(sql))) %}\\n  {%- set columns_in_relation = adapter.get_columns_in_relation(temp_relation) -%}\\n  {%- set column_name_to_data_types = {} -%}\\n  {%- set column_name_to_quoted = {} -%}\\n  {%- for column in columns_in_relation -%}\\n  {%-   do column_name_to_data_types.update({column.name|lower: column.data_type}) -%}\\n  {%-   do column_name_to_quoted.update({column.name|lower: column.quoted}) -%}\\n  {%- endfor -%}\\n\\n  {%- set expected_column_names_quoted = [] -%}\\n  {%- for column_name in tested_expected_column_names -%}\\n  {%-   do expected_column_names_quoted.append(column_name_to_quoted[column_name|lower]) -%}\\n  {%- endfor -%}\\n\\n  {% if not expected_sql %}\\n  {%   set expected_sql = get_expected_sql(expected_rows, column_name_to_data_types, column_name_to_quoted) %}\\n  {% endif %}\\n  {% set unit_test_sql = get_unit_test_sql(sql, expected_sql, expected_column_names_quoted) %}\\n\\n  {% call statement('main', fetch_result=True) -%}\\n\\n    {{ unit_test_sql }}\\n\\n  {%- endcall %}\\n\\n  {% do adapter.drop_relation(temp_relation) %}\\n\\n  {{ return({'relations': relations}) }}\\n\\n{%- endmaterialization -%}", "unique_id": "macro.dbt.materialization_unit_default", "created_at": 1758839280.955894, "depends_on": {"macros": ["macro.dbt.get_columns_in_query", "macro.dbt.make_temp_relation", "macro.dbt.run_query", "macro.dbt.get_create_table_as_sql", "macro.dbt.get_empty_subquery_sql", "macro.dbt.get_expected_sql", "macro.dbt.get_unit_test_sql", "macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/tests/unit.sql", "supported_languages": ["sql"]}, "macro.dbt.materialization_view_default": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialization_view_default", "path": "macros/materializations/models/view.sql", "arguments": [], "macro_sql": "{%- materialization view, default -%}\\n\\n  {%- set existing_relation = load_cached_relation(this) -%}\\n  {%- set target_relation = this.incorporate(type='view') -%}\\n  {%- set intermediate_relation =  make_intermediate_relation(target_relation) -%}\\n\\n  -- the intermediate_relation should not already exist in the database; get_relation\\n  -- will return None in that case. Otherwise, we get a relation that we can drop\\n  -- later, before we try to use this name for the current operation\\n  {%- set preexisting_intermediate_relation = load_cached_relation(intermediate_relation) -%}\\n  /*\\n     This relation (probably) doesn't exist yet. If it does exist, it's a leftover from\\n     a previous run, and we're going to try to drop it immediately. At the end of this\\n     materialization, we're going to rename the \\"existing_relation\\" to this identifier,\\n     and then we're going to drop it. In order to make sure we run the correct one of:\\n       - drop view ...\\n       - drop table ...\\n\\n     We need to set the type of this relation to be the type of the existing_relation, if it exists,\\n     or else \\"view\\" as a sane default if it does not. Note that if the existing_relation does not\\n     exist, then there is nothing to move out of the way and subsequentally drop. In that case,\\n     this relation will be effectively unused.\\n  */\\n  {%- set backup_relation_type = 'view' if existing_relation is none else existing_relation.type -%}\\n  {%- set backup_relation = make_backup_relation(target_relation, backup_relation_type) -%}\\n  -- as above, the backup_relation should not already exist\\n  {%- set preexisting_backup_relation = load_cached_relation(backup_relation) -%}\\n  -- grab current tables grants config for comparision later on\\n  {% set grant_config = config.get('grants') %}\\n\\n  {{ run_hooks(pre_hooks, inside_transaction=False) }}\\n\\n  -- drop the temp relations if they exist already in the database\\n  {{ drop_relation_if_exists(preexisting_intermediate_relation) }}\\n  {{ drop_relation_if_exists(preexisting_backup_relation) }}\\n\\n  -- `BEGIN` happens here:\\n  {{ run_hooks(pre_hooks, inside_transaction=True) }}\\n\\n  -- build model\\n  {% call statement('main') -%}\\n    {{ get_create_view_as_sql(intermediate_relation, sql) }}\\n  {%- endcall %}\\n\\n  -- cleanup\\n  -- move the existing view out of the way\\n  {% if existing_relation is not none %}\\n     /* Do the equivalent of rename_if_exists. 'existing_relation' could have been dropped\\n        since the variable was first set. */\\n    {% set existing_relation = load_cached_relation(existing_relation) %}\\n    {% if existing_relation is not none %}\\n        {{ adapter.rename_relation(existing_relation, backup_relation) }}\\n    {% endif %}\\n  {% endif %}\\n  {{ adapter.rename_relation(intermediate_relation, target_relation) }}\\n\\n  {% set should_revoke = should_revoke(existing_relation, full_refresh_mode=True) %}\\n  {% do apply_grants(target_relation, grant_config, should_revoke=should_revoke) %}\\n\\n  {% do persist_docs(target_relation, model) %}\\n\\n  {{ run_hooks(post_hooks, inside_transaction=True) }}\\n\\n  {{ adapter.commit() }}\\n\\n  {{ drop_relation_if_exists(backup_relation) }}\\n\\n  {{ run_hooks(post_hooks, inside_transaction=False) }}\\n\\n  {{ return({'relations': [target_relation]}) }}\\n\\n{%- endmaterialization -%}", "unique_id": "macro.dbt.materialization_view_default", "created_at": 1758839280.8898761, "depends_on": {"macros": ["macro.dbt.load_cached_relation", "macro.dbt.make_intermediate_relation", "macro.dbt.make_backup_relation", "macro.dbt.run_hooks", "macro.dbt.drop_relation_if_exists", "macro.dbt.statement", "macro.dbt.get_create_view_as_sql", "macro.dbt.should_revoke", "macro.dbt.apply_grants", "macro.dbt.persist_docs"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/view.sql", "supported_languages": ["sql"]}, "macro.dbt_date.default__get_base_dates": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_base_dates", "path": "macros/get_base_dates.sql", "arguments": [], "macro_sql": "{% macro default__get_base_dates(start_date, end_date, n_dateparts, datepart) %}\\n\\n{%- if start_date and end_date -%}\\n{%- set start_date=\\"cast('\\" ~ start_date ~ \\"' as \\" ~ dbt.type_timestamp() ~ \\")\\" -%}\\n{%- set end_date=\\"cast('\\" ~ end_date ~ \\"' as \\" ~ dbt.type_timestamp() ~ \\")\\"  -%}\\n\\n{%- elif n_dateparts and datepart -%}\\n\\n{%- set start_date = dbt.dateadd(datepart, -1 * n_dateparts, dbt_date.today()) -%}\\n{%- set end_date = dbt_date.tomorrow() -%}\\n{%- endif -%}\\n\\nwith date_spine as\\n(\\n\\n    {{ dbt_date.date_spine(\\n        datepart=datepart,\\n        start_date=start_date,\\n        end_date=end_date,\\n       )\\n    }}\\n\\n)\\nselect\\n    cast(d.date_{{ datepart }} as {{ dbt.type_timestamp() }}) as date_{{ datepart }}\\nfrom\\n    date_spine d\\n{% endmacro %}", "unique_id": "macro.dbt_date.default__get_base_dates", "created_at": 1758839281.1128166, "depends_on": {"macros": ["macro.dbt.type_timestamp", "macro.dbt.dateadd", "macro.dbt_date.today", "macro.dbt_date.tomorrow", "macro.dbt_date.date_spine"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/get_base_dates.sql", "supported_languages": null}, "macro.dbt_date.default__iso_week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__iso_week_start", "path": "macros/calendar_date/iso_week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__iso_week_start(date) -%}\\n{{ dbt_date._iso_week_start(date, 'isoweek') }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.default__iso_week_start", "created_at": 1758839281.1511638, "depends_on": {"macros": ["macro.dbt_date._iso_week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_start.sql", "supported_languages": null}, "macro.dbt_date.snowflake__iso_week_end": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snowflake__iso_week_end", "path": "macros/calendar_date/iso_week_end.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro snowflake__iso_week_end(date) -%}\\n{{ dbt_date._iso_week_end(date, 'weekiso') }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.snowflake__is