path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro lookup_max_value(max_values_list, lookup_value, lookup_key='type', return_key='max_val') %}\\n{#\\n    Use with the result of the max_existing_multirow macro.\\n    Does a lookup into that list of dicts for a given lookup_key.\\n\\n    Params:  max_values - the output of the max_existing_multirow macro, a list of dicts\\n      must have a 'type' and 'max_val' key\\n    Return: literal string of the max value if found or None\\n    None will print blank and probably cause an error in the SQL of your model.\\n#}\\n    {{ return (max_values_list | selectattr(lookup_key, 'eq', lookup_value) | map(attribute=return_key) | list | first) }}\\n{% endmacro %}", "unique_id": "macro.cht_pipeline_base.lookup_max_value", "created_at": 1758839281.3236918, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supported_languages": null}, "macro.dbt.default__get_catalog_relations": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_catalog_relations", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro default__get_catalog_relations(information_schema, relations) -%}\\n  {% set typename = adapter.type() %}\\n  {% set msg -%}\\n    get_catalog_relations not implemented for {{ typename }}\\n  {%- endset %}\\n\\n  {{ exceptions.raise_compiler_error(msg) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.default__get_catalog_relations", "created_at": 1758839281.0033758, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt.default__get_create_backup_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_create_backup_sql",