__to_unixtimestamp": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__to_unixtimestamp", "path": "macros/calendar_date/to_unixtimestamp.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__to_unixtimestamp(timestamp) -%}\\n    {{ dbt_date.date_part('epoch', timestamp) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.default__to_unixtimestamp", "created_at": 1758839281.1393917, "depends_on": {"macros": ["macro.dbt_date.date_part"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/to_unixtimestamp.sql", "supported_languages": null}, "macro.dbt_date.snowflake__iso_week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snowflake__iso_week_start", "path": "macros/calendar_date/iso_week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro snowflake__iso_week_start(date) -%}\\n{{ dbt_date._iso_week_start(date, 'week') }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.snowflake__iso_week_start", "created_at": 1758839281.151435, "depends_on": {"macros": ["macro.dbt_date._iso_week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_start.sql", "supported_languages": null}, "macro.dbt_date.trino__from_unixtimestamp": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "trino__from_unixtimestamp", "path": "macros/calendar_date/from_unixtimestamp.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro trino__from_unixtimestamp(epochs, format) -%}\\n    {%- if format == \\"seconds\\" -%}\\n        cast(from_unixtime({{ epochs }}) AT TIME ZONE 'UTC' as {{ dbt.type_timestamp() }})\\n    {%- elif format == \\"milliseconds\\" -%}\\n        cast(from_unixtime_nanos({{ epochs }} * pow(10, 6)) AT TIME ZONE 'UTC' as {{ dbt.type_timestamp() }})\\n    {%- elif format == \\"microseconds\\" -%}\\n        cast(from_unixtime_nanos({{ epochs }} * pow(10, 3)) AT TIME ZONE 'UTC' as {{ dbt.type_timestamp() }})\\n    {%- elif format == \\"nanoseconds\\" -%}\\n        cast(from_unixtime_nanos({{ epochs }}) AT TIME ZONE 'UTC' as {{ dbt.type_timestamp() }})\\n    {%- else -%}\\n    {{ exceptions.raise_compiler_error(\\n        \\"value \\" ~ format ~ \\" for `format` for from_unixtimestamp is not supported.\\"\\n        )\\n    }}\\n    {% endif -%}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.trino__from_unixtimestamp", "created_at": 1758839281.1705973, "depends_on": {"macros": ["macro.dbt.type_timestamp"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/from_unixtimestamp.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__copy_grants": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__copy_grants", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__copy_grants() %}\\n    {{ return(False) }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__copy_grants", "created_at": 1758839280.7454062, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__drop_schema": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__drop_schema", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__drop_schema(relation) -%}\\n  {% if relation.database -%}\\n    {{ adapter.verify_database(relation.database) }}\\n  {%- endif -%}\\n  {%- call statement('drop_schema') -%}\\n    drop schema if exists {{ relation.without_identifier().include(database=False) }} cascade\\n  {%- endcall -%}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__drop_schema", "created_at": 1758839280.735137, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_catalog": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_catalog", "path": "macros/catalog.sql", "arguments": [], "macro_sql": "{% macro postgres__get_catalog(information_schema, schemas) -%}\\n  {%- set relations = [] -%}\\n  {%- for schema in schemas -%}\\n    {%- set dummy = relations.append({'schema': schema}) -%}\\n  {%- endfor -%}\\n  {{ return(postgres__get_catalog_relations(information_schema, relations)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_catalog", "created_at": 1758839280.7486846, "depends_on": {"macros": ["macro.dbt_postgres.postgres__get_catalog_relations"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/catalog.sql", "supported_languages": null}, "macro.dbt_utils.default__generate_series": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__generate_series", "path": "macros/sql/generate_series.sql", "arguments": [], "macro_sql": "{% macro default__generate_series(upper_bound) %}\\n\\n    {% set n = dbt_utils.get_powers_of_two(upper_bound) %}\\n\\n    with p as (\\n        select 0 as generated_number union all select 1\\n    ), unioned as (\\n\\n    select\\n\\n    {% for i in range(n) %}\\n    p{{i}}.generated_number * power(2, {{i}})\\n    {% if not loop.last %} + {% endif %}\\n    {% endfor %}\\n    + 1\\n    as generated_number\\n\\n    from\\n\\n    {% for i in range(n) %}\\n    p as p{{i}}\\n    {% if not loop.last %} cross join {% endif %}\\n    {% endfor %}\\n\\n    )\\n\\n    select *\\n    from unioned\\n    where generated_number <= {{upper_bound}}\\n    order by generated_number\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__generate_series", "created_at": 1758839281.1977627, "depends_on": {"macros": ["macro.dbt_utils.get_powers_of_two"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/generate_series.sql", "supported_languages": null}, "macro.dbt_utils.default__nullcheck_table": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__nullcheck_table", "path": "macros/sql/nullcheck_table.sql", "arguments": [], "macro_sql": "{% macro default__nullcheck_table(relation) %}\\n\\n  {%- do dbt_utils._is_relation(relation, 'nullcheck_table') -%}\\n  {%- do dbt_utils._is_ephemeral(relation, 'nullcheck_table') -%}\\n  {% set cols = adapter.get_columns_in_relation(relation) %}\\n\\n  select {{ dbt_utils.nullcheck(cols) }}\\n  from {{relation}}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__nullcheck_table", "created_at": 1758839281.2127619, "depends_on": {"macros": ["macro.dbt_utils._is_relation", "macro.dbt_utils._is_ephemeral", "macro.dbt_utils.nullcheck"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/nullcheck_table.sql", "supported_languages": null}, "macro.dbt_utils.default__union_relations": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__union_relations", "path": "macros/sql/union.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__union_relations(relations, column_override=none, include=[], exclude=[], source_column_name='_dbt_source_relation', where=none) -%}\\n\\n    {%- if exclude and include -%}\\n        {{ exceptions.raise_compiler_error(\\"Both an exclude and include list were provided to the `union` macro. Only one is allowed\\") }}\\n    {%- endif -%}\\n\\n    {#-- Prevent querying of db in parsing mode. This works because this macro does not create any new refs. -#}\\n    {%- if not execute %}\\n        {{ return('') }}\\n    {% endif -%}\\n\\n    {%- set column_override = column_override if column_override is not none else {} -%}\\n\\n    {%- set relation_columns = {} -%}\\n    {%- set column_superset = {} -%}\\n    {%- set all_excludes = [] -%}\\n    {%- set all_includes = [] -%}\\n\\n    {%- if exclude -%}\\n        {%- for exc in exclude -%}\\n            {%- do all_excludes.append(exc | lower) -%}\\n        {%- endfor -%}\\n    {%- endif -%}\\n\\n    {%- if include -%}\\n        {%- for inc in include -%}\\n            {%- do all_includes.append(inc | lower) -%}\\n        {%- endfor -%}\\n    {%- endif -%}\\n\\n    {%- for relation in relations -%}\\n\\n        {%- do relation_columns.update({relation: []}) -%}\\n\\n        {%- do dbt_utils._is_relation(relation, 'union_relations') -%}\\n        {%- do dbt_utils._is_ephemeral(relation, 'union_relations') -%}\\n        {%- set cols = adapter.get_columns_in_relation(relation) -%}\\n        {%- for col in cols -%}\\n\\n        {#- If an exclude list was provided and the column is in the list, do nothing -#}\\n        {%- if exclude and col.column | lower in all_excludes -%}\\n\\n        {#- If an include list was provided and the column is not in the list, do nothing -#}\\n        {%- elif include and col.column | lower not in all_includes -%}\\n\\n        {#- Otherwise add the column to the column superset -#}\\n        {%- else -%}\\n\\n            {#- update the list of columns in this relation -#}\\n            {%- do relation_columns[relation].append(col.column) -%}\\n\\n            {%- if col.column in column_superset -%}\\n\\n                {%- set stored = column_superset[col.column] -%}\\n                {%- if col.is_string() and stored.is_string() and col.string_size() > stored.string_size() -%}\\n\\n                    {%- do column_superset.update({col.column: col}) -%}\\n\\n                {%- endif %}\\n\\n            {%- else -%}\\n\\n                {%- do column_superset.update({col.column: col}) -%}\\n\\n            {%- endif -%}\\n\\n        {%- endif -%}\\n\\n        {%- endfor -%}\\n    {%- endfor -%}\\n\\n    {%- set ordered_column_names = column_superset.keys() -%}\\n    {%- set dbt_command = flags.WHICH -%}\\n\\n\\n    {% if dbt_command in ['run', 'build'] %}\\n    {% if (include | length > 0 or exclude | length > 0) and not column_superset.keys() %}\\n        {%- set relations_string -%}\\n            {%- for relation in relations -%}\\n                {{ relation.name }}\\n            {%- if not loop.last %}, {% endif -%}\\n            {%- endfor -%}\\n        {%- endset -%}\\n\\n        {%- set error_message -%}\\n            There were no columns found to union for relations {{ relations_string }}\\n        {%- endset -%}\\n\\n        {{ exceptions.raise_compiler_error(error_message) }}\\n    {%- endif -%}\\n    {%- endif -%}\\n\\n    {%- for relation in relations %}\\n\\n        (\\n            select\\n\\n                {%- if source_column_name is not none %}\\n                cast({{ dbt.string_literal(relation) }} as {{ dbt.type_string() }}) as {{ source_column_name }},\\n                {%- endif %}\\n\\n                {% for col_name in ordered_column_names -%}\\n\\n                    {%- set col = column_superset[col_name] %}\\n                    {%- set col_type = column_override.get(col.column, col.data_type) %}\\n                    {%- set col_name = adapter.quote(col_name) if col_name in relation_columns[relation] else 'null' %}\\n                    cast({{ col_name }} as {{ col_type }}) as {{ col.quoted }} {% if not loop.last %},{% endif -%}\\n\\n                {%- endfor %}\\n\\n            from {{ relation }}\\n\\n            {% if where -%}\\n            where {{ where }}\\n            {%- endif %}\\n        )\\n\\n        {% if not loop.last -%}\\n            union all\\n        {% endif -%}\\n\\n    {%- endfor -%}\\n\\n{%- endmacro -%}", "unique_id": "macro.dbt_utils.default__union_relations", "created_at": 1758839281.2271688, "depends_on": {"macros": ["macro.dbt_utils._is_relation", "macro.dbt_utils._is_ephemeral", "macro.dbt.string_literal", "macro.dbt.type_string"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/union.sql", "supported_languages": null}, "macro.dbt_utils.get_relations_by_pattern": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_relations_by_pattern", "path": "macros/sql/get_relations_by_pattern.sql", "arguments": [], "macro_sql": "{% macro get_relations_by_pattern(schema_pattern, table_pattern, exclude='', database=target.database) %}\\n    {{ return(adapter.dispatch('get_relations_by_pattern', 'dbt_utils')(schema_pattern, table_pattern, exclude, database)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.get_relations_by_pattern", "created_at": 1758839281.205574, "depends_on": {"macros": ["macro.dbt_utils.default__get_relations_by_pattern"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_relations_by_pattern.sql", "supported_languages": null}, "macro.dbt_utils.get_tables_by_prefix_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_tables_by_prefix_sql", "path": "macros/sql/get_tables_by_prefix_sql.sql", "arguments": [], "macro_sql": "{% macro get_tables_by_prefix_sql(schema, prefix, exclude='', database=target.database) %}\\n    {{ return(adapter.dispatch('get_tables_by_prefix_sql', 'dbt_utils')(schema, prefix, exclude, database)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.get_tables_by_prefix_sql", "created_at": 1758839281.2176123, "depends_on": {"macros": ["macro.dbt_utils.default__get_tables_by_prefix_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_tables_by_prefix_sql.sql", "supported_languages": null}, "macro.dbt_utils.test_not_accepted_values": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_not_accepted_values", "path": "macros/generic_tests/not_accepted_values.sql", "arguments": [], "macro_sql": "{% test not_accepted_values(model, column_name, values, quote=True) %}\\n  {{ return(adapter.dispatch('test_not_accepted_values', 'dbt_utils')(model, column_name, values, quote)) }}\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_not_accepted_values", "created_at": 1758839281.2768464, "depends_on": {"macros": ["macro.dbt_utils.default__test_not_accepted_values"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/not_accepted_values.sql", "supported_languages": null}, "macro.dbt_utils.test_not_null_proportion": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_not_null_proportion", "path": "macros/generic_tests/not_null_proportion.sql", "arguments": [], "macro_sql": "{% macro test_not_null_proportion(model, group_by_columns = []) %}\\n  {{ return(adapter.dispatch('test_not_null_proportion', 'dbt_utils')(model, group_by_columns, **kwargs)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.test_not_null_proportion", "created_at": 1758839281.266748, "depends_on": {"macros": ["macro.dbt_utils.default__test_not_null_proportion"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/not_null_proportion.sql", "supported_languages": null}, "macro.dbt_utils.test_relationships_where": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_relationships_where", "path": "macros/generic_tests/relationships_where.sql", "arguments": [], "macro_sql": "{% test relationships_where(model, column_name, to, field, from_condition=\\"1=1\\", to_condition=\\"1=1\\") %}\\n  {{ return(adapter.dispatch('test_relationships_where', 'dbt_utils')(model, column_name, to, field, from_condition, to_condition)) }}\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_relationships_where", "created_at": 1758839281.3021662, "depends_on": {"macros": ["macro.dbt_utils.default__test_relationships_where"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/relationships_where.sql", "supported_languages": null}, "macro.cht_pipeline_base.max_existing_date": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "max_existing_date", "path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro max_existing_date(timestampfield, target_ref=this) -%}\\n{#\\n    Params:\\n        timestampfield: date or timestamp\\n        target_ref: string, optional, defaults to the current context model\\n                    pass in a call to ref or source to target a different model\\n    Returns a SQL expression casting the max value string to a timestamp.\\n        e.g. \\"CAST('2019-01-01' AS DATE)\\"\\n    Usage:\\n        current model - latest value of a field called \\"updated_at\\":\\n            {{ max_existing_date('updated_at') }}\\n\\n        some other model ref - latest value of a field called \\"deactivated_at\\":\\n            {{ max_existing_date('deactivated_at', ref('other_model')) }}\\n\\n        some other model source - latest value of a field called \\"deactivated_at\\":\\n            {{ max_existing_date('deactivated_at', source('source_name', 'table_or_view_name')) }}\\n\\n#}\\n    {{ return(_cast_as_type(max_existing(timestampfield, target_ref), 'DATE')) }}\\n{%- endmacro %}", "unique_id": "macro.cht_pipeline_base.max_existing_date", "created_at": 1758839281.3248918, "depends_on": {"macros": ["macro.cht_pipeline_base._cast_as_type", "macro.cht_pipeline_base.max_existing"]}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supported_languages": null}, "macro.cht_pipeline_base.parse_dbt_results": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "parse_dbt_results", "path": "macros/parse_dbt_results.sql", "arguments": [], "macro_sql": "{% macro parse_dbt_results(results) %}\\n  -- Create a list of parsed results\\n  {%- set parsed_results = [] %}\\n  -- Flatten results and add to list\\n  {% for run_result in results %}\\n    -- Convert the run result object to a simple dictionary\\n    {% set run_result_dict = run_result.to_dict() %}\\n    -- Get the underlying dbt graph node that was executed\\n    {% set node = run_result_dict.get('node') %}\\n    {% set rows_affected = run_result_dict.get('adapter_response', {}).get('rows_affected', 0) %}\\n    {%- if not rows_affected -%}\\n      {% set rows_affected = 0 %}\\n    {%- endif -%}\\n    {% set parsed_result_dict = {\\n        'result_id': invocation_id ~ '.' ~ node.get('unique_id'),\\n        'invocation_id': invocation_id,\\n        'unique_id': node.get('unique_id'),\\n        'database_name': node.get('database'),\\n        'schema_name': node.get('schema'),\\n        'name': node.get('name'),\\n        'resource_type': node.get('resource_type'),\\n        'status': run_result_dict.get('status'),\\n        'execution_time': run_result_dict.get('execution_time'),\\n        'rows_affected': rows_affected\\n        }%}\\n    {% do parsed_results.append(parsed_result_dict) %}\\n  {% endfor %}\\n  {{ return(parsed_results) }}\\n{% endmacro %}", "unique_id": "macro.cht_pipeline_base.parse_dbt_results", "created_at": 1758839281.3375986, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/parse_dbt_results.sql", "supported_languages": null}, "macro.dbt.default__alter_relation_comment": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__alter_relation_comment", "path": "macros/adapters/persist_docs.sql", "arguments": [], "macro_sql": "{% macro default__alter_relation_comment(relation, relation_comment) -%}\\n  {{ exceptions.raise_not_implemented(\\n    'alter_relation_comment macro not implemented for adapter '+adapter.type()) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__alter_relation_comment", "created_at": 1758839280.994072, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/persist_docs.sql", "supported_languages": null}, "macro.dbt.default__drop_materialized_view": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__drop_materialized_view", "path": "macros/relations/materialized_view/drop.sql", "arguments": [], "macro_sql": "{% macro default__drop_materialized_view(relation) -%}\\n    drop materialized view if exists {{ relation.render() }} cascade\\n{%- endmacro %}", "unique_id": "macro.dbt.default__drop_materialized_view", "created_at": 1758839280.82004, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/materialized_view/drop.sql", "supported_languages": null}, "macro.dbt.default__generate_database_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__generate_database_name", "path": "macros/get_custom_name/get_custom_database.sql", "arguments": [], "macro_sql": "{% macro default__generate_database_name(custom_database_name=none, node=none) -%}\\n    {%- set default_database = target.database -%}\\n    {%- if custom_database_name is none -%}\\n\\n        {{ default_database }}\\n\\n    {%- else -%}\\n\\n        {{ custom_database_name }}\\n\\n    {%- endif -%}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt.default__generate_database_name", "created_at": 1758839280.774715, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/get_custom_name/get_custom_database.sql", "supported_languages": null}, "macro.dbt.default__get_create_view_as_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_create_view_as_sql", "path": "macros/relations/view/create.sql", "arguments": [], "macro_sql": "{% macro default__get_create_view_as_sql(relation, sql) -%}\\n  {{ return(create_view_as(relation, sql)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_create_view_as_sql", "created_at": 1758839280.7964108, "depends_on": {"macros": ["macro.dbt.create_view_as"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/view/create.sql", "supported_languages": null}, "macro.dbt.default__get_dcl_statement_list": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_dcl_statement_list", "path": "macros/adapters/apply_grants.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__get_dcl_statement_list(relation, grant_config, get_dcl_macro) -%}\\n    {#\\n      -- Unpack grant_config into specific privileges and the set of users who need them granted/revoked.\\n      -- Depending on whether this database supports multiple grantees per statement, pass in the list of\\n      -- all grantees per privilege, or (if not) template one statement per privilege-grantee pair.\\n      -- `get_dcl_macro` will be either `get_grant_sql` or `get_revoke_sql`\\n    #}\\n    {%- set dcl_statements = [] -%}\\n    {%- for privilege, grantees in grant_config.items() %}\\n        {%- if support_multiple_grantees_per_dcl_statement() and grantees -%}\\n          {%- set dcl = get_dcl_macro(relation, privilege, grantees) -%}\\n          {%- do dcl_statements.append(dcl) -%}\\n        {%- else -%}\\n          {%- for grantee in grantees -%}\\n              {% set dcl = get_dcl_macro(relation, privilege, [grantee]) %}\\n              {%- do dcl_statements.append(dcl) -%}\\n          {% endfor -%}\\n        {%- endif -%}\\n    {%- endfor -%}\\n    {{ return(dcl_statements) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.default__get_dcl_statement_list", "created_at": 1758839281.0307753, "depends_on": {"macros": ["macro.dbt.support_multiple_grantees_per_dcl_statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/apply_grants.sql", "supported_languages": null}, "macro.dbt.default__get_empty_subquery_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_empty_subquery_sql", "path": "macros/adapters/columns.sql", "arguments": [], "macro_sql": "{% macro default__get_empty_subquery_sql(select_sql, select_sql_header=none) %}\\n    {%- if select_sql_header is not none -%}\\n    {{ select_sql_header }}\\n    {%- endif -%}\\n    select * from (\\n        {{ select_sql }}\\n    ) as __dbt_sbq\\n    where false\\n    limit 0\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_empty_subquery_sql", "created_at": 1758839281.0388525, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/columns.sql", "supported_languages": null}, "macro.dbt.default__get_or_create_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_or_create_relation", "path": "macros/adapters/relation.sql", "arguments": [], "macro_sql": "{% macro default__get_or_create_relation(database, schema, identifier, type) %}\\n  {%- set target_relation = adapter.get_relation(database=database, schema=schema, identifier=identifier) %}\\n\\n  {% if target_relation %}\\n    {% do return([true, target_relation]) %}\\n  {% endif %}\\n\\n  {%- set new_relation = api.Relation.create(\\n      database=database,\\n      schema=schema,\\n      identifier=identifier,\\n      type=type\\n  ) -%}\\n  {% do return([false, new_relation]) %}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_or_create_relation", "created_at": 1758839281.0220513, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/relation.sql", "supported_languages": null}, "macro.dbt.default__snapshot_staging_table": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__snapshot_staging_table", "path": "macros/materializations/snapshots/helpers.sql", "arguments": [], "macro_sql": "{% macro default__snapshot_staging_table(strategy, source_sql, target_relation) -%}\\n    {% set columns = config.get('snapshot_table_column_names') or get_snapshot_table_column_names() %}\\n    {% if strategy.hard_deletes == 'new_record' %}\\n        {% set new_scd_id = snapshot_hash_arguments([columns.dbt_scd_id, snapshot_get_time()]) %}\\n    {% endif %}\\n    with snapshot_query as (\\n\\n        {{ source_sql }}\\n\\n    ),\\n\\n    snapshotted_data as (\\n\\n        select *, {{ unique_key_fields(strategy.unique_key) }}\\n        from {{ target_relation }}\\n        where\\n            {% if config.get('dbt_valid_to_current') %}\\n\\t\\t{% set source_unique_key = columns.dbt_valid_to | trim %}\\n\\t\\t{% set target_unique_key = config.get('dbt_valid_to_current') | trim %}\\n\\n\\t\\t{# The exact equals semantics between NULL values depends on the current behavior flag set. Also, update records if the source field is null #}\\n                ( {{ equals(source_unique_key, target_unique_key) }} or {{ source_unique_key }} is null )\\n            {% else %}\\n                {{ columns.dbt_valid_to }} is null\\n            {% endif %}\\n\\n    ),\\n\\n    insertions_source_data as (\\n\\n        select *, {{ unique_key_fields(strategy.unique_key) }},\\n            {{ strategy.updated_at }} as {{ columns.dbt_updated_at }},\\n            {{ strategy.updated_at }} as {{ columns.dbt_valid_from }},\\n            {{ get_dbt_valid_to_current(strategy, columns) }},\\n            {{ strategy.scd_id }} as {{ columns.dbt_scd_id }}\\n\\n        from snapshot_query\\n    ),\\n\\n    updates_source_data as (\\n\\n        select *, {{ unique_key_fields(strategy.unique_key) }},\\n            {{ strategy.updated_at }} as {{ columns.dbt_updated_at }},\\n            {{ strategy.updated_at }} as {{ columns.dbt_valid_from }},\\n            {{ strategy.updated_at }} as {{ columns.dbt_valid_to }}\\n\\n        from snapshot_query\\n    ),\\n\\n    {%- if strategy.hard_deletes == 'invalidate' or strategy.hard_deletes == 'new_record' %}\\n\\n    deletes_source_data as (\\n\\n        select *, {{ unique_key_fields(strategy.unique_key) }}\\n        from snapshot_query\\n    ),\\n    {% endif %}\\n\\n    insertions as (\\n\\n        select\\n            'insert' as dbt_change_type,\\n            source_data.*\\n          {%- if strategy.hard_deletes == 'new_record' -%}\\n            ,'False' as {{ columns.dbt_is_deleted }}\\n          {%- endif %}\\n\\n        from insertions_source_data as source_data\\n        left outer join snapshotted_data\\n            on {{ unique_key_join_on(strategy.unique_key, \\"snapshotted_data\\", \\"source_data\\") }}\\n            where {{ unique_key_is_null(strategy.unique_key, \\"snapshotted_data\\") }}\\n            or ({{ unique_key_is_not_null(strategy.unique_key, \\"snapshotted_data\\") }} and (\\n               {{ strategy.row_changed }} {%- if strategy.hard_deletes == 'new_record' -%} or snapshotted_data.{{ columns.dbt_is_deleted }} = 'True' {% endif %}\\n            )\\n\\n        )\\n\\n    ),\\n\\n    updates as (\\n\\n        select\\n            'update' as dbt_change_type,\\n            source_data.*,\\n            snapshotted_data.{{ columns.dbt_scd_id }}\\n          {%- if strategy.hard_deletes == 'new_record' -%}\\n            , snapshotted_data.{{ columns.dbt_is_deleted }}\\n          {%- endif %}\\n\\n        from updates_source_data as source_data\\n        join snapshotted_data\\n            on {{ unique_key_join_on(strategy.unique_key, \\"snapshotted_data\\", \\"source_data\\") }}\\n        where (\\n            {{ strategy.row_changed }}  {%- if strategy.hard_deletes == 'new_record' -%} or snapshotted_data.{{ columns.dbt_is_deleted }} = 'True' {% endif %}\\n        )\\n    )\\n\\n    {%- if strategy.hard_deletes == 'invalidate' or strategy.hard_deletes == 'new_record' %}\\n    ,\\n    deletes as (\\n\\n        select\\n            'delete' as dbt_change_type,\\n            source_data.*,\\n            {{ snapshot_get_time() }} as {{ columns.dbt_valid_from }},\\n            {{ snapshot_get_time() }} as {{ columns.dbt_updated_at }},\\n            {{ snapshot_get_time() }} as {{ columns.dbt_valid_to }},\\n            snapshotted_data.{{ columns.dbt_scd_id }}\\n          {%- if strategy.hard_deletes == 'new_record' -%}\\n            , snapshotted_data.{{ columns.dbt_is_deleted }}\\n          {%- endif %}\\n        from snapshotted_data\\n        left join deletes_source_data as source_data\\n            on {{ unique_key_join_on(strategy.unique_key, \\"snapshotted_data\\", \\"source_data\\") }}\\n            where {{ unique_key_is_null(strategy.unique_key, \\"source_data\\") }}\\n\\n            {%- if strategy.hard_deletes == 'new_record' %}\\n            and not (\\n                --avoid updating the record's valid_to if the latest entry is marked as deleted\\n                snapshotted_data.{{ columns.dbt_is_deleted }} = 'True'\\n                and snapshotted_data.{{ columns.dbt_valid_to }} is null\\n            )\\n            {%- endif %}\\n    )\\n    {%- endif %}\\n\\n    {%- if strategy.hard_deletes == 'new_record' %}\\n        {% set snapshotted_cols = get_list_of_column_names(get_columns_in_relation(target_relation)) %}\\n        {% set source_sql_cols = get_column_schema_from_query(source_sql) %}\\n    ,\\n    deletion_records as (\\n\\n        select\\n            'insert' as dbt_change_type,\\n            {#\\n                If a column has been added to the source it won't yet exist in the\\n                snapshotted table so we insert a null value as a placeholder for the column.\\n             #}\\n            {%- for col in source_sql_cols -%}\\n            {%- if col.name in snapshotted_cols -%}\\n            snapshotted_data.{{ adapter.quote(col.column) }},\\n            {%- else -%}\\n            NULL as {{ adapter.quote(col.column) }},\\n            {%- endif -%}\\n            {% endfor -%}\\n            {%- if strategy.unique_key | is_list -%}\\n                {%- for key in strategy.unique_key -%}\\n            snapshotted_data.{{ key }} as dbt_unique_key_{{ loop.index }},\\n                {% endfor -%}\\n            {%- else -%}\\n            snapshotted_data.dbt_unique_key as dbt_unique_key,\\n            {% endif -%}\\n            {{ snapshot_get_time() }} as {{ columns.dbt_valid_from }},\\n            {{ snapshot_get_time() }} as {{ columns.dbt_updated_at }},\\n            snapshotted_data.{{ columns.dbt_valid_to }} as {{ columns.dbt_valid_to }},\\n            {{ new_scd_id }} as {{ columns.dbt_scd_id }},\\n            'True' as {{ columns.dbt_is_deleted }}\\n        from snapshotted_data\\n        left join deletes_source_data as source_data\\n            on {{ unique_key_join_on(strategy.unique_key, \\"snapshotted_data\\", \\"source_data\\") }}\\n        where {{ unique_key_is_null(strategy.unique_key, \\"source_data\\") }}\\n        and not (\\n            --avoid inserting a new record if the latest one is marked as deleted\\n            snapshotted_data.{{ columns.dbt_is_deleted }} = 'True'\\n            and snapshotted_data.{{ columns.dbt_valid_to }} is null\\n            )\\n\\n    )\\n    {%- endif %}\\n\\n    select * from insertions\\n    union all\\n    select * from updates\\n    {%- if strategy.hard_deletes == 'invalidate' or strategy.hard_deletes == 'new_record' %}\\n    union all\\n    select * from deletes\\n    {%- endif %}\\n    {%- if strategy.hard_deletes == 'new_record' %}\\n    union all\\n    select * from deletion_records\\n    {%- endif %}\\n\\n\\n{%- endmacro %}", "unique_id": "macro.dbt.default__snapshot_staging_table", "created_at": 1758839280.8510027, "depends_on": {"macros": ["macro.dbt.get_snapshot_table_column_names", "macro.dbt.snapshot_hash_arguments", "macro.dbt.snapshot_get_time", "macro.dbt.unique_key_fields", "macro.dbt.equals", "macro.dbt.get_dbt_valid_to_current", "macro.dbt.unique_key_join_on", "macro.dbt.unique_key_is_null", "macro.dbt.unique_key_is_not_null", "macro.dbt.get_list_of_column_names", "macro.dbt.get_columns_in_relation", "macro.dbt.get_column_schema_from_query"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/helpers.sql", "supported_languages": null}, "macro.dbt.get_catalog_for_single_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_catalog_for_single_relation", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro get_catalog_for_single_relation(relation) %}\\n  {{ return(adapter.dispatch('get_catalog_for_single_relation', 'dbt')(relation)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.get_catalog_for_single_relation", "created_at": 1758839281.0079024, "depends_on": {"macros": ["macro.dbt.default__get_catalog_for_single_relation"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt.get_snapshot_get_time_data_type": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_snapshot_get_time_data_type", "path": "macros/adapters/timestamps.sql", "arguments": [], "macro_sql": "{% macro get_snapshot_get_time_data_type() %}\\n    {% set snapshot_time = adapter.dispatch('snapshot_get_time', 'dbt')() %}\\n    {% set time_data_type_sql = 'select ' ~ snapshot_time ~ ' as dbt_snapshot_time' %}\\n    {% set snapshot_time_column_schema = get_column_schema_from_query(time_data_type_sql) %}\\n    {% set time_data_type = snapshot_time_column_schema[0].dtype %}\\n    {{ return(time_data_type or none) }}\\n{% endmacro %}", "unique_id": "macro.dbt.get_snapshot_get_time_data_type", "created_at": 1758839281.049316, "depends_on": {"macros": ["macro.dbt.snapshot_get_time", "macro.dbt_postgres.postgres__snapshot_get_time", "macro.dbt.get_column_schema_from_query"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/timestamps.sql", "supported_languages": null}, "macro.dbt.get_snapshot_table_column_names": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_snapshot_table_column_names", "path": "macros/materializations/snapshots/helpers.sql", "arguments": [], "macro_sql": "{% macro get_snapshot_table_column_names() %}\\n    {{ return({'dbt_valid_to': 'dbt_valid_to', 'dbt_valid_from': 'dbt_valid_from', 'dbt_scd_id': 'dbt_scd_id', 'dbt_updated_at': 'dbt_updated_at', 'dbt_is_deleted': 'dbt_is_deleted'}) }}\\n{% endmacro %}", "unique_id": "macro.dbt.get_snapshot_table_column_names", "created_at": 1758839280.8432841, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/helpers.sql", "supported_languages": null}, "macro.dbt.get_updated_at_column_data_type": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_updated_at_column_data_type", "path": "macros/materializations/snapshots/helpers.sql", "arguments": [], "macro_sql": "{% macro get_updated_at_column_data_type(snapshot_sql) %}\\n    {% set snapshot_sql_column_schema = get_column_schema_from_query(snapshot_sql) %}\\n    {% set dbt_updated_at_data_type = null %}\\n    {% set ns = namespace() -%} {#-- handle for-loop scoping with a namespace --#}\\n    {% set ns.dbt_updated_at_data_type = null -%}\\n    {% for column in snapshot_sql_column_schema %}\\n    {%   if ((column.column == 'dbt_updated_at') or (column.column == 'DBT_UPDATED_AT')) %}\\n    {%     set ns.dbt_updated_at_data_type = column.dtype %}\\n    {%   endif %}\\n    {% endfor %}\\n    {{ return(ns.dbt_updated_at_data_type or none)  }}\\n{% endmacro %}", "unique_id": "macro.dbt.get_updated_at_column_data_type", "created_at": 1758839280.8547125, "depends_on": {"macros": ["macro.dbt.get_column_schema_from_query"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/helpers.sql", "supported_languages": null}, "macro.dbt.materialized_view_execute_no_op": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialized_view_execute_no_op", "path": "macros/materializations/models/materialized_view.sql", "arguments": [], "macro_sql": "{% macro materialized_view_execute_no_op(target_relation) %}\\n    {% do store_raw_result(\\n        name=\\"main\\",\\n        message=\\"skip \\" ~ target_relation,\\n        code=\\"skip\\",\\n        rows_affected=\\"-1\\"\\n    ) %}\\n{% endmacro %}", "unique_id": "macro.dbt.materialized_view_execute_no_op", "created_at": 1758839280.8971531, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/materialized_view.sql", "supported_languages": null}, "macro.dbt.materialized_view_get_build_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialized_view_get_build_sql", "path": "macros/materializations/models/materialized_view.sql", "arguments": [], "macro_sql": "{% macro materialized_view_get_build_sql(existing_relation, target_relation, backup_relation, intermediate_relation) %}\\n\\n    {% set full_refresh_mode = should_full_refresh() %}\\n\\n    -- determine the scenario we're in: create, full_refresh, alter, refresh data\\n    {% if existing_relation is none %}\\n        {% set build_sql = get_create_materialized_view_as_sql(target_relation, sql) %}\\n    {% elif full_refresh_mode or not existing_relation.is_materialized_view %}\\n        {% set build_sql = get_replace_sql(existing_relation, target_relation, sql) %}\\n    {% else %}\\n\\n        -- get config options\\n        {% set on_configuration_change = config.get('on_configuration_change') %}\\n        {% set configuration_changes = get_materialized_view_configuration_changes(existing_relation, config) %}\\n\\n        {% if configuration_changes is none %}\\n            {% set build_sql = refresh_materialized_view(target_relation) %}\\n\\n        {% elif on_configuration_change == 'apply' %}\\n            {% set build_sql = get_alter_materialized_view_as_sql(target_relation, configuration_changes, sql, existing_relation, backup_relation, intermediate_relation) %}\\n        {% elif on_configuration_change == 'continue' %}\\n            {% set build_sql = '' %}\\n            {{ exceptions.warn(\\"Configuration changes were identified and `on_configuration_change` was set to `continue` for `\\" ~ target_relation.render() ~ \\"`\\") }}\\n        {% elif on_configuration_change == 'fail' %}\\n            {{ exceptions.raise_fail_fast_error(\\"Configuration changes were identified and `on_configuration_change` was set to `fail` for `\\" ~ target_relation.render() ~ \\"`\\") }}\\n\\n        {% else %}\\n            -- this only happens if the user provides a value other than `apply`, 'skip', 'fail'\\n            {{ exceptions.raise_compiler_error(\\"Unexpected configuration scenario\\") }}\\n\\n        {% endif %}\\n\\n    {% endif %}\\n\\n    {% do return(build_sql) %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.materialized_view_get_build_sql", "created_at": 1758839280.8966901, "depends_on": {"macros": ["macro.dbt.should_full_refresh", "macro.dbt.get_create_materialized_view_as_sql", "macro.dbt.get_replace_sql", "macro.dbt.get_materialized_view_configuration_changes", "macro.dbt.refresh_materialized_view", "macro.dbt.get_alter_materialized_view_as_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/materialized_view.sql", "supported_languages": null}, "macro.dbt.sql_convert_columns_in_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "sql_convert_columns_in_relation", "path": "macros/adapters/columns.sql", "arguments": [], "macro_sql": "{% macro sql_convert_columns_in_relation(table) -%}\\n  {% set columns = [] %}\\n  {% for row in table %}\\n    {% do columns.append(api.Column(*row)) %}\\n  {% endfor %}\\n  {{ return(columns) }}\\n{% endmacro %}", "unique_id": "macro.dbt.sql_convert_columns_in_relation", "created_at": 1758839281.0374122, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/columns.sql", "supported_languages": null}, "macro.dbt_date.bigquery__convert_timezone": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "bigquery__convert_timezone", "path": "macros/calendar_date/convert_timezone.sql", "arguments": [], "macro_sql": "{%- macro bigquery__convert_timezone(column, target_tz, source_tz=None) -%}\\ntimestamp(datetime({{ column }}, '{{ target_tz}}'))\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_date.bigquery__convert_timezone", "created_at": 1758839281.1544654, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/convert_timezone.sql", "supported_languages": null}, "macro.dbt_date.bigquery__to_unixtimestamp": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "bigquery__to_unixtimestamp", "path": "macros/calendar_date/to_unixtimestamp.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro bigquery__to_unixtimestamp(timestamp) -%}\\n    unix_seco