bt.datediff"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/date_spine.sql", "supported_languages": null}, "macro.dbt_utils.default__test_not_empty_string": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_not_empty_string", "path": "macros/generic_tests/not_empty_string.sql", "arguments": [], "macro_sql": "{% macro default__test_not_empty_string(model, column_name, trim_whitespace=true) %}\\n\\n    with\\n    \\n    all_values as (\\n\\n        select \\n\\n\\n            {% if trim_whitespace == true -%}\\n\\n                trim({{ column_name }}) as {{ column_name }}\\n\\n            {%- else -%}\\n\\n                {{ column_name }}\\n\\n            {%- endif %}\\n            \\n        from {{ model }}\\n\\n    ),\\n\\n    errors as (\\n\\n        select * from all_values\\n        where {{ column_name }} = ''\\n\\n    )\\n\\n    select * from errors\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_not_empty_string", "created_at": 1758839281.2760978, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/not_empty_string.sql", "supported_languages": null}, "macro.dbt_utils.test_mutually_exclusive_ranges": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_mutually_exclusive_ranges", "path": "macros/generic_tests/mutually_exclusive_ranges.sql", "arguments": [], "macro_sql": "{% test mutually_exclusive_ranges(model, lower_bound_column, upper_bound_column, partition_by=None, gaps='allowed', zero_length_range_allowed=False) %}\\n  {{ return(adapter.dispatch('test_mutually_exclusive_ranges', 'dbt_utils')(model, lower_bound_column, upper_bound_column, partition_by, gaps, zero_length_range_allowed)) }}\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_mutually_exclusive_ranges", "created_at": 1758839281.269737, "depends_on": {"macros": ["macro.dbt_utils.default__test_mutually_exclusive_ranges"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/mutually_exclusive_ranges.sql", "supported_languages": null}, "macro.cht_pipeline_base.max_existing_prior_date": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "max_existing_prior_date", "path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro max_existing_prior_date(datefield, target_ref=this) -%}\\n{#\\n    A day prior to the max of some date field.\\n    Params, Return and Usage as per the max_existing_date() macro\\n#}\\n    {{ return(_cast_as_type(_max_existing_prior_date(datefield, target_ref), 'DATE')) }}\\n{%- endmacro %}", "unique_id": "macro.cht_pipeline_base.max_existing_prior_date", "created_at": 1758839281.3265007, "depends_on": {"macros": ["macro.cht_pipeline_base._cast_as_type", "macro.cht_pipeline_base._max_existing_prior_date"]}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supported_languages": null}, "macro.dbt.default__collect_freshness_custom_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__collect_freshness_custom_sql", "path": "macros/adapters/freshness.sql", "arguments": [], "macro_sql": "{% macro default__collect_freshness_custom_sql(source, loaded_at_query) %}\\n  {% call statement('collect_freshness_custom_sql', fetch_result=True, auto_begin=False) -%}\\n  with source_query as (\\n    {{ loaded_at_query }}\\n  )\\n  select\\n    (select * from source_query) as max_loaded_at,\\n    {{ current_timestamp() }} as snapshotted_at\\n  {% endcall %}\\n  {{ return(load_result('collect_freshness_custom_sql')) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__collect_freshness_custom_sql", "created_at": 1758839281.0142934, "depends_on": {"macros": ["macro.dbt.statement", "macro.dbt.current_timestamp"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/freshness.sql", "supported_languages": null}, "macro.dbt.default__current_timestamp_backcompat": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__current_timestamp_backcompat", "path": "macros/adapters/timestamps.sql", "arguments": [], "macro_sql": "{% macro default__current_timestamp_backcompat() %}\\n    current_timestamp::timestamp\\n{% endmacro %}", "unique_id": "macro.dbt.default__current_timestamp_backcompat", "created_at": 1758839281.0498106, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/timestamps.sql", "supported_languages": null}, "macro.dbt.incremental_validate_on_schema_change": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "incremental_validate_on_schema_change", "path": "macros/materializations/models/incremental/on_schema_change.sql", "arguments": [], "macro_sql": "{% macro incremental_validate_on_schema_change(on_schema_change, default='ignore') %}\\n\\n   {% if on_schema_change not in ['sync_all_columns', 'append_new_columns', 'fail', 'ignore'] %}\\n\\n     {% set log_message = 'Invalid value for on_schema_change (%s) specified. Setting default value of %s.' % (on_schema_change, default) %}\\n     {% do log(log_message) %}\\n\\n     {{ return(default) }}\\n\\n   {% else %}\\n\\n     {{ return(on_schema_change) }}\\n\\n   {% endif %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.incremental_validate_on_schema_change", "created_at": 1758839280.9163437, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/on_schema_change.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_drop_index_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_drop_index_sql", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "\\n\\n\\n{%- macro postgres__get_drop_index_sql(relation, index_name) -%}\\n    drop index if exists \\"{{ relation.schema }}\\".\\"{{ index_name }}\\"\\n{%- endmacro -%}", "unique_id": "macro.dbt_postgres.postgres__get_drop_index_sql", "created_at": 1758839280.7461047, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_show_grant_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_show_grant_sql", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro postgres__get_show_grant_sql(relation) -%}\\n  select grantee, privilege_type\\n  from {{ relation.information_schema('role_table_grants') }}\\n      where grantor = current_role\\n        and grantee != current_role\\n        and table_schema = '{{ relation.schema }}'\\n        and table_name = '{{ relation.identifier }}'\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_postgres.postgres__get_show_grant_sql", "created_at": 1758839280.7451339, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__make_temp_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__make_temp_relation", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__make_temp_relation(base_relation, suffix) %}\\n    {% set temp_relation = postgres__make_relation_with_suffix(base_relation, suffix, dstring=True) %}\\n    {{ return(temp_relation.incorporate(path={\\"schema\\": none,\\n                                              \\"database\\": none})) }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__make_temp_relation", "created_at": 1758839280.7413852, "depends_on": {"macros": ["macro.dbt_postgres.postgres__make_relation_with_suffix"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__snapshot_merge_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__snapshot_merge_sql", "path": "macros/materializations/snapshot_merge.sql", "arguments": [], "macro_sql": "{% macro postgres__snapshot_merge_sql(target, source, insert_cols) -%}\\n    {%- set insert_cols_csv = insert_cols | join(', ') -%}\\n\\n    {%- set columns = config.get(\\"snapshot_table_column_names\\") or get_snapshot_table_column_names() -%}\\n\\n    update {{ target }}\\n    set {{ columns.dbt_valid_to }} = DBT_INTERNAL_SOURCE.{{ columns.dbt_valid_to }}\\n    from {{ source }} as DBT_INTERNAL_SOURCE\\n    where DBT_INTERNAL_SOURCE.{{ columns.dbt_scd_id }}::text = {{ target }}.{{ columns.dbt_scd_id }}::text\\n      and DBT_INTERNAL_SOURCE.dbt_change_type::text in ('update'::text, 'delete'::text)\\n      {% if config.get(\\"dbt_valid_to_current\\") %}\\n        and ({{ target }}.{{ columns.dbt_valid_to }} = {{ config.get('dbt_valid_to_current') }} or {{ target }}.{{ columns.dbt_valid_to }} is null);\\n      {% else %}\\n        and {{ target }}.{{ columns.dbt_valid_to }} is null;\\n      {% endif %}\\n\\n\\n    insert into {{ target }} ({{ insert_cols_csv }})\\n    select {% for column in insert_cols -%}\\n        DBT_INTERNAL_SOURCE.{{ column }} {%- if not loop.last %}, {%- endif %}\\n    {%- endfor %}\\n    from {{ source }} as DBT_INTERNAL_SOURCE\\n    where DBT_INTERNAL_SOURCE.dbt_change_type::text = 'insert'::text;\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__snapshot_merge_sql", "created_at": 1758839280.7628787, "depends_on": {"macros": ["macro.dbt.get_snapshot_table_column_names"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/materializations/snapshot_merge.sql", "supported_languages": null}, "macro.dbt_utils.databricks__get_table_types_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "databricks__get_table_types_sql", "path": "macros/sql/get_table_types_sql.sql", "arguments": [], "macro_sql": "{% macro databricks__get_table_types_sql() %}\\n            case table_type\\n                when 'MANAGED' then 'table'\\n                when 'BASE TABLE' then 'table'\\n                when 'MATERIALIZED VIEW' then 'materializedview'\\n                else lower(table_type)\\n            end as {{ adapter.quote('table_type') }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.databricks__get_table_types_sql", "created_at": 1758839281.2367847, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_table_types_sql.sql", "supported_languages": null}, "macro.dbt_utils.default__generate_surrogate_key": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__generate_surrogate_key", "path": "macros/sql/generate_surrogate_key.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__generate_surrogate_key(field_list) -%}\\n\\n{%- if var('surrogate_key_treat_nulls_as_empty_strings', False) -%}\\n    {%- set default_null_value = \\"\\" -%}\\n{%- else -%}\\n    {%- set default_null_value = '_dbt_utils_surrogate_key_null_' -%}\\n{%- endif -%}\\n\\n{%- set fields = [] -%}\\n\\n{%- for field in field_list -%}\\n\\n    {%- do fields.append(\\n        \\"coalesce(cast(\\" ~ field ~ \\" as \\" ~ dbt.type_string() ~ \\"), '\\" ~ default_null_value  ~\\"')\\"\\n    ) -%}\\n\\n    {%- if not loop.last %}\\n        {%- do fields.append(\\"'-'\\") -%}\\n    {%- endif -%}\\n\\n{%- endfor -%}\\n\\n{{ dbt.hash(dbt.concat(fields)) }}\\n\\n{%- endmacro -%}", "unique_id": "macro.dbt_utils.default__generate_surrogate_key", "created_at": 1758839281.204699, "depends_on": {"macros": ["macro.dbt.type_string", "macro.dbt.hash", "macro.dbt.concat"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/generate_surrogate_key.sql", "supported_languages": null}, "macro.dbt_utils.default__test_sequential_values": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_sequential_values", "path": "macros/generic_tests/sequential_values.sql", "arguments": [], "macro_sql": "{% macro default__test_sequential_values(model, column_name, interval=1, datepart=None, group_by_columns = []) %}\\n\\n{% set previous_column_name = \\"previous_\\" ~ dbt_utils.slugify(column_name) %}\\n\\n{% if group_by_columns|length() > 0 %}\\n  {% set select_gb_cols = group_by_columns|join(',') + ', ' %}\\n  {% set partition_gb_cols = 'partition by ' + group_by_columns|join(',') %}\\n{% endif %}\\n\\nwith windowed as (\\n\\n    select\\n        {{ select_gb_cols }}\\n        {{ column_name }},\\n        lag({{ column_name }}) over (\\n            {{partition_gb_cols}}\\n            order by {{ column_name }}\\n        ) as {{ previous_column_name }}\\n    from {{ model }}\\n),\\n\\nvalidation_errors as (\\n    select\\n        *\\n    from windowed\\n    {% if datepart %}\\n    where not(cast({{ column_name }} as {{ dbt.type_timestamp() }})= cast({{ dbt.dateadd(datepart, interval, previous_column_name) }} as {{ dbt.type_timestamp() }}))\\n    {% else %}\\n    where not({{ column_name }} = {{ previous_column_name }} + {{ interval }})\\n    {% endif %}\\n)\\n\\nselect *\\nfrom validation_errors\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_sequential_values", "created_at": 1758839281.280562, "depends_on": {"macros": ["macro.dbt_utils.slugify", "macro.dbt.type_timestamp", "macro.dbt.dateadd"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/sequential_values.sql", "supported_languages": null}, "macro.cht_pipeline_base._max_existing_prior_date": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "_max_existing_prior_date", "path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro _max_existing_prior_date(datefield, target_ref=this) -%}\\n    {% call statement('max_existing_prior_date', fetch_result=True)-%}\\n\\n        SELECT {{ dbt_utils.dateadd('day', -1,  \\"max(\\" ~ datefield ~ \\")\\" ) }} as max_existing_prior_date\\n        FROM {{ '\\"' ~ this.schema ~ '\\"' ~ '.' ~ '\\"' ~ this.name~ '\\"' if target_ref in [this] else target_ref }}\\n\\n    {%- endcall %}\\n    {% set max_existing_prior = load_result('max_existing_prior_date').table.columns['max_existing_prior_date'].values()[0] %}\\n    {{ return(max_existing_prior) }}\\n{%- endmacro %}", "unique_id": "macro.cht_pipeline_base._max_existing_prior_date", "created_at": 1758839281.3260596, "depends_on": {"macros": ["macro.dbt.statement", "macro.dbt.dateadd"]}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supported_languages": null}, "macro.dbt.default__get_assert_columns_equivalent": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_assert_columns_equivalent", "path": "macros/relations/column/columns_spec_ddl.sql", "arguments": [], "macro_sql": "{% macro default__get_assert_columns_equivalent(sql) -%}\\n  {{ return(assert_columns_equivalent(sql)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.default__get_assert_columns_equivalent", "created_at": 1758839280.8092291, "depends_on": {"macros": ["macro.dbt.assert_columns_equivalent"]},