     {%- endfor -%}\\n\\n        {{ return(tbl_relations) }}\\n    {%- else -%}\\n        {{ return([]) }}\\n    {%- endif -%}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__get_relations_by_prefix", "created_at": 1758839281.2612996, "depends_on": {"macros": ["macro.dbt.statement", "macro.dbt_utils.get_tables_by_prefix_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_relations_by_prefix.sql", "supported_languages": null}, "macro.dbt_utils.default__test_expression_is_true": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_expression_is_true", "path": "macros/generic_tests/expression_is_true.sql", "arguments": [], "macro_sql": "{% macro default__test_expression_is_true(model, expression, column_name) %}\\n\\n{% set column_list = '*' if should_store_failures() else \\"1\\" %}\\n\\nselect\\n    {{ column_list }}\\nfrom {{ model }}\\n{% if column_name is none %}\\nwhere not({{ expression }})\\n{%- else %}\\nwhere not({{ column_name }} {{ expression }})\\n{%- endif %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_expression_is_true", "created_at": 1758839281.285619, "depends_on": {"macros": ["macro.dbt.should_store_failures"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/expression_is_true.sql", "supported_languages": null}, "macro.dbt_utils.get_filtered_columns_in_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_filtered_columns_in_relation", "path": "macros/sql/get_filtered_columns_in_relation.sql", "arguments": [], "macro_sql": "{% macro get_filtered_columns_in_relation(from, except=[]) -%}\\n    {{ return(adapter.dispatch('get_filtered_columns_in_relation', 'dbt_utils')(from, except)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.get_filtered_columns_in_relation", "created_at": 1758839281.198662, "depends_on": {"macros": ["macro.dbt_utils.default__get_filtered_columns_in_relation"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_filtered_columns_in_relation.sql", "supported_languages": null}, "macro.dbt.default__get_incremental_microbatch_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_incremental_microbatch_sql", "path": "macros/materializations/models/incremental/strategies.sql", "arguments": [], "macro_sql": "{% macro default__get_incremental_microbatch_sql(arg_dict) %}\\n\\n  {{ exceptions.raise_not_implemented('microbatch materialization strategy not implemented for adapter ' + adapter.type()) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_incremental_microbatch_sql", "created_at": 1758839280.928228, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/strategies.sql", "supported_languages": null}, "macro.dbt.default__get_insert_overwrite_merge_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_insert_overwrite_merge_sql", "path": "macros/materializations/models/incremental/merge.sql", "arguments": [], "macro_sql": "{% macro default__get_insert_overwrite_merge_sql(target, source, dest_columns, predicates, include_sql_header) -%}\\n    {#-- The only time include_sql_header is True: --#}\\n    {#-- BigQuery + insert_overwrite strategy + \\"static\\" partitions config --#}\\n    {#-- We should consider including the sql header at the materialization level instead --#}\\n\\n    {%- set predicates = [] if predicates is none else [] + predicates -%}\\n    {%- set dest_cols_csv = get_quoted_csv(dest_columns | map(attribute=\\"name\\")) -%}\\n    {%- set sql_header = config.get('sql_header', none) -%}\\n\\n    {{ sql_header if sql_header is not none and include_sql_header }}\\n\\n    merge into {{ target }} as DBT_INTERNAL_DEST\\n        using {{ source }} as DBT_INTERNAL_SOURCE\\n        on FALSE\\n\\n    when not matched by source\\n        {% if predicates %} and {{ predicates | join(' and ') }} {% endif %}\\n        then delete\\n\\n    when not matched then insert\\n        ({{ dest_cols_csv }})\\n    values\\n        ({{ dest_cols_csv }})\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_insert_overwrite_merge_sql", "created_at": 1758839280.907529, "depends_on": {"macros": ["macro.dbt.get_quoted_csv"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/merge.sql", "supported_languages": null}, "macro.dbt.default__list_relations_without_caching": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__list_relations_without_caching", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro default__list_relations_without_caching(schema_relation) %}\\n  {{ exceptions.raise_not_implemented(\\n    'list_relations_without_caching macro not implemented for adapter '+adapter.type()) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__list_relations_without_caching", "created_at": 1758839281.0075486, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt.snapshot_check_all_get_existing_columns": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snapshot_check_all_get_existing_columns", "path": "macros/materializations/snapshots/strategies.sql", "arguments": [], "macro_sql": "{% macro snapshot_check_all_get_existing_columns(node, target_exists, check_cols_config) -%}\\n    {%- if not target_exists -%}\\n        {#-- no table yet -> return whatever the query does --#}\\n        {{ return((false, query_columns)) }}\\n    {%- endif -%}\\n\\n    {#-- handle any schema changes --#}\\n    {%- set target_relation = adapter.get_relation(database=node.database, schema=node.schema, identifier=node.alias) -%}\\n\\n    {% if check_cols_config == 'all' %}\\n        {%- set query_columns = get_columns_in_query(node['compiled_code']) -%}\\n\\n    {% elif check_cols_config is iterable and (check_cols_config | length) > 0 %}\\n        {#-- query for proper casing/quoting, to support comparison below --#}\\n        {%- set select_check_cols_from_target -%}\\n            {#-- N.B. The whitespace below is necessary to avoid edge case issue with comments --#}\\n            {#-- See: https://github.com/dbt-labs/dbt-core/issues/6781 --#}\\n            select {{ check_cols_config | join(', ') }} from (\\n                {{ node['compiled_code'] }}\\n            ) subq\\n        {%- endset -%}\\n        {% set query_columns = get_columns_in_query(select_check_cols_from_target) %}\\n\\n    {% else %}\\n        {% do exceptions.raise_compiler_error(\\"Invalid value for 'check_cols': \\" ~ check_cols_config) %}\\n    {% endif %}\\n\\n    {%- set existing_cols = adapter.get_columns_in_relation(target_relation) | map(attribute = 'name') | list -%}\\n    {%- set ns = namespace() -%} {#-- handle for-loop scoping with a namespace --#}\\n    {%- set ns.column_added = false -%}\\n\\n    {%- set intersection = [] -%}\\n    {%- for col in query_columns -%}\\n        {%- if col in existing_cols -%}\\n            {%- do intersection.append(adapter.quote(col)) -%}\\n        {%- else -%}\\n            {% set ns.column_added = true %}\\n        {%- endif -%}\\n    {%- endfor -%}\\n    {{ return((ns.column_added, intersection)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.snapshot_check_all_get_existing_columns", "created_at": 1758839280.876244, "depends_on": {"macros": ["macro.dbt.get_columns_in_query"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/strategies.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__alter_column_comment": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__alter_column_comment", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__alter_column_comment(relation, column_dict) %}\\n  {% set existing_columns = adapter.get_columns_in_relation(relation) | map(attribute=\\"name\\") | list %}\\n  {% for column_name in column_dict if (column_name in existing_columns) %}\\n    {% set comment = column_dict[column_name]['description'] %}\\n    {% set escaped_comment = postgres_escape_comment(comment) %}\\n    comment on column {{ relation }}.{{ adapter.quote(column_name) if column_dict[column_name]['quote'] else column_name }} is {{ escaped_comment }};\\n  {% endfor %}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__alter_column_comment", "created_at": 1758839280.7447028, "depends_on": {"macros": ["macro.dbt_postgres.postgres_escape_comment"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_create_index_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_create_index_sql", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__get_create_index_sql(relation, index_dict) -%}\\n  {%- set index_config = adapter.parse_index(index_dict) -%}\\n  {%- set comma_separated_columns = \\", \\".join(index_config.columns) -%}\\n  {%- set index_name = index_config.render(relation) -%}\\n\\n  create {% if index_config.unique -%}\\n    unique\\n  {%- endif %} index if not exists\\n  \\"{{ index_name }}\\"\\n  on {{ relation }} {% if index_config.type -%}\\n    using {{ index_config.type }}\\n  {%- endif %}\\n  ({{ comma_separated_columns }})\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_create_index_sql", "created_at": 1758839280.7338655, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_rename_table_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_rename_table_sql", "path": "macros/relations/table/rename.sql", "arguments": [], "macro_sql": "{% macro postgres__get_rename_table_sql(relation, new_name) %}\\n    alter table {{ relation }} rename to {{ new_name }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_rename_table_sql", "created_at": 1758839280.753385, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/relations/table/rename.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_replace_view_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_replace_view_sql", "path": "macros/relations/view/replace.sql", "arguments": [], "macro_sql": "{% macro postgres__get_replace_view_sql(relation, sql) -%}\\n\\n    {%- set sql_header = config.get('sql_header', none) -%}\\n    {{ sql_header if sql_header is not none }}\\n\\n    create or replace view {{ relation }}\\n        {% set contract_config = config.get('contract') %}\\n        {% if contract_config.enforced %}\\n            {{ get_assert_columns_equivalent(sql) }}\\n        {%- endif %}\\n    as (\\n        {{ sql }}\\n    );\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_replace_view_sql", "created_at": 1758839280.7511413, "depends_on": {"macros": ["macro.dbt.get_assert_columns_equivalent"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/relations/view/replace.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_show_indexes_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_show_indexes_sql", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__get_show_indexes_sql(relation) %}\\n    select\\n        i.relname                                   as name,\\n        m.amname                                    as method,\\n        ix.indisunique                              as \\"unique\\",\\n        array_to_string(array_agg(a.attname), ',')  as column_names\\n    from pg_index ix\\n    join pg_class i\\n        on i.oid = ix.indexrelid\\n    join pg_am m\\n        on m.oid=i.relam\\n    join pg_class t\\n        on t.oid = ix.indrelid\\n    join pg_namespace n\\n        on n.oid = t.relnamespace\\n    join pg_attribute a\\n        on a.attrelid = t.oid\\n        and a.attnum = ANY(ix.indkey)\\n    where t.relname = '{{ relation.identifier }}'\\n      and n.nspname = '{{ relation.schema }}'\\n      and t.relkind in ('r', 'm')\\n    group by 1, 2, 3\\n    order by 1, 2, 3\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_show_indexes_sql", "created_at": 1758839280.745783, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__make_backup_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__make_backup_relation", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__make_backup_relation(base_relation, backup_relation_type, suffix) %}\\n    {% set backup_relation = postgres__make_relation_with_suffix(base_relation, suffix, dstring=False) %}\\n    {{ return(backup_relation.incorporate(type=backup_relation_type)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__make_backup_relation", "created_at": 1758839280.7419264, "depends_on": {"macros": ["macro.dbt_postgres.postgres__make_relation_with_suffix"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_utils.default__get_relations_by_pattern": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_relations_by_pattern", "path": "macros/sql/get_relations_by_pattern.sql", "arguments": [], "macro_sql": "{% macro default__get_relations_by_pattern(schema_pattern, table_pattern, exclude='', database=target.database) %}\\n\\n    {%- call statement('get_tables', fetch_result=True) %}\\n\\n      {{ dbt_utils.get_tables_by_pattern_sql(schema_pattern, table_pattern, exclude, database) }}\\n\\n    {%- endcall -%}\\n\\n    {%- set table_list = load_result('get_tables') -%}\\n\\n    {%- if table_list and table_list['table'] -%}\\n        {%- set tbl_relations = [] -%}\\n        {%- for row in table_list['table'] -%}\\n            {%- set tbl_relation = api.Relation.create(\\n                database=database,\\n                schema=row.table_schema,\\n                identifier=row.table_name,\\n                type=row.table_type\\n            ) -%}\\n            {%- do tbl_relations.append(tbl_relation) -%}\\n        {%- endfor -%}\\n\\n        {{ return(tbl_relations) }}\\n    {%- else -%}\\n        {{ return([]) }}\\n    {%- endif -%}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__get_relations_by_pattern", "created_at": 1758839281.2072394, "depends_on": {"macros": ["macro.dbt.statement", "macro.dbt_utils.get_tables_by_pattern_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_relations_by_pattern.sql", "supported_languages": null}, "macro.dbt_utils.default__get_tables_by_prefix_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_tables_by_prefix_sql", "path": "macros/sql/get_tables_by_prefix_sql.sql", "arguments": [], "macro_sql": "{% macro default__get_tables_by_prefix_sql(schema, prefix, exclude='', database=target.database) %}\\n\\n    {{ dbt_utils.get_tables_by_pattern_sql(\\n        schema_pattern = schema,\\n        table_pattern = prefix ~ '%',\\n        exclude = exclude,\\n        database = database\\n    ) }}\\n    \\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__get_tables_by_prefix_sql", "created_at": 1758839281.2182097, "depends_on": {"macros": ["macro.dbt_utils.get_tables_by_pattern_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_tables_by_prefix_sql.sql", "supported_languages": null}, "macro.dbt_utils.default__test_not_accepted_values": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_not_accepted_values", "path": "macros/generic_tests/not_accepted_values.sql", "arguments": [], "macro_sql": "{% macro default__test_not_accepted_values(model, column_name, values, quote=True) %}\\nwith all_values as (\\n\\n    select distinct\\n        {{ column_name }} as value_field\\n\\n    from {{ model }}\\n\\n),\\n\\nvalidation_errors as (\\n\\n    select\\n        value_field\\n\\n    from all_values\\n    where value_field in (\\n        {% for value in values -%}\\n            {% if quote -%}\\n            '{{ value }}'\\n            {%- else -%}\\n            {{ value }}\\n            {%- endif -%}\\n            {%- if not loop.last -%},{%- endif %}\\n        {%- endfor %}\\n        )\\n\\n)\\n\\nselect *\\nfrom validation_errors\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_not_accepted_values", "created_at": 1758839281.277635, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/not_accepted_values.sql", "supported_languages": null}, "macro.dbt_utils.default__test_not_null_proportion": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_not_null_proportion", "path": "macros/generic_tests/not_null_proportion.sql", "arguments": [], "macro_sql": "{% macro default__test_not_null_proportion(model, group_by_columns) %}\\n\\n{% set column_name = kwargs.get('column_name', kwargs.get('arg')) %}\\n{% set at_least = kwargs.get('at_least', kwargs.get('arg')) %}\\n{% set at_most = kwargs.get('at_most', kwargs.get('arg', 1)) %}\\n\\n{% if group_by_columns|length() > 0 %}\\n  {% set select_gb_cols = group_by_columns|join(' ,') + ', ' %}\\n  {% set groupby_gb_cols = 'group by ' + group_by_columns|join(',') %}\\n{% endif %}\\n\\nwith validation as (\\n  select\\n    {{select_gb_cols}}\\n    sum(case when {{ column_name }} is null then 0 else 1 end) / cast(count(*) as numeric) as not_null_proportion\\n  from {{ model }}\\n  {{groupby_gb_cols}}\\n),\\nvalidation_errors as (\\n  select\\n    {{select_gb_cols}}\\n    not_null_proportion\\n  from validation\\n  where not_null_proportion < {{ at_least }} or not_null_proportion > {{ at_most }}\\n)\\nselect\\n  *\\nfrom validation_errors\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_not_null_proportion", "created_at": 1758839281.2683287, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/not_null_proportion.sql", "supported_languages": null}, "macro.dbt_utils.default__test_relationships_where": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_relationships_where", "path": "macros/generic_tests/relationships_where.sql", "arguments": [], "macro_sql": "{% macro default__test_relationships_where(model, column_name, to, field, from_condition=\\"1=1\\", to_condition=\\"1=1\\") %}\\n\\n{# T-SQL has no boolean data type so we use 1=1 which returns TRUE #}\\n{# ref https://stackoverflow.com/a/7170753/3842610 #}\\n\\nwith left_table as (\\n\\n  select\\n    {{column_name}} as id\\n\\n  from {{model}}\\n\\n  where {{column_name}} is not null\\n    and {{from_condition}}\\n\\n),\\n\\nright_table as (\\n\\n  select\\n    {{field}} as id\\n\\n  from {{to}}\\n\\n  where {{field}} is not null\\n    and {{to_condition}}\\n\\n),\\n\\nexceptions as (\\n\\n  select\\n    left_table.id,\\n    right_table.id as right_id\\n\\n  from left_table\\n\\n  left join right_table\\n         on left_table.id = right_table.id\\n\\n  where right_table.id is null\\n\\n)\\n\\nselect * from exceptions\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_relationships_where", "created_at": 1758839281.3033974, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/relationships_where.sql", "supported_languages": null}, "macro.dbt.default__get_catalog_for_single_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_catalog_for_single_relation", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro default__get_catalog_for_single_relation(relation) %}\\n  {{ exceptions.raise_not_implemented(\\n    'get_catalog_for_single_relation macro not implemented for adapter '+adapter.type()) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_catalog_for_single_relation", "created_at": 1758839281.008236, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_catalog_relations": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_catalog_relations", "path": "macros/catalog.sql", "arguments": [], "macro_sql": "{% macro postgres__get_catalog_relations(information_schema, relations) -%}\\n  {%- call statement('catalog', fetch_result=True) -%}\\n\\n    {#\\n      If the user has multiple databases set and the first one is wrong, this will fail.\\n      But we won't fail in the case where there are multiple quoting-difference-only dbs, which is better.\\n    #}\\n    {% set database = information_schema.database %}\\n    {{ adapter.verify_database(database) }}\\n\\n    select\\n        '{{ database }}' as table_database,\\n        sch.nspname as table_schema,\\n        tbl.relname as table_name,\\n        case tbl.relkind\\n            when 'v' then 'VIEW'\\n            when 'm' then 'MATERIALIZED VIEW'\\n            else 'BASE TABLE'\\n        end as table_type,\\n        tbl_desc.description as table_comment,\\n        col.attname as column_name,\\n        col.attnum as column_index,\\n        pg_catalog.format_type(col.atttypid, col.atttypmod) as column_type,\\n        col_desc.description as column_comment,\\n        pg_get_userbyid(tbl.relowner) as table_owner\\n\\n    from pg_catalog.pg_namespace sch\\n    join pg_catalog.pg_class tbl on tbl.relnamespace = sch.oid\\n    join pg_catalog.pg_attribute col on col.attrelid = tbl.oid\\n    left outer join pg_catalog.pg_description tbl_desc on (tbl_desc.objoid = tbl.oid and tbl_desc.objsubid = 0)\\n    left outer join pg_catalog.pg_description col_desc on (col_desc.objoid = tbl.oid and col_desc.objsubid = col.attnum)\\n    where (\\n      {%- for relation in relations -%}\\n        {%- if relation.identifier -%}\\n          (upper(sch.nspname) = upper('{{ relation.schema }}') and\\n           upper(tbl.relname) = upper('{{ relation.identifier }}'))\\n        {%- else-%}\\n          upper(sch.nspname) = upper('{{ relation.schema }}')\\n        {%- endif -%}\\n        {%- if not loop.last %} or {% endif -%}\\n      {%- endfor -%}\\n    )\\n      and not pg_is_other_temp_schema(sch.oid) -- not a temporary schema belonging to another session\\n      and tbl.relpersistence in ('p', 'u') -- [p]ermanent table or [u]nlogged table. Exclude [t]emporary tables\\n      and tbl.relkind in ('r', 'v', 'f', 'p', 'm') -- o[r]dinary table, [v]iew, [f]oreign table, [p]artitioned table, [m]aterialized view. Other values are [i]ndex, [S]equence, [c]omposite type, [t]OAST table\\n      and col.attnum > 0 -- negative numbers are used for system columns such as oid\\n      and not col.attisdropped -- column as not been dropped\\n\\n    order by\\n        sch.nspname,\\n        tbl.relname,\\n        col.attnum\\n\\n  {%- endcall -%}\\n\\n  {{ return(load_result('catalog').table) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_catalog_relations", "created_at": 1758839280.7479997, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/catalog.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_replace_table_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_replace_table_sql", "path": "macros/relations/table/replace.sql", "arguments": [], "macro_sql": "{% macro postgres__get_replace_table_sql(relation, sql) -%}\\n\\n    {%- set sql_header = config.get('sql_header', none) -%}\\n    {{ sql_header if sql_header is not none }}\\n\\n    create or replace table {{ relation }}\\n        {% set contract_config = config.get('contract') %}\\n        {% if contract_config.enforced %}\\n            {{ get_assert_columns_equivalent(sql) }}\\n            {{ get_table_columns_and_constraints() }}\\n            {%- set sql = get_select_subquery(sql) %}\\n        {% endif %}\\n    as (\\n        {{ sql }}\\n    );\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_replace_table_sql", "created_at": 1758839280.7530246, "depends_on": {"macros": ["macro.dbt.get_assert_columns_equivalent", "macro.dbt.get_table_columns_and_constraints", "macro.dbt.get_select_subquery"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/relations/table/replace.sql", "supported_languages": null}, "macro.dbt_utils.default__get_query_results_as_dict": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_query_results_as_dict", "path": "macros/sql/get_query_results_as_dict.sql", "arguments": [], "macro_sql": "{% macro default__get_query_results_as_dict(query) %}\\n\\n{# This macro returns a dictionary of the form {column_name: (tuple_of_results)} #}\\n\\n    {%- call statement('get_query_results', fetch_result=True,auto_begin=false) -%}\\n\\n        {{ query }}\\n\\n    {%- endcall -%}\\n\\n    {% set sql_results={} %}\\n\\n    {%- if execute -%}\\n        {% set sql_results_table = load_result('get_query_results').table.columns %}\\n        {% for column_name, column in sql_results_table.items() %}\\n            {% do sql_results.update({column_name: column.values()}) %}\\n        {% endfor %}\\n    {%- endif -%}\\n\\n    {{ return(sql_results) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__get_query_results_as_dict", "created_at": 1758839281.250471, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_query_results_as_dict.sql", "supported_languages": null}, "macro.dbt_utils.default__get_tables_by_pattern_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_tables_by_pattern_sql", "path": "macros/sql/get_tables_by_pattern_sql.sql", "arguments": [], "macro_sql": "{% macro default__get_tables_by_pattern_sql(schema_pattern, table_pattern, exclude='', database=target.database) %}\\n\\n        select distinct\\n            table_schema as {{ adapter.quote('table_schema') }},\\n            table_name as {{ adapter.quote('table_name') }},\\n            {{ dbt_utils.get_table_types_sql() }}\\n        from {{ database }}.information_schema.tables\\n        where table_schema ilike '{{ schema_pattern }}'\\n        and table_name ilike '{{ table_pattern }}'\\n        and table_name not ilike '{{ exclude }}'\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__get_tables_by_pattern_sql", "created_at": 1758839281.2564697, "depends_on": {"macros": ["macro.dbt_utils.get_table_types_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_tables_by_pattern_sql.sql", "supported_languages": null}, "macro.dbt_utils.default__test_cardinality_equality": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_cardinality_equality", "path": "macros/generic_tests/cardinality_equality.sql", "arguments": [], "macro_sql": "{% macro default__test_cardinality_equality(model, column_name, to, field) %}\\n\\n{# T-SQL does not let you use numbers as aliases for columns #}\\n{# Thus, no \\"GROUP BY 1\\" #}\\n\\nwith table_a as (\\nselect\\n  {{ column_name }},\\n  count(*) as num_rows\\nfrom {{ model }}\\ngroup by {{ column_name }}\\n),\\n\\ntable_b as (\\nselect\\n  {{ field }},\\n  count(*) as num_rows\\nfrom {{ to }}\\ngroup by {{ field }}\\n),\\n\\nexcept_a as (\\n  select *\\n  from table_a\\n  {{ dbt.except() }}\\n  select *\\n  from table_b\\n),\\n\\nexcept_b as (\\n  select *\\n  from table_b\\n  {{ dbt.except() }}\\n  select *\\n  from table_a\\n),\\n\\nunioned as (\\n  select *\\n  from except_a\\n  union all\\n  select *\\n  from except_b\\n)\\n\\nselect *\\nfrom unioned\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_cardinality_equality", "created_at": 1758839281.3012853, "depends_on": {"macros": ["macro.dbt.except"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/cardinality_equality.sql", "supported_languages": null}, "macro.dbt_utils.test_unique_combination_of_columns": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_unique_combination_of_columns", "path": "macros/generic_tests/unique_combination_of_columns.sql", "arguments": [], "macro_sql": "{% test unique_combination_of_columns(model, combination_of_columns, quote_columns=false) %}\\n  {{ return(adapter.dispatch('test_unique_combination_of_columns', 'dbt_utils')(model, combination_of_columns, quote_columns)) }}\\n{% endtest %}", "unique_id": "macro.dbt_utils.test_unique_combination_of_columns", "created_at": 1758839281.2735183, "depends_on": {"macros": ["macro.dbt_utils.default__test_unique_combination_of_columns"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/unique_combination_of_columns.sql", "supported_languages": null}, "macro.dbt.default__get_rename_materialized_view_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_rename_materialized_view_sql", "path": "macros/relations/materialized_view/rename.sql", "arguments": [], "macro_sql": "{% macro default__get_rename_materialized_view_sql(relation, new_name) %}\\n    {{ exceptions.raise_compiler_error(\\n        \\"`get_rename_materialized_view_sql` has not been implemented for this adapter.\\"\\n    ) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_rename_materialized_view_sql", "created_at": 1758839280.8152168, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/materialized_view/rename.sql", "supported_languages": null}, "macro.dbt.materialization_materialized_view_default": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "materialization_materialized_view_default", "path": "macros/materializations/models/materialized_view.sql", "arguments": [], "macro_sql": "{% materialization materialized_view, default %}\\n    {% set existing_relation = load_cached_relation(this) %}\\n    {% set target_relation = this.incorporate(type=this.MaterializedView) %}\\n    {% set intermediate_relation = make_intermediate_relation(target_relation) %}\\n    {% set backup_relation_type = target_relation.MaterializedView if existing_relation is none else existing_relation.type %}\\n    {% set backup_relation = make_backup_relation(target_relation, backup_relation_type) %}\\n\\n    {{ materialized_view_setup(backup_relation, intermediate_relation, pre_hooks) }}\\n\\n        {% set build_sql = materialized_view_get_build_sql(existing_relation, target_relation, backup_relation, intermediate_relation) %}\\n\\n        {% if build_sql == '' %}\\n            {{ materialized_view_execute_no_op(target_relation) }}\\n        {% else %}\\n            {{ materialized_view_execute_build_sql(build_sql, existing_relation, target_relation, post_hooks) }}\\n        {% endif %}\\n\\n    {{ materialized_view_teardown(backup_relation, intermediate_relation, post_hooks) }}\\n\\n    {{ return({'relations': [target_relation]}) }}\\n\\n{% endmaterialization %}", "unique_id": "macro.dbt.materialization_materialized_view_default", "created_at": 1758839280.8927307, "depends_on": {"macros": ["macro.dbt.load_cached_relation", "macro.dbt.make_intermediate_relation", "macro.dbt.make_backup_relation", "macro.dbt.materialized_view_setup", "macro.dbt.materialized_view_get_build_sql", "macro.dbt.materialized_view_execute_no_op", "macro.dbt.materialized_view_execute_build_sql", "macro.dbt.materialized_view_teardown"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/materialized_view.sql", "supported_languages": ["sql"]}, "macro.dbt_postgres.postgres__alter_relation_comment": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__alter_relation_comment", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__alter_relation_comment(relation, comment) %}\\n  {% set escaped_comment = postgres_escape_comment(comment) %}\\n  {% if relation.type == 'materialized_view' -%}\\n    {% set relation_type = \\"materialized view\\" %}\\n  {%- else -%}\\n    {%- set relation_type = relation.type -%}\\n  {%- endif -%}\\n  comment on {{ relation_type }} {{ relation }} is {{ escaped_comment }};\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__alter_relation_comment", "created_at": 1758839280.7435553, "depends_on": {"macros": ["macro.dbt_postgres.postgres_escape_comment"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__drop_materialized_view": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__drop_materialized_view", "path": "macros/relations/materialized_view/drop.sql", "arguments": [], "macro_sql": "{% macro postgres__drop_materialized_view(relation) -%}\\n    drop materialized view if exists {{ relation }} cascade\\n{%- endmacro %}", "unique_id": "macro.dbt_postgres.postgres__drop_materialized_view", "created_at": 1758839280.7587318, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/relations/materialized_view/drop.sql", "supported_languages": null}, "macro.dbt_utils.bigquery__get_tables_by_pattern_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "bigquery__get_tables_by_pattern_sql", "path": "macros/sql/get_tables_by_pattern_sql.sql", "arguments": [], "macro_sql": "{% macro bigquery__get_tables_by_pattern_sql(schema_pattern, table_pattern, exclude='', database=target.database) %}\\n\\n    {% if '%' in schema_pattern %}\\n        {% set schemata=dbt_utils._bigquery__get_matching_schemata(schema_pattern, database) %}\\n    {% else %}\\n        {% set schemata=[schema_pattern] %}\\n    {% endif %}\\n\\n    {% set sql %}\\n        {% for schema in schemata %}\\n            select distinct\\n                table_schema,\\n                table_name,\\n                {{ dbt_utils.get_table_types_sql() }}\\n\\n            from {{ adapter.quote(database) }}.{{ schema }}.INFORMATION_SCHEMA.TABLES\\n            where lower(table_name) like lower ('{{ table_pattern }}')\\n                and lower(table_name) not like lower ('{{ exclude }}')\\n\\n            {% if not loop.last %} union all {% endif %}\\n\\n        {% endfor %}\\n    {% endset %}\\n\\n    {{ return(sql) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.bigquery__get_tables_by_pattern_sql", "created_at": 1758839281.257832, "depends_on": {"macros": ["macro.dbt_utils._bigquery__get_matching_schemata", "macro.dbt_utils.get_table_types_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_tables_by_pattern_sql.sql", "supported_languages": null}, "macro.cht_pipeline_base.max_existing_prior_timestamp": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "max_existing_prior_timestamp", "path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro max_existing_prior_timestamp(datefield, target_ref=this) -%}\\n{#\\n    A day prior to the max of some timestamp field\\n    Params, Return and Usage as per the max_existing_date() macro\\n#}\\n    {{ return(_cast_as_type(_max_existing_prior_date(datefield, target_ref), 'TIMESTAMP')) }}\\n{%- endmacro %}", "unique_id": "macro.cht_pipeline_base.max_existing_prior_timestamp", "created_at": 1758839281.3269072, "depends_on": {"macros": ["macro.cht_pipeline_base._cast_as_type", "macro.cht_pipeline_base._max_existing_prior_date"]}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supp