on\\": \\"<name>\\", \\"context\\": ...}]}\\n\\n    For example:\\n    {\\n        \\"indexes\\": [\\n            {\\"action\\": \\"drop\\", \\"context\\": \\"index_abc\\"},\\n            {\\"action\\": \\"create\\", \\"context\\": {\\"columns\\": [\\"column_1\\", \\"column_2\\"], \\"type\\": \\"hash\\", \\"unique\\": True}},\\n        ],\\n    }\\n\\n    Either way, `get_materialized_view_configuration_changes` needs to align with `get_alter_materialized_view_as_sql`.\\n    #} */\\n    {{- log('Determining configuration changes on: ' ~ existing_relation) -}}\\n    {%- do return(adapter.dispatch('get_materialized_view_configuration_changes', 'dbt')(existing_relation, new_config)) -%}\\n{% endmacro %}", "unique_id": "macro.dbt.get_materialized_view_configuration_changes", "created_at": 1758839280.8171244, "depends_on": {"macros": ["macro.dbt_postgres.postgres__get_materialized_view_configuration_changes"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/materialized_view/alter.sql", "supported_languages": null}, "macro.dbt.support_multiple_grantees_per_dcl_statement": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "support_multiple_grantees_per_dcl_statement", "path": "macros/adapters/apply_grants.sql", "arguments": [], "macro_sql": "{% macro support_multiple_grantees_per_dcl_statement() %}\\n    {{ return(adapter.dispatch('support_multiple_grantees_per_dcl_statement', 'dbt')()) }}\\n{% endmacro %}", "unique_id": "macro.dbt.support_multiple_grantees_per_dcl_statement", "created_at": 1758839281.0253122, "depends_on": {"macros": ["macro.dbt.default__support_multiple_grantees_per_dcl_statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/apply_grants.sql", "supported_languages": null}, "macro.dbt.default__current_timestamp_in_utc_backcompat": {"docs": {"show": true, "node_color": null}, "