 {"meta": {}, "tags": []}, "data_type": "string", "doc_blocks": [], "constraints": [], "description": "", "granularity": null}, "contact_uuid": {"meta": {}, "name": "contact_uuid", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "string", "doc_blocks": [], "constraints": [], "description": "", "granularity": null}, "saved_timestamp": {"meta": {}, "name": "saved_timestamp", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "timestamp", "doc_blocks": [], "constraints": [], "description": "", "granularity": null}}, "metrics": [], "sources": [["couchdb", "medic"]], "version": null, "checksum": {"name": "sha256", "checksum": "16a5783c4aae3b46929c5ea1db83e8438449fe7360807e964e303e7109613fcc"}, "contract": {"checksum": "bcf066bde07dd59d0fe1b87f162052bab2cecc3d8e1c4d35ce34f3147fa05666", "enforced": true, "alias_types": true}, "database": "data", "language": "sql", "raw_code": "{{\\n  config(\\n    materialized = 'incremental',\\n    unique_key='user_id',\\n    on_schema_change='append_new_columns',\\n    indexes=[\\n      {'columns': ['user_id'], 'type': 'hash'},\\n      {'columns': ['saved_timestamp']},\\n    ]\\n  )\\n}}\\n\\nSELECT\\n  document_metadata.uuid as user_id,\\n  document_metadata.saved_timestamp,\\n  COALESCE(\\n    doc->>'contact_id',\\n    doc->>'facility_id'\\n  ) as contact_uuid,\\n  doc->>'language' as language,\\n  doc->>'roles' as roles\\nFROM {{ ref('document_metadata') }} document_metadata\\nINNER JOIN\\n  {{ source('couchdb', env_var('POSTGRES_TABLE')) }} source_table\\n  ON source_table._id = document_metadata.uuid\\nWHERE\\n  document_metadata.doc_type = 'user-settings'\\n  AND document_metadata._deleted = false\\n{% if is_incremental() %}\\n  AND document_metadata.saved_timestamp >= {{ max_existing_timestamp('saved_timestamp') }}\\n{% endif %}", "unique_id": "model.cht_pipeline_base.user", "build_path": null, "created_at": 1758839282.966199, "depends_on": {"nodes": ["source.cht_pipeline_base.c