 "monitoring_messages", "group": null, "access": "protected", "config": {"docs": {"show": true, "node_color": null}, "meta": {}, "tags": ["monitoring"], "alias": null, "begin": null, "group": null, "access": "protected", "grants": {}, "schema": null, "enabled": true, "indexes": [{"type": "hash", "columns": ["uuid"]}, {"columns": ["from_phone"]}, {"columns": ["message_timestamp"]}, {"columns": ["message_health"]}], "quoting": {}, "contract": {"enforced": true, "alias_types": true}, "database": null, "lookback": 1, "packages": [], "pre-hook": [], "freshness": null, "post-hook": [{"sql": "\\n      DO $$\\n      DECLARE\\n        record_count INTEGER;\\n        phone_numbers TEXT;\\n      BEGIN\\n        SELECT COUNT(*) INTO record_count FROM {{ this }};\\n        SELECT STRING_AGG(DISTINCT from_phone, ', ') INTO phone_numbers \\n        FROM {{ this }};\\n        \\n        RAISE NOTICE '=== MONITORING MESSAGES PROCESSING COMPLETE ===';\\n        RAISE NOTICE 'Total records processed: %', record_count;\\n        RAISE NOTICE 'Phone numbers found: %', COALESCE(phone_numbers, 'NONE');\\n        RAISE NOTICE '==============================================';\\n      END $$;\\n    ", "index": null, "transaction": true}], "batch_size": null, "event_time": null, "unique_key": "uuid", "column_types": {}, "full_refresh": null, "materialized": "incremental", "persist_docs": {}, "on_schema_change": "append_new_columns", "concurrent_batches": null, "incremental_strategy": null, "on_configuration_change": "apply"}, "schema": "v1", "columns": {"uuid": {"meta": {}, "name": "uuid", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "string", "doc_blocks": [], "constraints": [{"to": null, "name": null, "type": "foreign_key", "expression": "v1.document_metadata (uuid) ON DELETE CASCADE", "to_columns": [], "warn_unenforced": true, "warn_unsupported": true}, {"to": null, "name": null, "type": "unique", "expression": null, "to_columns": [], "warn_unenforced": true, "warn_unsupported": true}], "description": "", "granularity": null}, "reported": {"meta": {}, "name": "reported", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "timestamp with time zone", "doc_blocks": [], "constraints": [], "description": "", "granularity": null}, "from_phone": {"meta": {}, "name": "from_phone", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "string", "doc_blocks": [], "constraints": [], "description": "", "granularity": null}, "message_health": {"meta": {}, "name": "message_health", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "string", "doc_blocks": [], "constraints": [], "description": "Basic health status - detailed analysis done in Superset queries", "granularity": null}, "message_content": {"meta": {}, "name": "message_content", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "string", "doc_blocks": [], "constraints": [], "description": "SMS message content extracted from multiple possible JSON paths", "granularity": null}, "saved_timestamp": {"meta": {}, "name": "saved_timestamp", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "timestamp", "doc_blocks": [], "constraints": [], "description": "", "granularity": null}, "message_timestamp": {"meta": {}, "name": "message_timestamp", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "timestamp with time zone", "doc_blocks": [], "constraints": [], "description": "Full timestamp when message was sent", "granularity": null}, "time_since_last_message": {"meta": {}, "name": "time_since_last_message", "tags": [], "quote": null, "config": {"meta": {}, "tags": []}, "data_type": "interval", "doc_blocks": [], "constraints": [], "description": "Time elapsed since the last message from this phone number", "granularity": null}}, "metrics": [], "sources": [["couchdb", "medic"]], "version": null, "checksum": {"name": "sha256", "checksum": "9b29cc7fe5d319c63790f2b860db4870f195e7c56d000c5357517969a1abc700"}, "contract": {"checksum": "d19589c4f8c5790aff537d9d96ec094b6831d7aba77654f3bd316d0770269e79", "enforced": true, "alias_types": true}, "database": "data", "language": "sql", "raw_code": "{{\\n  config(\\n    materialized = 'incremental',\\n    unique_key='uuid',\\n    on_schema_change='append_new_columns',\\n    indexes=[\\n      {'columns': ['uuid'], 'type': 'hash'},\\n      {'columns': ['from_phone']},\\n      {'columns': ['message_timestamp']},\\n      {'columns': ['message_health']},\\n    ],\\n    post_hook=\\"\\n      DO $$\\n      DECLARE\\n        record_count INTEGER;\\n        phone_numbers TEXT;\\n      BEGIN\\n        SELECT COUNT(*) INTO record_count FROM {{ this }};\\n        SELECT STRING_AGG(DISTINCT from_phone, ', ') INTO phone_numbers \\n        FROM {{ this }};\\n        \\n        RAISE NOTICE '=== MONITORING MESSAGES PROCESSING COMPLETE ===';\\n        RAISE NOTICE 'Total records processed: %', record_count;\\n        RAISE NOTICE 'Phone numbers found: %', COALESCE(phone_numbers, 'NONE');\\n        RAISE NOTICE '==============================================';\\n      END $$;\\n    \\"\\n  )\\n}}\\n\\n-- Logging configuration for debugging\\n{{ log(\\"=== MONITORING MESSAGES MODEL CONFIGURATION ===\\", info=true) }}\\n{{ log(\\"MONITORING_PHONE_DIGICEL: \\" ~ env_var(\\"MONITORING_PHONE_DIGICEL\\", \\"NOT_SET\\"), info=true) }}\\n{{ log(\\"MONITORING_PHONE_FLOW: \\" ~ env_var(\\"MONITORING_PHONE_FLOW\\", \\"NOT_SET\\"), info=true) }}\\n{{ log(\\"POSTGRES_TABLE: \\" ~ env_var(\\"POSTGRES_TABLE\\", \\"NOT_SET\\"), info=true) }}\\n{{ log(\\"POSTGRES_SCHEMA: \\" ~ env_var(\\"POSTGRES_SCHEMA\\", \\"NOT_SET\\"), info=true) }}\\n{{ log(\\"================================================\\", info=true) }}\\nSELECT\\n  document_metadata.uuid as uuid,\\n  document_metadata.saved_timestamp,\\n  to_timestamp((NULLIF(doc->>'reported_date'::text, ''::text)::bigint / 1000)::double precision) AS reported,\\n  doc->>'from' as from_phone,\\n  \\n  \\n  -- Robust message extraction handling all possible JSON structures\\n  COALESCE(\\n    -- Handle object format: doc.sms_message.message.value\\n    CASE WHEN jsonb_typeof(doc->'sms_message'->'message') = 'object'\\n         THEN doc->'sms_message'->'message'->>'value' END,\\n    -- Handle string format: doc.sms_message.message\\n    doc->'sms_message'->>'message',\\n    -- Fallback to parsed fields\\n    doc->'fields'->>'message',\\n    doc->'fields'->>'sms_message',\\n    -- Historical variants\\n    doc->>'sms_content',\\n    doc->>'content'\\n  ) as message_content,\\n  \\n  to_timestamp((NULLIF(doc->>'reported_date'::text, ''::text)::bigint / 1000)::double precision) as message_timestamp,\\n  \\n  to_timestamp((NULLIF(doc->>'reported_date'::text, ''::text)::bigint / 1000)::double precision) - \\n  LAG(to_timestamp((NULLIF(doc->>'reported_date'::text, ''::text)::bigint / 1000)::double precision)) \\n  OVER (PARTITION BY doc->>'from' ORDER BY to_timestamp((NULLIF(doc->>'reported_date'::text, ''::text)::bigint / 1000)::double precision)) as time_since_last_message,\\n  \\n  -- Basic health status\\n  CASE\\n    WHEN doc->>'errors' IS NOT NULL THEN 'processing_error'\\n    WHEN doc->>'_deleted' = 'true' THEN 'deleted'\\n    ELSE 'healthy'\\n  END as message_health\\n\\nFROM {{ ref('document_metadata') }} document_metadata\\nINNER JOIN\\n  {{ source('couchdb', env_var('POSTGRES_TABLE')) }} source_table\\n  ON source_table._id = document_metadata.uuid\\nWHERE\\n  document_metadata.doc_type = 'data_record'\\n  AND document_metadata._deleted = false\\n  AND doc->>'from' IN (\\n    '{{ env_var(\\"MONITORING_PHONE_DIGICEL\\", \\"\\") }}',\\n    '{{ env_var(\\"MONITORING_PHONE_FLOW\\", \\"\\") }}'\\n  )\\n{% if is_incremental() %}\\n  AND document_metadata.saved_timestamp >= {{ max_existing_timestamp('saved_timestamp') }}\\n{% endif %}", "unique_id": "model.cht_pipeline_base.monitoring_messages", "build_path": null, "created_at": 1758839283.1823354, "depends_on": {"nodes": ["source.cht_pipeline_base.couchdb.medic", "model.cht_pipeline_base.document_metadata"], "macros": ["macro.dbt.is_incremental"]}, "doc_blocks": [], "patch_path": "cht_pipeline_base://models/forms/forms.yml", "time_spine": null, "constraints": [], "description": "", "primary_key": [], "package_name": "cht_pipeline_base", "compiled_path": null, "relation_name": "\\"data\\".\\"v1\\".\\"monitoring_messages\\"", "resource_type": "model", "latest_version": null, "deprecation_date": null, "unrendered_config": {"tags": ["monitoring"], "indexes": [{"type": "hash", "columns": ["uuid"]}, {"columns": ["from_phone"]}, {"columns": ["message_timestamp"]}, {"columns": ["message_health"]}], "contract": {"enforced": true}, "post-hook": "\\n      DO $$\\n      DECLARE\\n        record_count INTEGER;\\n        phone_numbers TEXT;\\n      BEGIN\\n        SELECT COUNT(*) INTO record_count FROM {{ this }};\\n        SELECT STRING_AGG(DISTINCT from_phone, ', ') INTO phone_numbers \\n        FROM {{ this }};\\n        \\n        RAISE NOTICE '=== MONITORING MESSAGES PROCESSING COMPLETE ===';\\n        RAISE NOTICE 'Total records processed: %', record_count;\\n        RAISE NOTICE 'Phone numbers found: %', COALESCE(phone_numbers, 'NONE');\\n        RAISE NOTICE '==============================================';\\n      END $$;\\n    ", "unique_key": "uuid", "materialized": "incremental", "on_schema_change": "append_new_columns"}, "original_file_path": "models/forms/monitoring_messages.sql"}, "model.cht_pipeline_base.monitoring_config_test": {"fqn": ["cht_pipeline_base", "meta", "monitoring_config_test"], "docs": {"show": true, "node_color": null}, "meta": {}, "name": "monitoring_config_test", "path": "meta/monitoring_config_test.sql", "refs": [], "tags": [], "alias": "monitoring_config_test", "group": null, "access": "protected", "config": {"docs": {"show": true, "node_color": null}, "meta": {}, "tags": [], "alias": null, "begin": null, 