cro_sql": "{% macro run_query(sql) %}\\n  {% call statement(\\"run_query_statement\\", fetch_result=true, auto_begin=false) %}\\n    {{ sql }}\\n  {% endcall %}\\n\\n  {% do return(load_result(\\"run_query_statement\\").table) %}\\n{% endmacro %}", "unique_id": "macro.dbt.run_query", "created_at": 1758839280.8241968, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/etc/statement.sql", "supported_languages": null}, "macro.dbt.safe_cast": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "safe_cast", "path": "macros/utils/safe_cast.sql", "arguments": [], "macro_sql": "{% macro safe_cast(field, type) %}\\n  {{ return(adapter.dispatch('safe_cast', 'dbt') (field, type)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.safe_cast", "created_at": 1758839281.0544229, "depends_on": {"macros": ["macro.dbt.default__safe_cast"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/safe_cast.sql", "supported_languages": null}, "macro.dbt.statement": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "statement", "path": "macros/etc/statement.sql", "arguments": [], "macro_sql": "\\n{%- macro statement(name=None, fetch_result=False, auto_begin=True, language='sql') -%}\\n  {%- if execute: -%}\\n    {%- set compiled_code = caller() -%}\\n\\n    {%- if name == 'main' -%}\\n      {{ log('Writing runtime {} for node \\"{}\\"'.format(language, model['unique_id'])) }}\\n      {{ write(compiled_code) }}\\n    {%- endif -%}\\n    {%- if language == 'sql'-%}\\n      {%- set res, table = adapter.execute(compiled_code, auto_begin=auto_begin, fetch=fetch_result) -%}\\n    {%- elif language == 'python' -%}\\n      {%- set res = submit_python_job(model, compiled_code) -%}\\n      {#-- TODO: What should table be for python models? --#}\\n      {%- set table = None -%}\\n    {%- else -%}\\n      {% do exceptions.raise_compiler_error(\\"statement macro didn't get supported language\\") %}\\n    {%- endif -%}\\n\\n    {%- if name is not none -%}\\n      {{ store_result(name, response=res, agate_table=table) }}\\n    {%- endif -%}\\n\\n  {%- endif -%}\\n{%- endmacro %}", "unique_id": "macro.dbt.statement", "created_at": 1758839280.8224003, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/etc/statement.sql", "supported_languages": null}, "macro.dbt_date.date": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "date", "path": "macros/_utils/modules_datetime.sql", "arguments": [], "macro_sql": "{% macro date(year, month, day) %}\\n    {{ return(modules.datetime.date(year, month, day)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_date.date", "created_at": 1758839281.1302297, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/_utils/modules_datetime.sql", "supported_languages": null}, "macro.dbt.date_spine": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "date_spine", "path": "macros/utils/date_spine.sql", "arguments": [], "macro_sql": "{% macro date_spine(datepart, start_date, end_date) %}\\n    {{ return(adapter.dispatch('date_spine', 'dbt')(datepart, start_date, end_date)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.date_spine", "created_at": 1758839281.0530684, "depends_on": {"macros": ["macro.dbt.default__date_spine"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/date_spine.sql", "supported_languages": null}, "macro.dbt.date_trunc": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "date_trunc", "path": "macros/utils/date_trunc.sql", "arguments": [], "macro_sql": "{% macro date_trunc(datepart, date) -%}\\n  {{ return(ada