ted_languages": null}, "macro.dbt_date.week_end": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "week_end", "path": "macros/calendar_date/week_end.sql", "arguments": [], "macro_sql": "{%- macro week_end(date=None, tz=None) -%}\\n{%-set dt = date if date else dbt_date.today(tz) -%}\\n{{ adapter.dispatch('week_end', 'dbt_date') (dt) }}\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_date.week_end", "created_at": 1758839281.1438968, "depends_on": {"macros": ["macro.dbt_date.today", "macro.dbt_date.postgres__week_end"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_end.sql", "supported_languages": null}, "macro.dbt_utils.slugify": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "slugify", "path": "macros/jinja_helpers/slugify.sql", "arguments": [], "macro_sql": "{% macro slugify(string) %}\\n\\n{#- Lower case the string -#}\\n{% set string = string | lower %}\\n{#- Replace spaces and dashes with underscores -#}\\n{% set string = modules.re.sub('[ -]+', '_', string) %}\\n{#- Only take letters, numbers, and underscores -#}\\n{% set string = modules.re.sub('[^a-z0-9_]+', '', string) %}\\n{#- Prepends \\"_\\" if string begins with a number -#}\\n{% set string = modules.re.sub('^[0-9]', '_' + string[0], string) %}\\n\\n{{ return(string) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_utils.slugify", "created_at": 1758839281.3093622, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/jinja_helpers/slugify.sql", "supported_languages": null}, "macro.dbt_utils.unpivot": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "unpivot", "path": "macros/sql/unpivot.sql", "arguments": [], "macro_sql": "{% macro unpivot(relation=none, cast_to='varchar', exclude=none, remove=none, field_name='field_name', value_name='value') -%}\\n    {{ r