on, sql) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.create_view_as", "created_at": 1758839280.7967596, "depends_on": {"macros": ["macro.dbt.default__create_view_as"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/view/create.sql", "supported_languages": null}, "macro.dbt.dates_in_range": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "dates_in_range", "path": "macros/etc/datetime.sql", "arguments": [], "macro_sql": "{% macro dates_in_range(start_date_str, end_date_str=none, in_fmt=\\"%Y%m%d\\", out_fmt=\\"%Y%m%d\\") %}\\n    {% set end_date_str = start_date_str if end_date_str is none else end_date_str %}\\n\\n    {% set start_date = convert_datetime(start_date_str, in_fmt) %}\\n    {% set end_date = convert_datetime(end_date_str, in_fmt) %}\\n\\n    {% set day_count = (end_date - start_date).days %}\\n    {% if day_count < 0 %}\\n        {% set msg -%}\\n            Partition start date is after the end date ({{ start_date }}, {{ end_date }})\\n        {%- endset %}\\n\\n        {{ exceptions.raise_compiler_error(msg, model) }}\\n    {% endif %}\\n\\n    {% set date_list = [] %}\\n    {% for i in range(0, day_count + 1) %}\\n        {% set the_date = (modules.datetime.timedelta(days=i) + start_date) %}\\n        {% if not out_fmt %}\\n            {% set _ = date_list.append(the_date) %}\\n        {% else %}\\n            {% set _ = date_list.append(the_date.strftime(out_fmt)) %}\\n        {% endif %}\\n    {% endfor %}\\n\\n    {{ return(date_list) }}\\n{% endmacro %}", "unique_id": "macro.dbt.dates_in_range", "created_at": 1758839280.8278494, "depends_on": {"macros": ["macro.dbt.convert_datetime"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/etc/datetime.sql", "supported_languages": null}, "macro.dbt.default__right": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "defau