nts": [], "macro_sql": "{% macro default__concat(fields) -%}\\n    {{ fields|join(' || ') }}\\n{%- endmacro %}", "unique_id": "macro.dbt.default__concat", "created_at": 1758839281.0886161, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/concat.sql", "supported_languages": null}, "macro.dbt.default__equals": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__equals", "path": "macros/utils/equals.sql", "arguments": [], "macro_sql": "{% macro default__equals(expr1, expr2) -%}\\n{%- if adapter.behavior.enable_truthy_nulls_equals_macro.no_warn %}\\n    case when (({{ expr1 }} = {{ expr2 }}) or ({{ expr1 }} is null and {{ expr2 }} is null))\\n        then 0\\n        else 1\\n    end = 0\\n{%- else -%}\\n    ({{ expr1 }} = {{ expr2 }})\\n{%- endif %}\\n{% endmacro %}", "unique_id": "macro.dbt.default__equals", "created_at": 1758839281.096941, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/equals.sql", "supported_languages": null}, "macro.dbt.default__except": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__except", "path": "macros/utils/except.sql", "arguments": [], "macro_sql": "{% macro default__except() %}\\n\\n    except\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__except", "created_at": 1758839281.092091, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/except.sql", "supported_languages": null}, "macro.dbt.default__length": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__length", "path": "macros/utils/length.sql", "arguments": [], "macro_sql": "{% macro default__length(expression) %}\\n\\n    length(\\n        {{ expression }}\\n    )\\n\\n{%- endmacro -%}", "unique_id": "macro.dbt.default__length", "created_at": 1758839281.1066964, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/length.sql", "supported_languages": null}, "macro.dbt.generate_series": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "generate_series", "path": "macros/utils/generate_series.sql", "arguments": [], "macro_sql": "{% macro generate_series(upper_bound) %}\\n    {{ return(adapter.dispatch('generate_series', 'dbt')(upper_bound)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.generate_series", "created_at": 1758839281.0578542, "depends_on": {"macros": ["macro.dbt.default__generate_series"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/generate_series.sql", "supported_languages": null}, "macro.dbt.get_fixture_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_fixture_sql", "path": "macros/unit_test_sql/get_fixture_sql.sql", "arguments": [], "macro_sql": "{% macro get_fixture_sql(rows, column_name_to_data_types) %}\\n-- Fixture for {{ model.name }}\\n{% set default_row = {} %}\\n\\n{%- if not column_name_to_data_types -%}\\n{#-- Use defer_relation IFF it is available in the manifest and 'this' is missing from the database --#}\\n{%-   set this_or_defer_relation = defer_relation if (defer_relation and not load_relation(this)) else this -%}\\n{%-   set columns_in_relation = adapter.get_columns_in_relation(this_or_defer_relation) -%}\\n\\n{%-   set column_name_to_data_types = {} -%}\\n{%-   set column_name_to_quoted = {} -%}\\n{%-   for column in columns_in_relation -%}\\n\\n{#-- This needs to be a case-insensitive comparison --#}\\n{%-     do column_name_to_data_types.update({column.name|lower: column.data_type}) -%}\\n{%-     do column_name_to_quoted.update({column.name|lower: column.quoted}) -%}\\n{%-   endfor -%}\\n{%- endif -%}\\n\\n{%- if not column_name_to_data_types -%}\\n    {{ exceptions.raise_compiler_error(\\"Not able to get columns for unit test '\\" ~ model.name ~ \\"' from relation \\" ~ this ~ \\" because the relation doesn't exist\\") }}\\n{%- endif -%}\\n\\n{%- for column_name, column_type in column_name_to_data_types.items() -%}\\n    {%- do default_row.update({column_name: (safe_cast(\\"null\\", column_type) | trim )}) -%}\\n{%- endfor -%}\\n\\n{{ validate_fixture_rows(rows, row_number) }}\\n\\n{%- for row in rows -%}\\n{%-   set formatted_row = format_row(row, column_name_to_data_types) -%}\\n{%-   set default_row_copy = default_row.copy() -%}\\n{%-   do default_row_copy.update(formatted_row) -%}\\nselect\\n{%-   for column_name, column_value in default_row_copy.items() %} {{ column_value }} as {{ column_name_to_quoted[column_name] }}{% if not loop.last -%}, {%- endif %}\\n{%-   endfor %}\\n{%-   if not loop.last %}\\nunion all\\n{%    endif %}\\n{%- endfor -%}\\n\\n{%- if (rows | length) == 0 -%}\\n    select\\n    {%- for column_name, column_value in default_row.items() %} {{ column_value }} as {{ column_name_to_quoted[column_name] }}{% if not loop.last -%},{%- endif %}\\n    {%- endfor %}\\n    limit 0\\n{%- endif -%}\\n{% endmacro %}", "unique_id": "macro.dbt.get_fixture_sql", "created_at": 1758839280.986315, "depends_on": {"macros": ["macro.dbt.load_relation", "macro.dbt.safe_cast", "macro.dbt.validate_fixture_rows", "macro.dbt.format_row"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/unit_test_sql/get_fixture_sql.sql", "supported_languages": null}, "macro.dbt.get_replace_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_replace_sql", "path": "macros/relations/replace.sql", "arguments": [], "macro_sql": "{% macro get_replace_sql(existing_relation, target_relation, sql) %}\\n    {{- log('Applying REPLACE to: ' ~ existing_relation) -}}\\n    {{- adapter.dispatch('get_replace_sql', 'dbt')(existing_relation, target_relation, sql) -}}\\n{% endmacro %}", "unique_id": "macro.dbt.get_replace_sql", "created_at": 1758839280.778741, "depends_on": {"macros": ["macro.dbt.default__get_replace_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/replace.sql", "supported_languages": null}, "macro.dbt.partition_range": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "partition_range", "path": "macros/etc/datetime.sql", "arguments": [], "macro_sql": "{% macro partition_range(raw_partition_date, date_fmt='%Y%m%d') %}\\n    {% set partition_range = (raw_partition_date | string).split(\\",\\") %}\\n\\n    {% if (partition_range | length) == 1 %}\\n      {% set start_date = partition_range[0] %}\\n      {% set end_date = none %}\\n    {% elif (partition_range | length) == 2 %}\\n      {% set start_date = partition_range[0] %}\\n      {% set end_date = partition_range[1] %}\\n    {% else %}\\n      {{ exceptions.raise_compiler_error(\\"Invalid partition time. Expected format: {Start Date}[,{End Date}]. Got: \\" ~ raw_partition_date) }}\\n    {% endif %}\\n\\n    {{ return(dates_in_range(start_date, end_date, in_fmt=date_fmt)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.partition_range", "created_at": 1758839280.8295503, "depends_on": {"macros": ["macro.dbt.dates_in_range"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/etc/datetime.sql", "supported_languages": null}, "macro.dbt.rename_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "rename_relation", "path": "macros/relations/rename.sql", "arguments": [], "macro_sql": "{% macro rename_relation(from_relation, to_relation) -%}\\n  {{ return(adapter.dispatch('rename_relation', 'dbt')(from_relation, to_relation)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.rename_relation", "created_at": 1758839280.783154, "depen