d_df_function = kwargs.get(\\"dbt_load_df_function\\")\\n    return dbt_load_df_function(refs[key])\\n\\n{% endmacro %}", "unique_id": "macro.dbt.build_ref_function", "created_at": 1758839280.9785511, "depends_on": {"macros": ["macro.dbt.resolve_model_name"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/python_model/python.sql", "supported_languages": null}, "macro.dbt.default__any_value": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__any_value", "path": "macros/utils/any_value.sql", "arguments": [], "macro_sql": "{% macro default__any_value(expression) -%}\\n\\n    any_value({{ expression }})\\n\\n{%- endmacro %}", "unique_id": "macro.dbt.default__any_value", "created_at": 1758839281.0670588, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/any_value.sql", "supported_languages": null}, "macro.dbt.default__drop_view": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__drop_view", "path": "macros/relations/view/drop.sql", "arguments": [], "macro_sql": "{% macro default__drop_view(relation) -%}\\n    drop view if exists {{ relation.render() }} cascade\\n{%- endmacro %}", "unique_id": "macro.dbt.default__drop_view", "created_at": 1758839280.7983463, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/view/drop.sql", "supported_languages": null}, "macro.dbt.default__intersect": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__intersect", "path": "macros/utils/intersect.sql", "arguments": [], "macro_sql": "{% macro default__intersect() %}\\n\\n    intersect\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__intersect", "created_at": 1758839281.0621974, "depends_on": {"macros": []}, "patch_path": null, "descrip