e": "macro", "original_file_path": "macros/adapters/apply_grants.sql", "supported_languages": null}, "macro.dbt.check_schema_exists": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "check_schema_exists", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro check_schema_exists(information_schema, schema) -%}\\n  {{ return(adapter.dispatch('check_schema_exists', 'dbt')(information_schema, schema)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.check_schema_exists", "created_at": 1758839281.0062532, "depends_on": {"macros": ["macro.dbt_postgres.postgres__check_schema_exists"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt.default__date_spine": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__date_spine", "path": "macros/utils/date_spine.sql", "arguments": [], "macro_sql": "{% macro default__date_spine(datepart, start_date, end_date) %}\\n\\n\\n    {# call as follows:\\n\\n    date_spine(\\n        \\"day\\",\\n        \\"to_date('01/01/2016', 'mm/dd/yyyy')\\",\\n        \\"dbt.dateadd(week, 1, current_date)\\"\\n    ) #}\\n\\n\\n    with rawdata as (\\n\\n        {{dbt.generate_series(\\n            dbt.get_intervals_between(start_date, end_date, datepart)\\n        )}}\\n\\n    ),\\n\\n    all_periods as (\\n\\n        select (\\n            {{\\n                dbt.dateadd(\\n                    datepart,\\n                    \\"row_number() over (order by 1) - 1\\",\\n                    start_date\\n                )\\n            }}\\n        ) as date_{{datepart}}\\n        from rawdata\\n\\n    ),\\n\\n    filtered as (\\n\\n        select *\\n        from all_periods\\n        where date_{{datepart}} <= {{ end_date }}\\n\\n    )\\n\\n    select * from filtered\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__date_spine", "created_at": 1758839281.0538208, "depends_on": {"macros": ["macro.dbt.generate_series", "macro.dbt.get_intervals_between", "macro.dbt.dateadd"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/date_spine.sql", "supported_languages": null}, "macro.dbt.default__date_trunc": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__date_trunc", "path": "macros/utils/date_trunc.sql", "arguments": [], "macro_sql": "{% macro default__date_trunc(datepart, date) -%}\\n    date_trunc('{{datepart}}', {{date}})\\n{%- endmacro %}", "unique_id": "macro.dbt.default__date_trunc", "created_at": 1758839281.0701253, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/utils/date_trunc.sql", "supported_languages": null}, "macro.dbt.default__drop_table": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__drop_table", "path": "macros/relations/table/drop.sql", "arguments": [], "macro_sql": "{% macro default__drop_table(relation) -%}\\n    drop table if exists {{ relation.render() }} cascade\\n{%- endmacro %}", "unique_id": "macro.dbt.default__drop_table", "created_at": 1758839280.8058836, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/table/drop.sql", "supported_languages": null}, "macro.dbt.default__split_part": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__split_part", "path": "macros/utils/split_part.sql", "arguments": [], "macro_sql": "{% macro default__split_part(string_text, delimiter_text, part_number) %}\\n\\n    split_part(\\n        {{ string_text }},\\n        {{ delimiter_text }},\\n        {{ part_number }}\\n        )\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__split_part", "created_at": 1758839281.1046753, "depends_on": {"macros": []}, "patch