chema_changes_dict['new_target_types'] -%}\\n\\n     {% if add_to_target_arr | length > 0 or remove_from_target_arr | length > 0 %}\\n       {%- do alter_relation_add_remove_columns(target_relation, add_to_target_arr, remove_from_target_arr) -%}\\n     {% endif %}\\n\\n     {% if new_target_types != [] %}\\n       {% for ntt in new_target_types %}\\n         {% set column_name = ntt['column_name'] %}\\n         {% set new_type = ntt['new_type'] %}\\n         {% do alter_column_type(target_relation, column_name, new_type) %}\\n       {% endfor %}\\n     {% endif %}\\n\\n  {% endif %}\\n\\n  {% set schema_change_message %}\\n    In {{ target_relation }}:\\n        Schema change approach: {{ on_schema_change }}\\n        Columns added: {{ add_to_target_arr }}\\n        Columns removed: {{ remove_from_target_arr }}\\n        Data types changed: {{ new_target_types }}\\n  {% endset %}\\n\\n  {% do log(schema_change_message) %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.sync_column_schemas", "created_at": 1758839280.920916, "depends_on": {"macros": ["macro.dbt.alter_relation_add_remove_columns", "macro.dbt.alter_column_type"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/on_schema_change.sql", "supported_languages": null}, "macro.dbt_date.get_base_dates": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_base_dates", "path": "macros/get_base_dates.sql", "arguments": [], "macro_sql": "{% macro get_base_dates(start_date=None, end_date=None, n_dateparts=None, datepart=\\"day\\") %}\\n    {{ adapter.dispatch('get_base_dates', 'dbt_date') (start_date, end_date, n_dateparts, datepart) }}\\n{% endmacro %}", "unique_id": "macro.dbt_date.get_base_dates", "created_at": 1758839281.1113505, "depends_on": {"macros": ["macro.dbt_date.default__get_base_dates"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/get_base_dates.sql", "supported_languages": null}, "macro.dbt_date.iso_week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "iso_week_start", "path": "macros/calendar_date/iso_week_start.sql", "arguments": [], "macro_sql": "{%- macro iso_week_start(date=None, tz=None) -%}\\n{%-set dt = date if date else dbt_date.today(tz) -%}\\n{{ adapter.dispatch('iso_week_start', 'dbt_date') (dt) }}\\n{%- endmacro -%}\\n\\n", "unique_id": "macro.dbt_date.iso_week_start", "created_at": 1758839281.1505625, "depends_on": {"macros": ["macro.dbt_date.today", "macro.dbt_date.postgres__iso_week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/iso_week_start.sql", "supported_languages": null}, "macro.dbt_utils._is_ephemeral": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "_is_ephemeral", "path": "macros/jinja_helpers/_is_ephemeral.sql", "arguments": [], "macro_sql": "{% macro _is_ephemeral(obj, macro) %}\\n    {%- if obj.is_cte -%}\\n        {% set ephemeral_prefix = api.Relation.add_ephemeral_prefix('') %}\\n        {% if obj.name.startswith(ephemeral_prefix) %}\\n            {% set model_name = obj.name[(ephemeral_prefix|length):] %}\\n        {% else %}\\n            {% set model_name = obj.name %}\\n        {%- endif -%}\\n        {% set error_message %}\\nThe `{{ macro }}` macro cannot be used with ephemeral models, as it relies on the information schema.\\n\\n`{{ model_name }}` is an ephemeral model. Consider making it a view or table instead.\\n        {% endset %}\\n        {%- do exceptions.raise_compiler_error(error_message) -%}\\n    {%- endif -%}\\n{% endmacro %}", "unique_id": "macro.dbt_utils._is_ephemeral", "created_at": 1758839281.3047607, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/jinja_helpers/_is_ephemeral.sql", "supported_languages": null}, "macro.dbt_utils.default__star": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__star", "path": "macros/sql/star.sql", "arguments": [], "macro_sql": "{% macro default__star(from, relation_alias=False, except=[], prefix='', suffix='', quote_identifiers=True) -%}\\r\\n    {%- do dbt_utils._is_relation(from, 'star') -%}\\r\\n    {%- do dbt_utils._is_ephemeral(from, 'star') -%}\\r\\n\\r\\n    {#-- Prevent querying of db in parsing mode. This works because this macro does not create any new refs. #}\\r\\n    {%- if not execute -%}\\r\\n        {% do return('*') %}\\r\\n    {%- endif -%}\\r\\n\\r\\n    {% set cols = dbt_utils.get_filtered_columns_in_relation(from, except) %}\\r\\n\\r\\n    {%- if cols|length <= 0 -%}\\r\\n        {% if flags.WHICH == 'compile' %}\\r\\n            {% set response %}\\r\\n*\\r\\n/* No columns were returned. Maybe the relation doesn't exist yet \\r\\nor all columns were excluded. This star is only output during  \\r\\ndbt compile, and exists to keep SQLFluff happy. */\\r\\n            {% endset %}\\r\\n            {% do return(response) %}\\r\\n        {% else %}\\r\\n            {% do return(\\"/* no columns returned from star() macro */\\") %}\\r\\n        {% endif %}\\r\\n    {%- else -%}\\r\\n        {%- for col in cols %}\\r\\n            {%- if relation_alias %}{{ relation_alias }}.{% else %}{%- endif -%}\\r\\n                {%- if quote_identifiers -%}\\r\\n                    {{ adapter.quote(col)|trim }} {%- if prefix!='' or suffix!='' %} as {{ adapter.quote(prefix ~ col ~ suffix)|trim }} {%- endif -%}\\r\\n                {%- else -%}\\r\\n                    {{ col|trim }} {%- if prefix!='' or suffix!='' %} as {{ (prefix ~ col ~ suffix)|trim }} {%- endif -%}\\r\\n                {% endif %}\\r\\n            {%- if not loop.last %},{{ '\\\\n  ' }}{%- endif -%}\\r\\n        {%- endfor -%}\\r\\n    {% endif %}\\r\\n{%- endmacro %}", "unique_id": "macro.dbt_utils.default__star", "created_at": 1758839281.2168622, "depends_on": {"macros": ["macro.dbt_utils._is_relation", "macro.dbt_utils._is_ephemeral", "macro.dbt_utils.get_filtered_columns_in_relation"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/star.sql", "supported_languages": null}, "macro.dbt_utils.safe_subtract": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "safe_subtract", "path": "macros/sql/safe_subtract.sql", "arguments": [], "macro_sql": "{%- macro safe_subtract(field_list) -%}\\n    {{ return(adapter.dispatch('safe_subtract', 'dbt_utils')(field_list)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.safe_subtract", "created_at": 1758839281.2290542, "depends_on": {"macros": ["macro.dbt_utils.default__safe_subtract"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/safe_subtract.sql", "supported_languages": null}, "macro.dbt_utils.surrogate_key": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "surrogate_key", "path": "macros/sql/surrogate_key.sql", "arguments": [], "macro_sql": "{%- macro surrogate_key(field_list) -%}\\n    {% set frustrating_jinja_feature = varargs %}\\n    {{ return(adapter.dispatch('surrogate_key', 'dbt_utils')(field_list, *varargs)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.surrogate_key", "created_at": 1758839281.2279065, "depends_on": {"macros": ["macro.dbt_utils.default__surrogate_key"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/surrogate_key.sql", "supported_languages": null}, "macro.dbt_utils.test_equality": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "test_equality", "path": "macros/generic_tests/equality.sql", "arguments": [], "macro_sql": "{% test equality(model, compare_model, compare_columns=None) %}\\n  {{ ret