quote_identifiers=True,\\n               distinct=False) %}\\n  {% for value in values %}\\n    {{ agg }}(\\n      {% if distinct %} distinct {% endif %}\\n      case\\n      when {{ column }} {{ cmp }} '{{ dbt.escape_single_quotes(value) }}'\\n        then {{ then_value }}\\n      else {{ else_value }}\\n      end\\n    )\\n    {% if alias %}\\n      {% if quote_identifiers %}\\n            as {{ adapter.quote(prefix ~ value ~ suffix) }}\\n      {% else %}\\n        as {{ dbt_utils.slugify(prefix ~ value ~ suffix) }}\\n      {% endif %}\\n    {% endif %}\\n    {% if not loop.last %},{% endif %}\\n  {% endfor %}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__pivot", "created_at": 1758839281.2398741, "depends_on": {"macros": ["macro.dbt.escape_single_quotes", "macro.dbt_utils.slugify"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/pivot.sql", "supported_languages": null}, "macro.dbt.build_source_function": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "build_source_function", "path": "macros/python_model/python.sql", "arguments": [], "macro_sql": "{% macro build_source_function(model) %}\\n\\n    {%- set source_dict = {} -%}\\n    {%- for _source in model.sources -%}\\n        {%- set resolved = source(*_source) -%}\\n        {%- do source_dict.update({_source | join('.'): resolve_model_name(resolved)}) -%}\\n    {%- endfor -%}\\n\\ndef source(*args, dbt_load_df_function):\\n    sources = {{ source_dict | tojson }}\\n    key = '.'.join(args)\\n    return dbt_load_df_function(sources[key])\\n\\n{% endmacro %}", "unique_id": "macro.dbt.build_source_function", "created_at": 1758839280.979355, "depends_on": {"macros": ["macro.dbt.resolve_model_name"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/python_model/python.sql", "supported_languages": null}, "macro.dbt.check_time_data_types": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "check_time_data_types", "path": "macros/materializations/snapshots/helpers.sql", "arguments": [], "macro_sql": "{% macro check_time_data_types(sql) %}\\n  {% set dbt_updated_at_data_type = get_updated_at_column_data_type(sql) %}\\n  {% set snapshot_get_time_data_type = get_snapshot_get_time_data_type() %}\\n  {% if snapshot_get_time_data_type is not none and dbt_updated_at_data_type is not none and snapshot_get_time_data_type != dbt_updated_at_data_type %}\\n  {%   if exceptions.warn_snapshot_timestamp_data_types %}\\n  {{     exceptions.warn_snapshot_timestamp_data_types(snapshot_get_time_data_type, dbt_updated_at_data_type) }}\\n  {%   endif %}\\n  {% endif %}\\n{% endmacro %}", "unique_id": "macro.dbt.check_time_data_types", "created_at": 1758839280.8555682, "depends_on": {"macros": ["macro.dbt.get_updated_at_column_data_type", "macro.dbt.get_snapshot_get_time_data_type"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/helpers.sql", "supported_languages": null}, "macro.dbt.default__apply_grants": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__apply_grants", "path": "macros/adapters/apply_grants.sql", "arguments": [], "macro_sql": "{% macro default__apply_grants(relation, grant_config, should_revoke=True) %}\\n    {#-- If grant_config is {} or None, this is a no-op --#}\\n    {% if grant_config %}\\n        {% if should_revoke %}\\n            {#-- We think previous grants may have carried over --#}\\n            {#-- Show current grants and calculate diffs --#}\\n            {% set current_grants_table = run_query(get_show_grant_sql(relation)) %}\\n            {% set current_grants_dict = adapter.standardize_grants_dict(current_grants_table) %}\\n            {% set needs_granting = diff_of_two_dicts(grant_config, current_grants_dict) %}\\n            {% set needs_revoking = diff_of_two_dicts(current_grants_dict, grant_config) %}\\n            {% if not (needs_granting or needs_revoking) %}\\n                {{ log('On ' ~ relation.render() ~': All grants are in place, no revocation or granting needed.')}}\\n            {% endif %}\\n        {% else %}\\n            {#-- We don't think there's any chance of previous grants having carried over. --#}\\n            {#-- Jump straight to granting what the user has configured. --#}\\n            {% set needs_revoking = {} %}\\n            {% set needs_granting = grant_config %}\\n        {% endif %}\\n        {% if needs_granting or needs_revoking %}\\n            {% set revoke_statement_list = get_dcl_statement_list(relation, needs_revoking, get_revoke_sql) %}\\n            {% set grant_statement_list = get_dcl_statement_list(relation, needs_granting, get_grant_sql) %}\\n            {% set dcl_statement_list = revoke_statement_list + grant_statement_list %}\\n            {% if dcl_statement_list %}\\n                {{ call_dcl_statements(dcl_statement_list) }}\\n            {% endif %}\\n        {% endif %}\\n    {% endif %}\\n{% endmacro %}", "unique_id": "macro.dbt.default__apply_grants", "created_at": 1758839281.0342958, "depends_on": {"macros": ["macro.dbt.run_query", "macro.dbt.get_show_grant_sql", "macro.dbt.get_dcl_statement_list", "macro.dbt.call_dcl_statements"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/apply_grants.sql", "supported_languages": null}, "macro.dbt.default__array_append": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__array_append", "path": "macros/utils/array_append.sql", "arguments": [], "macro_sql": "{% macro default__array_append(array, new_element) -%}\\n    array_append({{ array }}, {{ new_element }})\\n{%- endmacro %}", "unique_id": "macro.dbt.default__array_append", "created_at": 1758839281.093397, "depends_on": {"macros": []}, "patch_path": null