depends_on": {"macros": ["macro.dbt_utils.default__nullcheck_table"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/nullcheck_table.sql", "supported_languages": null}, "macro.dbt_utils.union_relations": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "union_relations", "path": "macros/sql/union.sql", "arguments": [], "macro_sql": "{%- macro union_relations(relations, column_override=none, include=[], exclude=[], source_column_name='_dbt_source_relation', where=none) -%}\\n    {{ return(adapter.dispatch('union_relations', 'dbt_utils')(relations, column_override, include, exclude, source_column_name, where)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.union_relations", "created_at": 1758839281.2199948, "depends_on": {"macros": ["macro.dbt_utils.default__union_relations"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/union.sql", "supported_languages": null}, "macro.dbt.alter_relation_comment": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "alter_relation_comment", "path": "macros/adapters/persist_docs.sql", "arguments": [], "macro_sql": "{% macro alter_relation_comment(relation, relation_comment) -%}\\n  {{ return(adapter.dispatch('alter_relation_comment', 'dbt')(relation, relation_comment)) }}\\n{% endmacro %}", "unique_id": "macro.dbt.alter_relation_comment", "created_at": 1758839280.9936812, "depends_on": {"macros": ["macro.dbt_postgres.postgres__alter_relation_comment"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/persist_docs.sql", "supported_languages": null}, "macro.dbt.create_or_replace_view": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "create_or_replace_view", "path": "macros/relations/view/replace.sql", "arguments": [], "macro_sql": "{% macro create_or_replace_view() %}\\n  {%- set identifier = model['alias'] -%}\\n\\n  {%- set old_relation = adapter.get_relation(database=database, schema=schema, identifier=identifier) -%}\\n  {%- set exists_as_view = (old_relation is not none and old_relation.is_view) -%}\\n\\n  {%- set target_relation = api.Relation.create(\\n      identifier=identifier, schema=schema, database=database,\\n      type='view') -%}\\n  {% set grant_config = config.get('grants') %}\\n\\n  {{ run_hooks(pre_hooks) }}\\n\\n  -- If there's a table with the same name and we weren't told to full refresh,\\n  -- that's an error. If we were told to full refresh, drop it. This behavior differs\\n  -- for Snowflake and BigQuery, so multiple dispatch is used.\\n  {%- if old_relation is not none and old_relation.is_table -%}\\n    {{ handle_existing_table(should_full_refresh(), old_relation) }}\\n  {%- endif -%}\\n\\n  -- build model\\n  {% call statement('main') -%}\\n    {{ get_create_view_as_sql(target_relation, sql) }}\\n  {%- endcall %}\\n\\n  {% set should_revoke = should_revoke(exists_as_view, full_refresh_mode=True) %}\\n  {% do apply_grants(target_relation, grant_config, should_revoke=should_revoke) %}\\n\\n  {{ run_hooks(post_hooks) }}\\n\\n  {{ return({'relations': [target_relation]}) }}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.create_or_replace_view", "created_at": 1758839280.7937129, "depends_on": {"macros": ["macro.dbt.run_hooks", "macro.dbt.handle_existing_table", "macro.dbt.should_full_refresh", "macro.dbt.statement", "macro.dbt.get_create_view_as_sql", "macro.dbt.should_revoke", "macro.dbt.apply_grants"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/view/replace.sql", "supported_languages": null}, "macro.dbt.default__create_schema": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__create_schema", "path": "macros/adapters/schema.sql", "arguments": [], "macro_sql": "{% macro default__create_schema(relation) -%}\\n  {%- call statement('create_schema') -%}\\n    create schema if not exists {{ relation.without_identifier() }}\\n  {% endcall %}\\n{% endmacro %}", "unique_id": "macro.dbt.default__create_schema", "created_at": 1758839280.9914763, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/schema.sql", "supported_languages": null}, "macro.dbt.default__drop_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__drop_relation", "path": "macros/relations/drop.sql", "arguments": [], "macro_sql": "{% macro default__drop_relation(relation) -%}\\n    {% call statement('drop_relation', auto_begin=False) -%}\\n        {{ get_drop_sql(relation) }}\\n    {%- endcall %}\\n{% endmacro %}", "unique_id": "macro.dbt.default__drop_relation", "created_at": 1758839280.7897613, "depends_on": {"macros": ["macro.dbt.statement", "macro.dbt.get_drop_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/drop.sql", "supported_languages": null}, "macro.dbt.default__format_column": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__format_column", "path": "macros/relations/column/columns_spec_ddl.sql", "arguments": [], "macro_sql": "{% macro default__format_column(column) -%}\\n  {% set data_type = column.dtype %}\\n  {% set formatted = column.column.lower() ~ \\" \\" ~ data_type %}\\n  {{ return({'name': column.name, 'data_type': data_type, 'formatted': formatted}) }}\\n{%- endmacro -%}", "unique_id": "macro.dbt.default__format_column", "created_at": 1758839280.8135307, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/column/columns_spec_ddl.sql", "supported_languages": null}, "macro.dbt.default__get_grant_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_grant_sql", "path": "macros/adapters/apply_grants.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__get_grant_sql(relation, privilege, grantees) -%}\\n    grant {{ privilege }} on {{ relation.render() }} to {{ grantees | join(', ') }}\\n{%- endmacro -%}\\n\\n\\n", "unique_id": "macro.dbt.default__get_grant_sql", "created_at": 1758839281.0282307, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/apply_grants.sql", "supported_languages": null}, "macro.dbt.default__get_limit_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_limit_sql", "path": "macros/adapters/show.sql", "arguments": [], "macro_sql": "{% macro default__get_limit_sql(sql, limit) %}\\n  {{ sql }}\\n  {% if limit is not none %}\\n  limit {{ limit }}\\n  {%- endif -%}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_limit_sql", "created_at": 1758839281.0014486, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/show.sql", "supported_languages": null}, "macro.dbt.default__get_merge_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_merge_sql", "path": "macros/materializations/models/incremental/merge.sql", "arguments": [], "macro_sql": "{% macro default__get_merge_sql(target, source, unique_key, dest_columns, incremental_predicates=none) -%}\\n    {%- set predicates = [] if incremental_predicates is none else [] + incremental_predicates -%}\\n    {%- set dest_cols_csv = get_quoted_csv(dest_columns | map(attribute=\\"name\\")) -%}\\n    {%- set merge_update_columns = config.get('merge_update_columns') -%}\\n    {%- set merge_exclude_columns = config.get('merge_exclude_columns') -%}\\n    {%- set update_columns = get_merge_update_columns(merge_update_columns, merge_exclude_columns, dest_columns) -%}\\n    {%- set sql_header = config.get('sql_header', none) -%}\\n\\n    {% if unique_key %}\\n        {% if unique_key is sequence and unique_key is not mapping and unique_key is not string %}\\n            {% for key in unique_key %}\\n                {% set this_key_match %}\\n                    DBT_INTERNAL_SOURCE.{{ key }} = DBT_INTERNAL_DEST.{{ key }}\\n                {% endset %}\\n                {% do predicates.append(this_key_match) %}\\n            {% endfor %}\\n        {% else %}\\n            {% set source_unique_key = (\\"DBT_INTERNAL_SOURCE.\\" ~ unique_key) | trim %}\\n\\t    {% set target_unique_key = (\\"DBT_INTERNAL_DEST.\\" ~ unique_key) | trim %}\\n\\t    {% set unique_key_match = equals(source_unique_key, target_unique_key) | trim %}\\n            {% do predicates.append(unique_key_match) %}\\n        {% endif %}\\n    {% else %}\\n        {% do predicates.append('FALSE') %}\\n    {% endif %}\\n\\n    {{ sql_header if sql_header is not none }}\\n\\n    merge into {{ target }} as DBT_INTERNAL_DEST\\n        using {{ source }} as DBT_INTERNAL_SOURCE\\n        on {{\\"(\\" ~ predicates | join(\\") and (\\") ~ \\")\\"}}\\n\\n    {% if unique_key %}\\n    when matched then update set\\n        {% for column_name in update_columns -%}\\n            {{ column_name }} = DBT_INTERNAL_SOURCE.{{ column_name }}\\n            {%- if not loop.last %}, {%- endif %}\\n        {%- endfor %}\\n    {% endif %}\\n\\n    when not matched then insert\\n        ({{ dest_cols_csv }})\\n    values\\n        ({{ dest_cols_csv }})\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_merge_sql", "created_at": 1758839280.9038415, "depends_on": {"macros": ["macro.dbt.get_quoted_csv", "macro.dbt.get_merge_update_columns", "macro.dbt.equals"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/merge.sql", "supported_languages": null}, "macro.dbt.default__get_relations": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_relations", "path": "macros/adapters/metadata.sql", "arguments": [], "macro_sql": "{% macro default__get_relations() %}\\n  {{ exceptions.raise_not_implemented(\\n    'get_relations macro not implemented for adapter '+adapter.type()) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_relations", "created_at": 1758839281.008864, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/adapters/metadata.sql", "supported_languages": null}, "macro.dbt.default__load_csv_rows": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__load_csv_rows", "path": "macros/materializations/seeds/helpers.sql", "arguments": [], "macro_sql": "{% macro default__load_csv_rows(model, agate_table) %}\\n\\n  {% set batch_size = get_batch_size() %}\\n\\n  {% set cols_sql = get_seed_column_quoted_csv(model, agate_table.column_names) %}\\n  {% set bindings = [] %}\\n\\n  {% set statements = [] %}\\n\\n  {% for chunk in agate_table.rows | batch(batch_size) %}\\n      {% set bindings = [] %}\\n\\n      {% for row in chunk %}\\n          {% do bindings.extend(row) %}\\n      {% endfor %}\\n\\n      {% set sql %}\\n          insert into {{ this.render() }} ({{ cols_sql }}) values\\n          {% for row in chunk -%}\\n              ({%- for column in agate_table.column_names -%}\\n                  {{ get_binding_char() }}\\n                  {%- if not loop.last%},{%- endif %}\\n              {%- endfor -%})\\n              {%- if not loop.last%},{%- endif %}\\n          {%- endfor %}\\n      {% endset %}\\n\\n      {% do adapter.add_query(sql, bindings=bindings, abridge_sql_log=True) %}\\n\\n      {% if loop.index0 == 0 %}\\n          {% do statements.append(sql) %}\\n      {% endif %}\\n  {% endfor %}\\n\\n  {# Return