ta": {}, "name": "process_schema_changes", "path": "macros/materializations/models/incremental/on_schema_change.sql", "arguments": [], "macro_sql": "{% macro process_schema_changes(on_schema_change, source_relation, target_relation) %}\\n\\n    {% if on_schema_change == 'ignore' %}\\n\\n     {{ return({}) }}\\n\\n    {% else %}\\n\\n      {% set schema_changes_dict = check_for_schema_changes(source_relation, target_relation) %}\\n\\n      {% if schema_changes_dict['schema_changed'] %}\\n\\n        {% if on_schema_change == 'fail' %}\\n\\n          {% set fail_msg %}\\n              The source and target schemas on this incremental model are out of sync!\\n              They can be reconciled in several ways:\\n                - set the `on_schema_change` config to either append_new_columns or sync_all_columns, depending on your situation.\\n                - Re-run the incremental model with `full_refresh: True` to update the target schema.\\n                - update the schema manually and re-run the process.\\n\\n              Additional troubleshooting context:\\n                 Source columns not in target: {{ schema_changes_dict['source_not_in_target'] }}\\n                 Target columns not in source: {{ schema_changes_dict['target_not_in_source'] }}\\n                 New column types: {{ schema_changes_dict['new_target_types'] }}\\n          {% endset %}\\n\\n          {% do exceptions.raise_compiler_error(fail_msg) %}\\n\\n        {# -- unless we ignore, run the sync operation per the config #}\\n        {% else %}\\n\\n          {% do sync_column_schemas(on_schema_change, target_relation, schema_changes_dict) %}\\n\\n        {% endif %}\\n\\n      {% endif %}\\n\\n      {{ return(schema_changes_dict['source_columns']) }}\\n\\n    {% endif %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.process_schema_changes", "created_at": 1758839280.922539, "depends_on": {"macros": ["macro.dbt.check_for_schema_changes", "macro.dbt.sync_column_schemas"]}, "patch_path":