"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/materialized_view.sql", "supported_languages": null}, "macro.dbt.snapshot_check_strategy": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snapshot_check_strategy", "path": "macros/materializations/snapshots/strategies.sql", "arguments": [], "macro_sql": "{% macro snapshot_check_strategy(node, snapshotted_rel, current_rel, model_config, target_exists) %}\\n    {# The model_config parameter is no longer used, but is passed in anyway for compatibility. #}\\n    {% set check_cols_config = config.get('check_cols') %}\\n    {% set primary_key = config.get('unique_key') %}\\n    {% set hard_deletes = adapter.get_hard_deletes_behavior(config) %}\\n    {% set invalidate_hard_deletes = hard_deletes == 'invalidate' %}\\n    {% set updated_at = config.get('updated_at') or snapshot_get_time() %}\\n\\n    {% set column_added = false %}\\n\\n    {% set column_added, check_cols = snapshot_check_all_get_existing_columns(node, target_exists, check_cols_config) %}\\n\\n    {%- set row_changed_expr -%}\\n    (\\n    {%- if column_added -%}\\n        {{ get_true_sql() }}\\n    {%- else -%}\\n    {%- for col in check_cols -%}\\n        {{ snapshotted_rel }}.{{ col }} != {{ current_rel }}.{{ col }}\\n        or\\n        (\\n            (({{ snapshotted_rel }}.{{ col }} is null) and not ({{ current_rel }}.{{ col }} is null))\\n            or\\n            ((not {{ snapshotted_rel }}.{{ col }} is null) and ({{ current_rel }}.{{ col }} is null))\\n        )\\n        {%- if not loop.last %} or {% endif -%}\\n    {%- endfor -%}\\n    {%- endif -%}\\n    )\\n    {%- endset %}\\n\\n    {% set scd_args = api.Relation.scd_args(primary_key, updated_at) %}\\n    {% set scd_id_expr = snapshot_hash_arguments(scd_args) %}\\n\\n    {% do return({\\n        \\"unique_key\\": primary_key,\\n        \\"updated_at\\": updated_at,\\n        \\"row_changed\\": row_changed_expr,\\n        \\"scd_id\\": scd_id_expr,\\n        \\"invalidate_hard_deletes\\": invalidate_hard_deletes,\\n        \\"hard_deletes\\": hard_deletes\\n    }) %}\\n{% endmacro %}", "unique_id": "macro.dbt.snapshot_check_strategy", "created_at": 1758839280.879409, "depends_on": {"macros": ["macro.dbt.snapshot_get_time", "macro.dbt.snapshot_check_all_get_existing_columns", "macro.dbt.get_true_sql", "macro.dbt.snapshot_hash_arguments"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/strategies.sql", "supported_languages": null}, "macro.dbt.snapshot_hash_arguments": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snapshot_hash_arguments", "path": "macros/materializations/snapshots/strategies.sql", "arguments": [], "macro_sql": "{% macro snapshot_hash_arguments(args) -%}\\n  {{ adapter.dispatch('snapshot_hash_arguments', 'dbt')(args) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.snapshot_hash_arguments", "created_at": 1758839280.8702936, "depends_on": {"macros": ["macro.dbt.default__snapshot_hash_arguments"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/strategies.sql", "supported_languages": null}, "macro.dbt.snapshot_string_as_time": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "snapshot_string_as_time", "path": "macros/materializations/snapshots/strategies.sql", "arguments": [], "macro_sql": "{% macro snapshot_string_as_time(timestamp) -%}\\n    {{ adapter.dispatch('snapshot_string_as_time', 'dbt')(timestamp) }}\\n{%- endmacro %}", "unique_id": "macro.dbt.snapshot_string_as_time", "created_at": 1758839280.872988, "depends_on": {"macros": ["macro.dbt_postgres.postgres__snapshot_string_as_time"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/snapshots/strategies.sql", "supported_languages": null}, "macro.dbt_date.bigquery__day_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "bigquery__day_name", "path": "macros/calendar_date/day_name.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro bigquery__day_name(date, short) -%}\\n{%- set f = '%a' if short else '%A' -%}\\n    format_date('{{ f }}', cast({{ date }} as date))\\n{%- endmacro %}", "unique_id": "macro.dbt_date.bigquery__day_name", "created_at": 1758839281.1474571, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_name.sql", "supported_languages": null}, "macro.dbt_date.default__date_part": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__date_part", "path": "macros/calendar_date/date_part.sql", "arguments": [], "macro_sql": "{% macro default__date_part(datepart, date) -%}\\n    date_part('{{ datepart }}', {{  date }})\\n{%- endmacro %}", "unique_id": "macro.dbt_date.default__date_part", "created_at": 1758839281.1416833, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/date_part.sql", "supported_languages": null}, "macro.dbt_date.duckdb__month_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "duckdb__month_name", "path": "macros/calendar_date/month_name.sql", "arguments": [], "macro_sql": "\\n\\n\\n{%- macro duckdb__month_name(date, short) -%}\\n    {%- if short -%}\\n    substr(monthname({{ date }}), 1, 3)\\n    {%- else -%}\\n    monthname({{ date }})\\n    {%- endif -%}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.duckdb__month_name", "created_at": 1758839281.1639812, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/month_name.sql", "supported_languages": null}, "macro.dbt_date.duckdb__week_start": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "duckdb__week_start", "path": "macros/calendar_date/week_start.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro duckdb__week_start(date) -%}\\n{{ return(dbt_date.postgres__week_start(date)) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.duckdb__week_start", "created_at": 1758839281.176144, "depends_on": {"macros": ["macro.dbt_date.postgres__week_start"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/week_start.sql", "supported_languages": null}, "macro.dbt_date.from_unixtimestamp": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "from_unixtimestamp", "path": "macros/calendar_date/from_unixtimestamp.sql", "arguments": [], "macro_sql": "{%- macro from_unixtimestamp(epochs, format=\\"seconds\\") -%}\\n    {{ adapter.dispatch('from_unixtimestamp', 'dbt_date') (epochs, format) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.from_unixtimestamp", "created_at": 1758839281.1666577, "depends_on": {"macros": ["macro.dbt_date.postgres__from_unixtimestamp"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/from_unixtimestamp.sql", "supported_languages": null}, "macro.dbt_date.get_date_dimension": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_date_dimension", "path": "macros/get_date_dimension.sql", "arguments": [], "macro_sql": "{% macro get_date_dimension(start_date, end_date) %}\\n    {{ adapter.dispatch('get_date_dimension', 'dbt_date') (start_date, end_date) }}\\n{% endmacro %}", "unique_id": "macro.dbt_date.get_date_dimension", "created_at": 1758839281.1177492, "depends_on": {"macros": ["macro.dbt_date.postgres__get_date_dimension"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/get_date_dimension.sql", "supported_languages": null}, "macro.dbt_date.get_fiscal_periods": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_fiscal_periods", "path": "macros/fiscal_date/get_fiscal_periods.sql", "arguments": [], "macro_sql": "{% macro get_fiscal_periods(dates, year_end_month, week_start_day, shift_year=1) %}\\n{#\\nThis macro requires you to pass in a ref to a date dimension, created via\\ndbt_date.get_date_dimension()s\\n#}\\nwith fscl_year_dates_for_periods as (\\n    {{ dbt_date.get_fiscal_year_dates(dates, year_end_month, week_start_day, shift_year) }}\\n),\\nfscl_year_w13 as (\\n\\n    select\\n        f.*,\\n        -- We count the weeks in a 13 week period\\n        -- and separate the 4-5-4 week sequences\\n        mod(cast(\\n            (f.fiscal_week_of_year-1) as {{ dbt.type_int() }}\\n            ), 13) as w13_number,\\n        -- Chop weeks into 13 week merch quarters\\n        cast(\\n            least(\\n                floor((f.fiscal_week_of_year-1)/13.0)\\n                , 3)\\n            as {{ dbt.type_int() }}) as quarter_number\\n    from\\n        fscl_year_dates_for_periods f\\n\\n),\\nfscl_periods as (\\n\\n    select\\n        f.date_day,\\n        f.fiscal_year_number,\\n        f.week_start_date,\\n        f.week_end_date,\\n        f.fiscal_week_of_year,\\n        case\\n            -- we move week 53 into the 3rd period of the quarter\\n            when f.fiscal_week_of_year = 53 then 3\\n            when f.w13_number between 0 and 3 then 1\\n            when f.w13_number between 4 and 8 then 2\\n            when f.w13_number between 9 and 12 then 3\\n        end as period_of_quarter,\\n        f.quarter_number\\n    from\\n        fscl_year_w13 f\\n\\n),\\nfscl_periods_quarters as (\\n\\n    select\\n        f.*,\\n        cast((\\n            (f.quarter_number * 3) + f.period_of_quarter\\n         ) as {{ dbt.type_int() }}) as fiscal_period_number\\n    from\\n        fscl_periods f\\n\\n)\\nselect\\n    date_day,\\n    fiscal_year_number,\\n    week_start_date,\\n    week_end_date,\\n    fiscal_week_of_year,\\n    dense_rank() over(partition by fiscal_period_number order by fiscal_week_of_year) as fiscal_week_of_period,\\n    fiscal_period_number,\\n    quarter_number+1 as fiscal_quarter_number,\\n    period_of_quarter as fiscal_period_of_quarter\\nfrom\\n    fscl_periods_quarters\\norder by 1,2\\n{% endmacro %}", "unique_id": "macro.dbt_date.get_fiscal_periods", "created_at": 1758839281.1356478, "depends_on": {"macros": ["macro.dbt_date.get_fiscal_year_dates", "macro.dbt.type_int"]}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/fiscal_date/get_fiscal_periods.sql", "supported_languages": null}, "macro.dbt_date.postgres__day_name": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__day_name", "path": "macros/calendar_date/day_name.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro postgres__day_name(date, short) -%}\\n{# FM = Fill mode, which suppresses padding blanks #}\\n{%- set f = 'FMDy' if short else 'FMDay' -%}\\n    to_char({{ date }}, '{{ f }}')\\n{%- endmacro %}", "unique_id": "macro.dbt_date.postgres__day_name", "created_at": 1758839281.1478534, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_date", "resource_type": "macro", "original_file_path": "macros/calendar_date/day_name.sql", "supported_languages": null}, "macro.dbt_date.postgres__week_end": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__week_end", "path": "macros/calendar_date/week_end.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro postgres__week_end(date) -%}\\n{%- set dt = dbt_date.week_start(date) -%}\\n{{ dbt_date.n_days_away(6, dt) }}\\n{%- endmacro %}", "unique_id": "macro.dbt_date.postgres__week_end", "created_at": 175883928