) %}\\n    {{ log(dbt_utils.pretty_log_format(message), info=True) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__log_info", "created_at": 1758839281.3055923, "depends_on": {"macros": ["macro.dbt_utils.pretty_log_format"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/jinja_helpers/log_info.sql", "supported_languages": null}, "macro.dbt_utils.default__safe_add": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__safe_add", "path": "macros/sql/safe_add.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__safe_add(field_list) -%}\\n\\n{%- if field_list is not iterable or field_list is string or field_list is mapping -%}\\n\\n{%- set error_message = '\\nWarning: the `safe_add` macro now takes a single list argument instead of \\\\\\nstring arguments. The {}.{} model triggered this warning. \\\\\\n'.format(model.package_name, model.name) -%}\\n\\n{%- do exceptions.warn(error_message) -%}\\n\\n{%- endif -%}\\n\\n{% set fields = [] %}\\n\\n{%- for field in field_list -%}\\n\\n    {% do fields.append(\\"coalesce(\\" ~ field ~ \\", 0)\\") %}\\n\\n{%- endfor -%}\\n\\n{{ fields|join(' +\\\\n  ') }}\\n\\n{%- endmacro -%}", "unique_id": "macro.dbt_utils.default__safe_add", "created_at": 1758839281.2017586, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/safe_add.sql", "supported_languages": null}, "macro.dbt_utils.get_column_values": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "get_column_values", "path": "macros/sql/get_column_values.sql", "arguments": [], "macro_sql": "{% macro get_column_values(table, column, order_by='count(*) desc', max_records=none, default=none, where=none) -%}\\n    {{ return(adapter.dispatch('get_column_values', 'dbt_utils')(table, column, order_by, max_records, default, where)) }}\\n{% endmacro %}",