e": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/haversine_distance.sql", "supported_languages": null}, "macro.dbt_utils.haversine_distance": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "haversine_distance", "path": "macros/sql/haversine_distance.sql", "arguments": [], "macro_sql": "{% macro haversine_distance(lat1, lon1, lat2, lon2, unit='mi') -%}\\n    {{ return(adapter.dispatch('haversine_distance', 'dbt_utils')(lat1,lon1,lat2,lon2,unit)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_utils.haversine_distance", "created_at": 1758839281.2434065, "depends_on": {"macros": ["macro.dbt_utils.default__haversine_distance"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/haversine_distance.sql", "supported_languages": null}, "macro.dbt.assert_columns_equivalent": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "assert_columns_equivalent", "path": "macros/relations/column/columns_spec_ddl.sql", "arguments": [], "macro_sql": "{% macro assert_columns_equivalent(sql) %}\\n\\n  {#-- First ensure the user has defined 'columns' in yaml specification --#}\\n  {%- set user_defined_columns = model['columns'] -%}\\n  {%- if not user_defined_columns -%}\\n      {{ exceptions.raise_contract_error([], []) }}\\n  {%- endif -%}\\n\\n  {#-- Obtain the column schema provided by sql file. #}\\n  {%- set sql_file_provided_columns = get_column_schema_from_query(sql, config.get('sql_header', none)) -%}\\n  {#--Obtain the column schema provided by the schema file by generating an 'empty schema' query from the model's columns. #}\\n  {%- set schema_file_provided_columns = get_column_schema_from_query(get_empty_schema_sql(user_defined_columns)) -%}\\n\\n  {#-- create dictionaries with name and formatted data type and strings for exception #}\\n  {%- set sql_columns = format_columns(sql_file_provided_columns) -%}\\n  {%- set yaml_columns = format_columns(schema_file_provided_columns)  -%}\\n\\n  {%- if sql_columns|length != yaml_columns|length -%}\\n    {%- do exceptions.raise_contract_error(yaml_columns, sql_columns) -%}\\n  {%- endif -%}\\n\\n  {%- for sql_col in sql_columns -%}\\n    {%- set yaml_col = [] -%}\\n    {%- for this_col in yaml_columns -%}\\n      {%- if this_col['name'] == sql_col['name'] -%}\\n        {%- do yaml_col.append(this_col) -%}\\n        {%- break -%}\\n      {%- endif -%}\\n    {%- endfor -%}\\n    {%- if not yaml_col -%}\\n      {#-- Column with name not found in yaml #}\\n      {%- do exceptions.raise_contract_error(yaml_columns, sql_columns) -%}\\n    {%- endif -%}\\n    {%- if sql_col['formatted'] != yaml_col[0]['formatted'] -%}\\n      {#-- Column data types don't match #}\\n      {%- do exceptions.raise_contract_error(yaml_columns, sql_columns) -%}\\n    {%- endif -%}\\n  {%- endfor -%}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.assert_columns_equivalent", "created_at": 1758839280.8121035, "depends_on": {"macros": ["macro.dbt.get_column_schema_from_query", "macro.dbt.get_empty_schema_sql", "macro.dbt.format_columns"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/column/columns_spec_ddl.sql", "supported_languages": null}, "macro.dbt.default__create_csv_table": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__create_csv_table", "path": "macros/materializations/seeds/helpers.sql", "arguments": [], "macro_sql": "{% macro default__create_csv_table(model, agate_table) %}\\n  {%- set column_override = model['config'].get('column_types', {}) -%}\\n  {%- set quote_seed_column = model['config'].get('quote_columns', None) -%}\\n\\n  {% set sql %}\\n    create table {{ this.render() }} (\\n        {%- for col_name in agate_table.column_names -%}\\n            {%- set inferred_type = adapter.convert_type(agate_table, loop.index0) -%}\\n            {%- set type = column_override.get(col_name, inferred_type) -%}\\n            {%- set column_name = (col_name | string) -%}\\n            {{ adapter.quote_seed_column(column_name, quote_seed_column) }} {{ type }} {%- if not loop.last -%}, {%- endif -%}\\n        {%- endfor -%}\\n    )\\n  {% endset %}\\n\\n  {% call statement('_') -%}\\n    {{ sql }}\\n  {%- endcall %}\\n\\n  {{ return(sql) }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__create_csv_table", "created_at": 1758839280.9638553, "depends_on": {"macros": ["macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/seeds/helpers.sql", "supported_languages": null}, "macro.dbt.default__get_binding_char": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_binding_char", "path": "macros/materializations/seeds/helpers.sql", "arguments": [], "macro_sql": "{% macro default__get_binding_char() %}\\n  {{ return('%s') }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_binding_char", "created_at": 1758839280.9664254, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/seeds/helpers.sql", "supported_languages": null}, "macro.dbt.default__get_column_names": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_column_names", "path": "macros/relations/table/create.sql", "arguments": [], "macro_sql": "{% macro default__get_column_names() %}\\n  {#- loop through user_provided_columns to get column names -#}\\n    {%- set user_provided_columns = model['columns'] -%}\\n    {%- for i in user_provided_columns %}\\n      {%- set col = user_provided_columns[i] -%}\\n      {%- set col_name = adapter.quote(col['name']) if col.get('quote') else col['name'] -%}\\n      {{ col_name }}{{ \\", \\" if not loop.last }}\\n    {%- endfor -%}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_