r, schema=schema, database=database,\\n        type='view') -%}\\n\\n  {{ run_hooks(pre_hooks) }}\\n\\n  {% call statement('main') -%}\\n    {{ sql }}\\n  {%- endcall %}\\n\\n  {{ adapter.commit() }}\\n\\n  {{ return({'relations': [target_relation]}) }}\\n\\n{% endmaterialization %}", "unique_id": "macro.cht_pipeline_base.materialization_raw_sql_default", "created_at": 1758839281.3104353, "depends_on": {"macros": ["macro.dbt.run_hooks", "macro.dbt.statement"]}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/function.sql", "supported_languages": ["sql"]}, "macro.dbt.default__get_incremental_insert_overwrite_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_incremental_insert_overwrite_sql", "path": "macros/materializations/models/incremental/strategies.sql", "arguments": [], "macro_sql": "{% macro default__get_incremental_insert_overwrite_sql(arg_dict) %}\\n\\n  {% do return(get_insert_overwrite_merge_sql(arg_dict[\\"target_relation\\"], arg_dict[\\"temp_relation\\"], arg_dict[\\"dest_columns\\"], arg_dict[\\"incremental_predicates\\"])) %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_incremental_insert_overwrite_sql", "created_at": 1758839280.926811, "depends_on": {"macros": ["macro.dbt.get_insert_overwrite_merge_sql"]}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/materializations/models/incremental/strategies.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__describe_materialized_view": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__describe_materialized_view", "path": "macros/relations/materialized_view/describe.sql", "arguments": [], "macro_sql": "{% macro postgres__describe_materialized_view(relation) %}\\n    -- for now just get the indexes, we don't need the name or the query yet\\n    {% set _indexes = run_query(get_show_indexes_sql(relation)) %}\\n    {% do return({'indexes': _indexes}) %}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__describe_materialized_view", "created_at": 1758839280.7575586, "depends_on": {"macros": ["macro.dbt.run_query", "macro.dbt.get_show_indexes_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/relations/materialized_view/describe.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__make_intermediate_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__make_intermediate_relation", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__make_intermediate_relation(base_relation, suffix) %}\\n    {{ return(postgres__make_relation_with_suffix(base_relation, suffix, dstring=False)) }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__make_intermediate_relation", "created_at": 1758839280.7407696, "depends_on": {"macros": ["macro.dbt_postgres.postgres__make_relation_with_suffix"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/adapters.sql", "supported_languages": null}, "macro.dbt_utils.default__test_mutually_exclusive_ranges": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__test_mutually_exclusive_ranges", "path": "macros/generic_tests/mutually_exclusive_ranges.sql", "arguments": [], "macro_sql": "{% macro default__test_mutually_exclusive_ranges(model, lower_bound_column, upper_bound_column, partition_by=None, gaps='allowed', zero_length_range_allowed=False) %}\\n{% if gaps == 'not_allowed' %}\\n    {% set allow_gaps_operator='=' %}\\n    {% set allow_gaps_operator_in_words='equal_to' %}\\n{% elif gaps == 'allowed' %}\\n    {% set allow_gaps_operator='<=' %}\\n    {% set allow_gaps_operator_in_words='less_than_or_equal_to' %}\\n{% elif gaps == 'required' %}\\n    {% set allow_gaps_operator='<' %}\\n    {% set allow_gaps_operator_in_words='less_than' %}\\n{% else %}\\n    {{ exceptions.raise_compiler_error(\\n        \\"`gaps` argument for mutually_exclusive_ranges test must be one of ['not_allowed', 'allowed', 'required'] Got: '\\" ~ gaps ~\\"'.'\\"\\n    ) }}\\n{% endif %}\\n{% if not zero_length_range_allowed %}\\n    {% set allow_zero_length_operator='<' %}\\n    {% set allow_zero_length_operator_in_words='less_than' %}\\n{% elif zero_length_range_allowed %}\\n    {% set allow_zero_length_operator='<=' %}\\n    {% set allow_zero_length_operator_in_words='less_than_or_equal_to' %}\\n{% else %}\\n    {{ exceptions.raise_compiler_error(\\n        \\"`zero_length_range_allowed` argument for mutually_exclusive_ranges test must be one of [true, false] Got: '\\" ~ zero_length_range_allowed ~\\"'.'\\"\\n    ) }}\\n{% endif %}\\n\\n{% set partition_clause=\\"partition by \\" ~ partition_by if partition_by else '' %}\\n\\nwith window_functions as (\\n\\n    select\\n        {% if partition_by %}\\n        {{ partition_by }} as partition_by_col,\\n        {% endif %}\\n        {{ lower_bound_column }} as lower_bound,\\n        {{ upper_bound_column }} as upper_bound,\\n\\n        lead({{ lower_bound_column }}) over (\\n            {{ partition_clause }}\\n            order by {{ lower_bound_column }}, {{ upper_bound_column }}\\n        ) as next_lower_bound,\\n\\n        row_number() over (\\n            {{ partition_clause }}\\n            order by {{ lower_bound_column }} desc, {{ upper_bound_column }} desc\\n        ) = 1 as is_last_record\\n\\n    from {{ model }}\\n\\n),\\n\\ncalc as (\\n    -- We want to return records where one of our assumptions fails, so we'll use\\n    -- the `not` function with `and` statements so we can write our assumptions more cleanly\\n    select\\n        *,\\n\\n        -- For each record: lower_bound should be < upper_bound.\\n        -- Coalesce it to return an error on the null case (implicit assumption\\n        -- these columns are not_null)\\n        coalesce(\\n            lower_bound {{ allow_zero_length_operator }} upper_bound,\\n            false\\n        ) as lower_bound_{{ allow_zero_length_operator_in_words }}_upper_bound,\\n\\n        -- For each record: upper_bound {{ allow_gaps_operator }} the next lower_bound.\\n        -- Coalesce it to handle null cases for the last record.\\n        coalesce(\\n            upper_bound {{ allow_gaps_operator }} next_lower_bound,\\n            is_last_record,\\n            false\\n        ) as upper_bound_{{ allow_gaps_operator_in_words }}_next_lower_bound\\n\\n    from window_functions\\n\\n),\\n\\nvalidation_errors as (\\n\\n    select\\n        *\\n    from calc\\n\\n    where not(\\n        -- THE FOLLOWING SHOULD BE TRUE --\\n        lower_bound_{{ allow_zero_length_operator_in_words }}_upper_bound\\n        and upper_bound_{{ allow_gaps_operator_in_words }}_next_lower_bound\\n    )\\n)\\n\\nselect * from validation_errors\\n{% endmacro %}", "unique_id": "macro.dbt_utils.default__test_mutually_exclusive_ranges", "created_at": 1758839281.2727106, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/generic_tests/mutually_exclusive_ranges.sql", "supported_languages": null}, "macro.cht_pipeline_base._two_column_matrix_to_list_dicts": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "_two_column_matrix_to_list_dicts", "path": "macros/max_existing_multiro_macros.sql", "arguments": [], "macro_sql": "{% macro _two_column_matrix_to_list_dicts(agate_rows, col1_name, col2_name) %}\\n{#\\n    Converts an agate.Table.rows to a list of dicts\\n    Params: an agate.Table.rows and names of the two columns\\n    Return: list of dicts with keys col1_name and col2_name\\n #}\\n    {%- set list_dicts = [] -%}\\n    {%- for row in agate_rows -%}\\n        {{- list_dicts.append( {col1_name: row[0], col2_name : row[1] } ) -}}\\n    {%- endfor -%}\\n    {% for dict_val in list_dicts %}\\n        {{ log(dict_val) }}\\n    {%- endfor -%}\\n    {{ return(list_dicts)}}\\n{% endmacro %}", "unique_id": "macro.cht_pipeline_base._two_column_matrix_to_list_dicts", "created_at": 1758839281.322442, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "cht_pipeline_base", "resource_type": "macro", "original_file_path": "macros/max_existing_multiro_macros.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_incremental_default_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_incremental_default_sql", "path": "macros/materializations/incremental_strategies.sql", "arguments": [], "macro_sql": "{% macro postgres__get_incremental_default_sql(arg_dict) %}\\n\\n  {% if arg_dict[\\"unique_key\\"] %}\\n    {% do return(get_incremental_delete_insert_sql(arg_dict)) %}\\n  {% else %}\\n    {% do return(get_incremental_append_sql(arg_dict)) %}\\n  {% endif %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_incremental_default_sql", "created_at": 1758839280.7596414, "depends_on": {"macros": ["macro.dbt.get_incremental_delete_insert_sql", "macro.dbt.get_incremental_append_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/materializations/incremental_strategies.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__current_timestamp_backcompat": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__current_timestamp_backcompat", "path": "macros/timestamps.sql", "arguments": [], "macro_sql": "{% macro postgres__current_timestamp_backcompat() %}\\n    current_timestamp::{{ type_timestamp() }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__current_timestamp_backcompat", "created_at": 1758839280.749893, "depends_on": {"macros": ["macro.dbt.type_timestamp"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/timestamps.sql", "supported_languages": null}, "macro.dbt_utils.default__get_filtered_columns_in_relation": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_filtered_columns_in_relation", "path": "macros/sql/get_filtered_columns_in_relation.sql", "arguments": [], "macro_sql": "{% macro default__get_filtered_columns_in_relation(from, except=[]) -%}\\n    {%- do dbt_utils._is_relation(from, 'get_filtered_columns_in_relation') -%}\\n    {%- do dbt_utils._is_ephemeral(from, 'get_filtered_columns_in_relation') -%}\\n\\n    {# -- Prevent querying of db in parsing mode. This works because this macro does not create any new refs. #}\\n    {%- if not execute -%}\\n        {{ return('') }}\\n    {% endif %}\\n\\n    {%- set include_cols = [] %}\\n    {%- set cols = adapter.get_columns_in_relation(from) -%}\\n    {%- set except = except | map(\\"lower\\") | list %}\\n    {%- for col in cols -%}\\n        {%- if col.column|lower not in except -%}\\n            {% do include_cols.append(col.column) %}\\n        {%- endif %}\\n    {%- endfor %}\\n\\n    {{ return(include_cols) }}\\n\\n{%- endmacro %}", "unique_id": "macro.dbt_utils.default__get_filtered_columns_in_relation", "created_at": 1758839281.2000885, "depends_on": {"macros": ["macro.dbt_utils._is_relation", "macro.dbt_utils._is_ephemeral"]}, "patch_path": null, "description": "", "package_name": "dbt_utils", "resource_type": "macro", "original_file_path": "macros/sql/get_filtered_columns_in_relation.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__get_incremental_microbatch_sql": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__get_incremental_microbatch_sql", "path": "macros/materializations/incremental_strategies.sql", "arguments": [], "macro_sql": "{% macro postgres__get_incremental_microbatch_sql(arg_dict) %}\\n\\n  {% if arg_dict[\\"unique_key\\"] %}\\n    {% do return(adapter.dispatch('get_incremental_merge_sql', 'dbt')(arg_dict)) %}\\n  {% else %}\\n    {{ exceptions.raise_compiler_error(\\"dbt-postgres 'microbatch' requires a `unique_key` config\\") }}\\n  {% endif %}\\n\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_incremental_microbatch_sql", "created_at": 1758839280.7606876, "depends_on": {"macros": ["macro.dbt.get_incremental_merge_sql", "macro.dbt.default__get_incremental_merge_sql"]}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/materializations/incremental_strategies.sql", "supported_languages": null}, "macro.dbt_postgres.postgres__list_relations_without_caching": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "postgres__list_relations_without_caching", "path": "macros/adapters.sql", "arguments": [], "macro_sql": "{% macro postgres__list_relations_without_caching(schema_relation) %}\\n  {% call statement('list_relations_without_caching', fetch_result=True) -%}\\n    select\\n      '{{ schema_relation.database }}' as database,\\n      tablename as name,\\n      schemaname as schema,\\n      'table' as type\\n    from pg_tables\\n    where schemaname ilike '{{ schema_relation.schema }}'\\n    union all\\n    select\\n      '{{ schema_relation.database }}' as database,\\n      viewname as name,\\n      schemaname as schema,\\n      'view' as type\\n    from pg_views\\n    where schemaname ilike '{{ schema_relation.schema }}'\\n    union all\\n    select\\n      '{{ schema_relation.database }}' as database,\\n      matviewname as name,\\n      schemaname as schema,\\n      'materialized_view' as type\\n    from pg_matviews\\n    where schemaname ilike '{{ schema_relation.schema }}'\\n  {% endcall %}\\n  {{ return(load_result('list_relations_without_caching').table) }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__list_relations_without_caching", "