ew/rename.sql", "arguments": [], "macro_sql": "{% macro postgres__get_rename_materialized_view_sql(relation, new_name) %}\\n    alter materialized view {{ relation }} rename to {{ new_name }}\\n{% endmacro %}", "unique_id": "macro.dbt_postgres.postgres__get_rename_materialized_view_sql", "created_at": 1758839280.7540267, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt_postgres", "resource_type": "macro", "original_file_path": "macros/relations/materialized_view/rename.sql", "supported_languages": null}, "macro.dbt.default__get_materialized_view_configuration_changes": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__get_materialized_view_configuration_changes", "path": "macros/relations/materialized_view/alter.sql", "arguments": [], "macro_sql": "{% macro default__get_materialized_view_configuration_changes(existing_relation, new_config) %}\\n    {{ exceptions.raise_compiler_error(\\"Materialized views have not been implemented for this adapter.\\") }}\\n{% endmacro %}", "unique_id": "macro.dbt.default__get_materialized_view_configuration_changes", "created_at": 1758839280.8174136, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "macro", "original_file_path": "macros/relations/materialized_view/alter.sql", "supported_languages": null}, "macro.dbt.default__support_multiple_grantees_per_dcl_statement": {"docs": {"show": true, "node_color": null}, "meta": {}, "name": "default__support_multiple_grantees_per_dcl_statement", "path": "macros/adapters/apply_grants.sql", "arguments": [], "macro_sql": "\\n\\n{%- macro default__support_multiple_grantees_per_dcl_statement() -%}\\n    {{ return(True) }}\\n{%- endmacro -%}\\n\\n\\n", "unique_id": "macro.dbt.default__support_multiple_grantees_per_dcl_statement", "created_at": 1758839281.0260887, "depends_on": {"macros": []}, "patch_path": null, "description": "", "package_name": "dbt", "resource_type": "