2025-09-25 22:27:43.893	_design/medic-client	f	{"_id": "_design/medic-client", "_rev": "4-bef52e212bd84817154d46b5c17a2881", "views": {"doc_by_type": {"map": "function(doc) {\\n  if (doc.type === 'translations') {\\n    emit([ 'translations', doc.enabled ], {\\n      code: doc.code,\\n      name: doc.name\\n    });\\n    return;\\n  }\\n  emit([ doc.type ]);\\n}"}, "visits_by_date": {"map": "function(doc) {\\n  if (doc.type === 'data_record' &&\\n      doc.form &&\\n      doc.fields &&\\n      doc.fields.visited_contact_uuid) {\\n\\n    var visited_date = doc.fields.visited_date ? Date.parse(doc.fields.visited_date) : doc.reported_date;\\n\\n    // Is a visit report about a family\\n    emit(visited_date, doc.fields.visited_contact_uuid);\\n    emit([doc.fields.visited_contact_uuid, visited_date]);\\n  }\\n}"}, "reports_by_date": {"map": "function(doc) {\\n  if (doc.type === 'data_record' && doc.form) {\\n    emit([doc.reported_date], doc.reported_date);\\n  }\\n}"}, "reports_by_form": {"map": "function(doc) {\\n  if (doc.type === 'data_record' && doc.form) {\\n    emit([doc.form], doc.reported_date);\\n  }\\n}", "reduce": "function() {\\n  return true;\\n}"}, "contacts_by_type": {"map": "function(doc) {\\n  var types = [ 'district_hospital', 'health_center', 'clinic', 'person' ];\\n  var idx;\\n  var type;\\n  if (doc.type === 'contact') {\\n    type = doc.contact_type;\\n    idx = types.indexOf(type);\\n    if (idx === -1) {\\n      idx = type;\\n    }\\n  } else {\\n    type = doc.type;\\n    idx = types.indexOf(type);\\n  }\\n  if (idx !== -1) {\\n    var dead = !!doc.date_of_death;\\n    var muted = !!doc.muted;\\n    var order = dead + ' ' + muted + ' ' + idx + ' ' + (doc.name && doc.name.toLowerCase());\\n    emit([ type ], order);\\n  }\\n}"}, "reports_by_place": {"map": "function(doc) {\\n  if (doc.type === 'data_record' && doc.form) {\\n    var place = doc.contact && doc.contact.parent;\\n    while (place) {\\n      if (place._id) {\\n        emit([ place._id ], doc.reported_date);\\n      }\\n      place = place.parent;\\n    }\\n  }\\n}"}, "tasks_by_contact": {"map": "function(doc) {\\n  if (doc.type === 'task') {\\n    var isTerminalState = ['Cancelled', 'Completed', 'Failed'].indexOf(doc.state) >= 0;\\n    var owner = (doc.owner || '_unassigned');\\n\\n    if (!isTerminalState) {\\n      emit('owner-' + owner);\\n    }\\n\\n    if (doc.requester) {\\n      emit('requester-' + doc.requester);\\n    }\\n\\n    emit(['owner', 'all', owner], { state: doc.state });\\n  }\\n}"}, "contacts_by_phone": {"map": "function(doc) {\\n  if (doc.phone) {\\n    var types = [ 'contact', 'district_hospital', 'health_center', 'clinic', 'person' ];\\n    if (types.indexOf(doc.type) !== -1) {\\n      emit(doc.phone);\\n    }\\n  }\\n}"}, "contacts_by_place": {"map": "function(doc) {\\n  var types = [ 'district_hospital', 'health_center', 'clinic', 'person' ];\\n  var idx;\\n  if (doc.type === 'contact') {\\n    idx = types.indexOf(doc.contact_type);\\n    if (idx === -1) {\\n      idx = doc.contact_type;\\n    }\\n  } else {\\n    idx = types.indexOf(doc.type);\\n  }\\n  if (idx !== -1) {\\n    var place = doc.parent;\\n    var order = idx + ' ' + (doc.name && doc.name.toLowerCase());\\n    while (place) {\\n      if (place._id) {\\n        emit([ place._id ], order);\\n      }\\n      place = place.parent;\\n    }\\n  }\\n}"}, "contacts_by_parent": {"map": "function(doc) {\\n  if (doc.type === 'contact' ||\\n      doc.type === 'clinic' ||\\n      doc.type === 'health_center' ||\\n      doc.type === 'district_hospital' ||\\n      doc.type === 'person') {\\n    var parentId = doc.parent && doc.parent._id;\\n    var type = doc.type === 'contact' ? doc.contact_type : doc.type;\\n    if (parentId) {\\n      emit([parentId, type]);\\n    }\\n  }\\n}"}, "docs_by_id_lineage": {"map": "function(doc) {\\n\\n  var emitLineage = function(contact, depth) {\\n    while (contact && contact._id) {\\n      emit([ doc._id, depth++ ], { _id: contact._id });\\n      contact = contact.parent;\\n    }\\n  };\\n\\n  var types = [ 'contact', 'district_hospital', 'health_center', 'clinic', 'person' ];\\n\\n  if (types.indexOf(doc.type) !== -1) {\\n    // contact\\n    emitLineage(doc, 0);\\n  } else if (doc.type === 'data_record' && doc.form) {\\n    // report\\n    emit([ doc._id, 0 ]);\\n    emitLineage(doc.contact, 1);\\n  }\\n}"}, "reports_by_subject": {"map": "function(doc) {\\n  if (doc.type === 'data_record' && doc.form) {\\n    var emitField = function(obj, field) {\\n      if (obj[field]) {\\n        emit(obj[field], doc.reported_date);\\n      }\\n    };\\n\\n    emitField(doc, 'patient_id');\\n    emitField(doc, 'place_id');\\n    emitField(doc, 'case_id');\\n\\n    if (doc.fields) {\\n      emitField(doc.fields, 'patient_id');\\n      emitField(doc.fields, 'place_id');\\n      emitField(doc.fields, 'case_id');\\n      emitField(doc.fields, 'patient_uuid');\\n      emitField(doc.fields, 'place_uuid');\\n    }\\n  }\\n}"}, "registered_patients": {"map": "// NB: This returns *registrations* for contacts. If contacts are created by\\n//     means other then sending in a registration report (eg created in the UI)\\n//     they will not show up in this view.\\n//\\n//     For a view with all patients by their shortcode, use:\\n//        medic/docs_by_shortcode\\nfunction(doc) {\\n  var patientId = doc.patient_id || (doc.fields && doc.fields.patient_id);\\n  var placeId = doc.place_id || (doc.fields && doc.fields.place_id);\\n\\n  if (!doc.form || doc.type !== 'data_record' || (doc.errors && doc.errors.length)) {\\n    return;\\n  }\\n\\n  if (patientId) {\\n    emit(String(patientId));\\n  }\\n\\n  if (placeId) {\\n    emit(String(placeId));\\n  }\\n}"}, "reports_by_freetext": {"map": "function(doc) {\\n  var skip = [ '_id', '_rev', 'type', 'refid', 'content' ];\\n\\n  var usedKeys = [];\\n  var emitMaybe = function(key, value) {\\n    if (usedKeys.indexOf(key) === -1 && // Not already used\\n        key.length > 2 // Not too short\\n    ) {\\n      usedKeys.push(key);\\n      emit([key], value);\\n    }\\n  };\\n\\n  var emitField = function(key, value, reportedDate) {\\n    if (!key || !value) {\\n      return;\\n    }\\n    key = key.toLowerCase();\\n    if (skip.indexOf(key) !== -1 || /_date$/.test(key)) {\\n      return;\\n    }\\n    if (typeof value === 'string') {\\n      value = value.toLowerCase();\\n      value.split(/\\\\s+/).forEach(function(word) {\\n        emitMaybe(word, reportedDate);\\n      });\\n    }\\n    if (typeof value === 'number' || typeof value === 'string') {\\n      emitMaybe(key + ':' + value, reportedDate);\\n    }\\n  };\\n\\n  if (doc.type === 'data_record' && doc.form) {\\n    Object.keys(doc).forEach(function(key) {\\n      emitField(key, doc[key], doc.reported_date);\\n    });\\n    if (doc.fields) {\\n      Object.keys(doc.fields).forEach(function(key) {\\n        emitField(key, doc.fields[key], doc.reported_date);\\n      });\\n    }\\n    if (doc.contact && doc.contact._id) {\\n      emitMaybe('contact:' + doc.contact._id.toLowerCase(), doc.reported_date);\\n    }\\n  }\\n}"}, "reports_by_validity": {"map": "function(doc) {\\n  if (doc.type === 'data_record' && doc.form) {\\n    emit([!doc.errors || doc.errors.length === 0], doc.reported_date);\\n  }\\n}"}, "contacts_by_freetext": {"map": "function(doc) {\\n  var skip = [ '_id', '_rev', 'type', 'refid', 'geolocation' ];\\n\\n  var usedKeys = [];\\n  var emitMaybe = function(key, value) {\\n    if (usedKeys.indexOf(key) === -1 && // Not already used\\n        key.length > 2 // Not too short\\n    ) {\\n      usedKeys.push(key);\\n      emit([key], value);\\n    }\\n  };\\n\\n  var emitField = function(key, value, order) {\\n    if (!key || !value) {\\n      return;\\n    }\\n    key = key.toLowerCase();\\n    if (skip.indexOf(key) !== -1 || /_date$/.test(key)) {\\n      return;\\n    }\\n    if (typeof value === 'string') {\\n      value = value.toLowerCase();\\n      value.split(/\\\\s+/).forEach(function(word) {\\n        emitMaybe(word, order);\\n      });\\n    }\\n    if (typeof value === 'number' || typeof value === 'string') {\\n      emitMaybe(key + ':' + value, order);\\n    }\\n  };\\n\\n  var types = [ 'district_hospital', 'health_center', 'clinic', 'person' ];\\n  var idx;\\n  if (doc.type === 'contact') {\\n    idx = types.indexOf(doc.contact_type);\\n    if (idx === -1) {\\n      idx = doc.contact_type;\\n    }\\n  } else {\\n    idx = types.indexOf(doc.type);\\n  }\\n\\n  if (idx !== -1) {\\n    var dead = !!doc.date_of_death;\\n    var muted = !!doc.muted;\\n    var order = dead + ' ' + muted + ' ' + idx + ' ' + (doc.name && doc.name.toLowerCase());\\n    Object.keys(doc).forEach(function(key) {\\n      emitField(key, doc[key], order);\\n    });\\n  }\\n}"}, "data_records_by_type": {"map": "function(doc) {\\n  if (doc.type === 'data_record') {\\n    emit(doc.form ? 'report' : 'message');\\n  }\\n}", "reduce": "_count"}, "contacts_by_reference": {"map": "function(doc) {\\n  if (doc.type === 'contact' ||\\n      doc.type === 'clinic' ||\\n      doc.type === 'health_center' ||\\n      doc.type === 'district_hospital' ||\\n      doc.type === 'national_office' ||\\n      doc.type === 'person') {\\n\\n    var emitReference = function(prefix, key) {\\n      emit([ prefix, String(key) ], doc.reported_date);\\n    };\\n\\n    if (doc.place_id) {\\n      emitReference('shortcode', doc.place_id);\\n    }\\n    if (doc.patient_id) {\\n      emitReference('shortcode', doc.patient_id);\\n    }\\n    if (doc.rc_code) {\\n      // need String because rewriter wraps everything in quotes\\n      // keep refid case-insenstive since data is usually coming from SMS\\n      emitReference('external', String(doc.rc_code).toUpperCase());\\n    }\\n  }\\n}"}, "reports_by_verification": {"map": "function(doc) {\\n  if (doc.type === 'data_record' && doc.form) {\\n    emit([doc.verified], doc.reported_date);\\n  }\\n}"}, "contacts_by_last_visited": {"map": "function(doc) {\\n  if (doc.type === 'data_record' &&\\n      doc.form &&\\n      doc.fields &&\\n      doc.fields.visited_contact_uuid) {\\n\\n    var date = doc.fields.visited_date ? Date.parse(doc.fields.visited_date) : doc.reported_date;\\n    if (typeof date !== 'number' || isNaN(date)) {\\n      date = 0;\\n    }\\n    // Is a visit report about a family\\n    emit(doc.fields.visited_contact_uuid, date);\\n  } else if (doc.type === 'contact' ||\\n             doc.type === 'clinic' ||\\n             doc.type === 'health_center' ||\\n             doc.type === 'district_hospital' ||\\n             doc.type === 'person') {\\n    // Is a contact type\\n    emit(doc._id, 0);\\n  }\\n}", "reduce": "_stats"}, "messages_by_contact_date": {"map": "function(doc) {\\n\\n  var emitMessage = function(doc, contact, phone) {\\n    var id = (contact && contact._id) || phone || doc._id;\\n    emit([ id, doc.reported_date ], {\\n      id: doc._id,\\n      date: doc.reported_date,\\n      contact: contact && contact._id\\n    });\\n  };\\n\\n  if (doc.type === 'data_record' && !doc.form) {\\n    if (doc.kujua_message && doc.tasks) {\\n      // outgoing\\n      doc.tasks.forEach(function(task) {\\n        var message = task.messages && task.messages[0];\\n        if(message) {\\n          emitMessage(doc, message.contact, message.to);\\n        }\\n      });\\n    } else if (doc.sms_message) {\\n      // incoming\\n      emitMessage(doc, doc.contact, doc.from);\\n    }\\n  }\\n}", "reduce": "function(key, values) {\\n  var latest = { date: 0 };\\n  values.forEach(function(value) {\\n    if (value.date > latest.date) {\\n      latest = value;\\n    }\\n  });\\n  return latest;\\n}"}, "contacts_by_type_freetext": {"map": "function(doc) {\\n  var skip = [ '_id', '_rev', 'type', 'refid', 'geolocation' ];\\n\\n  var usedKeys = [];\\n  var emitMaybe = function(type, key, value) {\\n    if (usedKeys.indexOf(key) === -1 && // Not already used\\n        key.length > 2 // Not too short\\n    ) {\\n      usedKeys.push(key);\\n      emit([ type, key ], value);\\n    }\\n  };\\n\\n  var emitField = function(type, key, value, order) {\\n    if (!key || !value) {\\n      return;\\n    }\\n    key = key.toLowerCase();\\n    if (skip.indexOf(key) !== -1 || /_date$/.test(key)) {\\n      return;\\n    }\\n    if (typeof value === 'string') {\\n      value = value.toLowerCase();\\n      value.split(/\\\\s+/).forEach(function(word) {\\n        emitMaybe(type, word, order);\\n      });\\n    }\\n    if (typeof value === 'number' || typeof value === 'string') {\\n      emitMaybe(type, key + ':' + value, order);\\n    }\\n  };\\n\\n  var types = [ 'district_hospital', 'health_center', 'clinic', 'person' ];\\n  var idx;\\n  var type;\\n  if (doc.type === 'contact') {\\n    type = doc.contact_type;\\n    idx = types.indexOf(type);\\n    if (idx === -1) {\\n      idx = type;\\n    }\\n  } else {\\n    type = doc.type;\\n    idx = types.indexOf(type);\\n  }\\n  if (idx !== -1) {\\n    var dead = !!doc.date_of_death;\\n    var muted = !!doc.muted;\\n    var order = dead + ' ' + muted + ' ' + idx + ' ' + (doc.name && doc.name.toLowerCase());\\n    Object.keys(doc).forEach(function(key) {\\n      emitField(type, key, doc[key], order);\\n    });\\n  }\\n}"}, "total_clinics_by_facility": {"map": "function(doc) {\\n  var districtId = doc.parent && doc.parent.parent && doc.parent.parent._id;\\n  if (doc.type === 'clinic' || (doc.type === 'contact' && districtId)) {\\n    var healthCenterId = doc.parent && doc.parent._id;\\n    emit([ districtId, healthCenterId, doc._id, 0 ]);\\n    if (doc.contact && doc.contact._id) {\\n      emit([ districtId, healthCenterId, doc._id, 1 ], { _id: doc.contact._id });\\n    }\\n    var index = 2;\\n    var parent = doc.parent;\\n    while(parent) {\\n      if (parent._id) {\\n        emit([ districtId, healthCenterId, doc._id, index++ ], { _id: parent._id });\\n      }\\n      parent = parent.parent;\\n    }\\n  }\\n}"}}, "version": "4.21.1.16656970076", "build_info": {"time": "2025-07-31T18:32:53.572Z", "build": "4.21.1.16656970076", "author": "npm on runner", "version": "4.21.1", "namespace": "medic", "application": "medic", "base_version": "4.21.1", "schema_version": 2}, "deploy_info": {"user": "", "timestamp": 1756818571633, "upgrade_log_id": "upgrade_log:1756818495031:4.21.1"}, "validate_doc_update": "function(newDoc, oldDoc, userCtx, secObj) {\\n  /*\\n    LOCAL DOCUMENT VALIDATION\\n\\n    This is for validating document structure, irrespective of authority, so it\\n    can be run both on couchdb and pouchdb (where you are technically admin).\\n\\n    For validations around authority check lib/validate_doc_update.js, which is\\n    only run on the server.\\n  */\\n\\n  var _err = function(msg) {\\n    throw({ forbidden: msg });\\n  };\\n\\n  var hasRole = function(roles, role) {\\n    if (roles) {\\n      for (var i = 0; i < roles.length; i++) {\\n        if (roles[i] === role) {\\n          return true;\\n        }\\n      }\\n    }\\n    return false;\\n  };\\n\\n  var isDbAdmin = function(userCtx, secObj) {\\n    if (hasRole(userCtx.roles, '_admin')) {\\n      return true;\\n    }\\n\\n    if (secObj.admins && secObj.admins.names && secObj.admins.names.indexOf(userCtx.name) !== -1) {\\n      return true;\\n    }\\n\\n    if (secObj.admins && secObj.admins.roles) {\\n      for (var i = 0; i < userCtx.roles.length; i++) {\\n        if (hasRole(secObj.admins.roles, userCtx.roles[i])) {\\n          return true;\\n        }\\n      }\\n    }\\n\\n    return false;\\n  };\\n\\n  /**\\n   * Ensure that type='form' documents are created with correctly formatted _id\\n   * property.\\n   */\\n  var validateForm = function() {\\n    var id_parts = newDoc._id.split(':');\\n    var prefix = id_parts[0];\\n    var form_id = id_parts.slice(1).join(':');\\n    if (prefix !== 'form') {\\n      _err('_id property must be prefixed with \\"form:\\". e.g. \\"form:registration\\"');\\n    }\\n    if (!form_id) {\\n      _err('_id property must define a value after \\"form:\\". e.g. \\"form:registration\\"');\\n    }\\n    if (newDoc._id !== newDoc._id.toLowerCase()) {\\n      _err('_id property must be lower case. e.g. \\"form:registration\\"');\\n    }\\n  };\\n\\n  var validateUserSettings = function() {\\n    var id_parts = newDoc._id.split(':');\\n    var prefix = id_parts[0];\\n    var username = id_parts.slice(1).join(':');\\n    var idExample = ' e.g. \\"org.couchdb.user:sally\\"';\\n    if (prefix !== 'org.couchdb.user') {\\n      _err('_id must be prefixed with \\"org.couchdb.user:\\".' + idExample);\\n    }\\n    if (!username) {\\n      _err('_id must define a value after \\"org.couchdb.user:\\".' + idExample);\\n    }\\n    if (newDoc._id !== newDoc._id.toLowerCase()) {\\n      _err('_id must be lower case.' + idExample);\\n    }\\n    if (typeof newDoc.name === 'undefined' || newDoc.name !== username) {\\n      _err('name property must be equivalent to username.' + idExample);\\n    }\\n    if (newDoc.name.toLowerCase() !== username.toLowerCase()) {\\n      _err('name must be equivalent to username');\\n    }\\n    if (typeof newDoc.known !== 'undefined' && typeof newDoc.known !== 'boolean') {\\n      _err('known is not a boolean.');\\n    }\\n    if (typeof newDoc.roles !== 'object') {\\n      _err('roles is a required array');\\n    }\\n  };\\n\\n  var authorizeUserSettings = function() {\\n    if (!oldDoc) {\\n      _err('You are not authorized to create user-settings');\\n    }\\n    if (typeof oldDoc.roles !== 'object') {\\n      _err('You are not authorized to edit roles');\\n    }\\n    if (newDoc.roles.length !== oldDoc.roles.length) {\\n      _err('You are not authorized to edit roles');\\n    }\\n    for (var i = 0; i < oldDoc.roles.length; i++) {\\n      if (oldDoc.roles[i] !== newDoc.roles[i]) {\\n        _err('You are not authorized to edit roles');\\n      }\\n    }\\n  }\\n\\n  // admins can do anything\\n  if (isDbAdmin(userCtx, secObj)) {\\n    return;\\n  }\\n  if (userCtx.facility_id === newDoc._id ||\\n    (Array.isArray(userCtx.facility_id) && userCtx.facility_id.includes(newDoc._id ))\\n  ) {\\n    _err('You are not authorized to edit your own place');\\n  }\\n  if (newDoc.type === 'form') {\\n    validateForm();\\n  }\\n  if (newDoc.type === 'user-settings') {\\n    validateUserSettings();\\n    authorizeUserSettings();\\n  }\\n\\n  log(\\n    'medic-client validate_doc_update passed for User \\"' + userCtx.name +\\n    '\\" changing document \\"' +  newDoc._id + '\\"'\\n  );\\n}"}
